def is_prohibited_product_title(title: str) -> bool:
    """Reject medicines, pharmacy items, vitamins, and dietary supplements from affiliate posts."""
    normalized = str(title or "").lower()
    normalized = re.sub(r"[\u200b-\u200f\ufeff]", "", normalized)
    normalized = normalized.replace("ي", "ی").replace("ك", "ک").replace("\u200c", " ")
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return bool(EXCLUDED_HEALTH_PRODUCT_RE.search(normalized))


def normalize_digits(value: str) -> str:
    return (value or "").translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩٬٫", "01234567890123456789,."))


def safe_product_url(raw: str) -> str:
    """Canonicalize supported retailer product URLs; reject search/category and foreign hosts."""
    try:
        p = urlsplit((raw or "").strip())
    except Exception:
        return ""
    host = (p.hostname or "").lower()
    if p.scheme not in {"http", "https"}:
        return ""
    if host == "digikala.com" or host.endswith(".digikala.com"):
        match = re.search(r"/product/(dkp-\d+)", p.path, re.I)
        return f"https://www.digikala.com/product/{match.group(1).lower()}/" if match else ""
    if host == "snappshop.ir" or host.endswith(".snappshop.ir"):
        match = re.fullmatch(r"/product/(snp-\d+)/?", p.path, re.I)
        return f"https://snappshop.ir/product/{match.group(1).lower()}" if match else ""
    return ""


def product_id(url: str) -> str:
    match = re.search(r"/product/((?:dkp|snp)-\d+)", url or "", re.I)
    return match.group(1).lower() if match else ""


def product_merchant(url_or_affiliate: str) -> str:
    """Return a storefront label only for destinations accepted by safe_product_url."""
    value = str(url_or_affiliate or "").strip()
    try:
        parsed = urlsplit(value)
        if (parsed.hostname or "").lower() == "aflo.ir":
            destinations = parse_qs(parsed.query, keep_blank_values=True).get("p", [])
            value = destinations[0] if len(destinations) == 1 else ""
    except Exception:
        return "دیجی‌کالا"
    canonical = safe_product_url(value)
    return "اسنپ‌شاپ" if canonical and product_id(canonical).startswith("snp-") else "دیجی‌کالا"


def purchase_button_label(affiliate_url: str) -> str:
    return f"🛍️ مشاهده و خرید از {product_merchant(affiliate_url)}"


AFFILIO_REDIRECT_PLACEHOLDER = "{redirect_to}"
DEFAULT_AFFILIO_PUBLIC_LINK_TEMPLATE = "https://aflo.ir/QekEYTRg?p={redirect_to}"


def build_affilio_tracking_link(product_url: str, template: str | None = None) -> str:
    """Build affiliate URLs only through the user's confirmed publisher-specific public link.

    The known template is deliberately fixed. Legacy direct URLs and other reusable
    templates are rejected so a stale secret/configuration cannot silently switch routes.
    """
    canonical = safe_product_url(product_url)
    if not canonical:
        return ""

    # Compatibility for callers/tests that pass a template: accept only the exact
    # publisher-owned template confirmed by the user, never another affiliate route.
    if template is not None and template.strip() != DEFAULT_AFFILIO_PUBLIC_LINK_TEMPLATE:
        return ""
    template = DEFAULT_AFFILIO_PUBLIC_LINK_TEMPLATE

    parsed = urlsplit(template)
    query = parse_qs(parsed.query, keep_blank_values=True)
    if (
        parsed.scheme != "https"
        or (parsed.hostname or "").lower() != "aflo.ir"
        or parsed.path != "/QekEYTRg"
        or query.get("p") != [AFFILIO_REDIRECT_PLACEHOLDER]
        or parsed.fragment
        or parsed.username
        or parsed.password
    ):
        return ""

    # Quote the whole destination once as the value of p; retain no arbitrary product query params.
    result = template.replace(AFFILIO_REDIRECT_PLACEHOLDER, quote(canonical, safe=""))
    try:
        built = urlsplit(result)
        destinations = parse_qs(built.query, keep_blank_values=True).get("p", [])
    except Exception:
        return ""
    if (
        built.scheme != "https"
        or (built.hostname or "").lower() != "aflo.ir"
        or built.path != "/QekEYTRg"
        or len(destinations) != 1
        or safe_product_url(destinations[0]) != canonical
        or AFFILIO_REDIRECT_PLACEHOLDER in result
    ):
        return ""
    return result


def _affiliate_destination_matches_product(affiliate_url: str, canonical_product_url: str) -> bool:
    """Accept only the confirmed OfferChin public link for the same DigiKala or SnappShop product."""
    canonical = safe_product_url(canonical_product_url)
    if not canonical:
        return False
    try:
        parsed = urlsplit(str(affiliate_url or "").strip())
        destinations = parse_qs(parsed.query, keep_blank_values=True).get("p", [])
    except Exception:
        return False
    return (
        parsed.scheme == "https"
        and (parsed.hostname or "").lower() == "aflo.ir"
        and parsed.path == "/QekEYTRg"
        and len(destinations) == 1
        and safe_product_url(destinations[0]) == canonical
    )


def _is_valid_affilio_tracking_url(affiliate_url: str) -> bool:
    """Validate the exact public Affilio template and its DigiKala or SnappShop destination."""
    try:
        parsed = urlsplit(str(affiliate_url or "").strip())
        destinations = parse_qs(parsed.query, keep_blank_values=True).get("p", [])
    except Exception:
        return False
    return bool(
        len(destinations) == 1
        and parsed.scheme == "https"
        and (parsed.hostname or "").lower() == "aflo.ir"
        and parsed.path == "/QekEYTRg"
        and _affiliate_destination_matches_product(str(affiliate_url or ""), destinations[0])
    )


def build_click_tracking_link(
    product_url: str,
    affiliate_url: str,
    base_url: str | None = None,
    source: str = "unknown",
) -> str:
    """Wrap a verified Affilio link for privacy-preserving product/source click counts."""
    canonical = safe_product_url(product_url)
    original = str(affiliate_url or "").strip()
    pid = product_id(canonical) if canonical else ""
    if not canonical or not original or not re.fullmatch(r"(?:dkp-\d{1,12}|snp-\d{1,20})", pid):
        return original
    if not _affiliate_destination_matches_product(original, canonical):
        return original

    base = (base_url if base_url is not None else AFFILIO_CLICK_TRACKER_BASE_URL).strip().rstrip("/")
    try:
        parsed_base = urlsplit(base)
    except Exception:
        return original
    if (
        parsed_base.scheme != "https"
        or not parsed_base.netloc
        or parsed_base.query
        or parsed_base.fragment
        or parsed_base.username
        or parsed_base.password
    ):
        return original

    allowed_sources = {"telegram", "bale", "youtube", "aparat"}
    source_value = str(source or "unknown").strip().lower()
    if source_value not in allowed_sources:
        source_value = "unknown"
    return f"{base}/p/{pid}?u={quote(original, safe='')}&src={quote(source_value, safe='')}"


def _click_tracker_is_healthy() -> bool:
    """Probe health and both retailer redirect paths without recording click events."""
    global _CLICK_TRACKER_HEALTH_CACHE
    if _CLICK_TRACKER_HEALTH_CACHE is not None:
        return _CLICK_TRACKER_HEALTH_CACHE

    base = AFFILIO_CLICK_TRACKER_BASE_URL.strip().rstrip("/")
    try:
        parsed_base = urlsplit(base)
        if (
            parsed_base.scheme != "https"
            or not parsed_base.netloc
            or parsed_base.query
            or parsed_base.fragment
            or parsed_base.username
            or parsed_base.password
        ):
            raise RuntimeError("tracker_base_invalid")

        health = SESSION.get(
            f"{base}/health",
            headers={"Accept": "application/json", "User-Agent": "OfferChinClickTrackerProbe/1.0"},
            timeout=(3, 5),
        )
        health.raise_for_status()
        health_payload = health.json()
        if health_payload.get("ok") is not True or health_payload.get("clickStoreReady") is not True:
            raise RuntimeError("tracker_health_not_ready")

        # HEAD never writes a click event. Both retailer paths must validate before tracking is enabled.
        probes = (
            ("https://www.digikala.com/product/dkp-15970075/", "telegram"),
            ("https://snappshop.ir/product/snp-2097083854", "bale"),
        )
        for product_url, source in probes:
            affiliate = build_affilio_tracking_link(product_url)
            if not _is_valid_affilio_tracking_url(affiliate):
                raise RuntimeError("tracker_probe_affilio_link_invalid")
            wrapped = build_click_tracking_link(product_url, affiliate, base, source=source)
            probe = SESSION.head(
                wrapped,
                headers={"User-Agent": "OfferChinClickTrackerProbe/1.0"},
                allow_redirects=False,
                timeout=(3, 5),
            )
            location = urlsplit(str(probe.headers.get("Location") or ""))
            if (
                probe.status_code != 302
                or (location.hostname or "").lower() != "aflo.ir"
                or location.path != "/QekEYTRg"
                or parse_qs(location.query, keep_blank_values=True).get("p") != [safe_product_url(product_url)]
            ):
                raise RuntimeError(f"tracker_redirect_probe_failed_{probe.status_code}")

        _CLICK_TRACKER_HEALTH_CACHE = True
        print("CLICK_TRACKER_READY retailers=digikala,snappshop source_attribution=enabled")
    except Exception as exc:
        _CLICK_TRACKER_HEALTH_CACHE = False
        print(f"CLICK_TRACKER_BYPASS reason={type(exc).__name__}; direct_affilio_links_preserved")
    return _CLICK_TRACKER_HEALTH_CACHE


def tracked_affiliate_button_url(affiliate_url: str, source: str) -> str:
    """Return the verified Affilio purchase URL unchanged; click-tracker redirects are disabled."""
    original = str(affiliate_url or "").strip()
    return original if _is_valid_affilio_tracking_url(original) else ""


def _walk_dicts(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from _walk_dicts(child)
    elif isinstance(value, list):
        for child in value:
            yield from _walk_dicts(child)


def _as_list(value):
    if value is None:
        return []
    return value if isinstance(value, list) else [value]


def _money_to_toman(raw, currency=""):
    if raw is None:
        return None
    raw_s = normalize_digits(str(raw)).strip().replace(",", "").replace("٬", "").replace("٫", ".")
    match = re.search(r"\d+(?:\.\d+)?", raw_s)
    if not match:
        return None
    try:
        amount = float(match.group(0))
    except ValueError:
        return None
    currency = str(currency or "").upper()
    # JSON-LD may express Iranian prices in IRR (rials), while visible page/meta
    # values are usually already in toman. Convert only when currency says IRR.
    if currency == "IRR":
        amount /= 10
    result = int(round(amount))
    return result if result >= 1000 else None


def _clean_title(value):
    value = BeautifulSoup(str(value or ""), "html.parser").get_text(" ", strip=True)
    value = re.sub(r"\s+", " ", html.unescape(value)).strip()
    value = re.sub(r"\s*[|–-]\s*(?:دیجی ?کالا|خرید|قیمت).*$", "", value, flags=re.I)
    return value[:180]


def _availability_from_page(soup, product_obj=None):
    # Structured product/offer fields are more reliable than generic page text.
    for obj in [product_obj] if isinstance(product_obj, dict) else []:
        offers = _as_list(obj.get("offers"))
        for offer in offers:
            if not isinstance(offer, dict):
                continue
            availability = str(offer.get("availability", "")).lower().rsplit("/", 1)[-1]
            availability = availability.replace("_", "").replace("-", "")
            if availability in {"outofstock", "soldout", "discontinued", "preorder"}:
                return "out_of_stock", "schema.org"
            if availability in {"instock", "limitedavailability", "onlineonly"}:
                return "in_stock", "schema.org"

    # Some pages expose non-schema stock keys in serialized page data.
    raw_html = str(soup)
    low = raw_html.lower()
    if re.search(r'"(?:stockquantity|inventoryquantity|availablequantity)"\s*:\s*0(?:\D|$)', low):
        return "out_of_stock", "page_data_quantity"
    for key in ("\"hasstock\":false", "\"isavailable\":false", "\"available\":false"):
        if key in low:
            return "out_of_stock", "page_data_flag"
    for key in ("\"hasstock\":true", "\"isavailable\":true", "\"available\":true"):
        if key in low:
            return "in_stock", "page_data_flag"

    text = re.sub(r"\s+", " ", soup.get_text(" ", strip=True)).lower()
    text = text.replace("ي", "ی").replace("ك", "ک")
    if any(term in text for term in (
        "اتمام موجودی", "ناموجود", "موجودی ندارد", "موجود نیست",
        "قابل سفارش نیست", "out of stock", "sold out", "unavailable",
    )):
        return "out_of_stock", "visible_text"
    if any(term in text for term in (
        "موجود در انبار", "در انبار موجود است", "قابل سفارش",
        "افزودن به سبد خرید", "in stock",
    )):
        # The page must state a positive signal explicitly; mere existence of a
        # generic "buy" word is not enough.
        if "قابل سفارش نیست" not in text:
            return "in_stock", "visible_text"
    return "unknown", "no_reliable_stock_signal"


def parse_product_page(url: str, page_html: str) -> dict:
    soup = BeautifulSoup(page_html or "", "html.parser")
    meta = {}
    for node in soup.select("meta"):
        key = (node.get("property") or node.get("name") or node.get("itemprop") or "").strip().lower()
        content = node.get("content")
        if key and content:
            meta[key] = html.unescape(content.strip())

    product_obj = None
    for node in soup.select('script[type="application/ld+json"]'):
        try:
            data = json.loads(node.string or node.get_text())
        except (ValueError, TypeError):
            continue
        for obj in _walk_dicts(data):
            types = obj.get("@type", [])
            if isinstance(types, str):
                types = [types]
            if any(str(t).lower() == "product" for t in types) and (obj.get("name") or obj.get("offers")):
                product_obj = obj
                break
        if product_obj:
            break

    title = ""
    image = ""
    current_price = None
    original_price = None
    rating = None
    review_count = 0
    currency = ""

    if product_obj:
        title = _clean_title(product_obj.get("name"))
        images = _as_list(product_obj.get("image"))
        if images and isinstance(images[0], str):
            image = images[0]
        offers = _as_list(product_obj.get("offers"))
        for offer in offers:
            if not isinstance(offer, dict):
                continue
            currency = str(offer.get("priceCurrency", currency or ""))
            value = _money_to_toman(offer.get("price") or offer.get("lowPrice"), currency)
            if value and (current_price is None or value < current_price):
                current_price = value
            specs = _as_list(offer.get("priceSpecification"))
            for spec in specs:
                if not isinstance(spec, dict):
                    continue
                spec_value = _money_to_toman(spec.get("price"), currency)
                type_text = " ".join(str(spec.get(k, "")) for k in ("priceType", "name", "@type")).lower()
                if spec_value and any(k in type_text for k in ("list", "regular", "strike", "original", "high")):
                    original_price = max(original_price or 0, spec_value)
        aggregate = product_obj.get("aggregateRating")
        if isinstance(aggregate, dict):
            try:
                rating = float(normalize_digits(str(aggregate.get("ratingValue", ""))))
            except ValueError:
                rating = None
            try:
                review_count = int(float(normalize_digits(str(aggregate.get("reviewCount") or aggregate.get("ratingCount") or 0))))
            except ValueError:
                review_count = 0

    title = title or _clean_title(meta.get("og:title") or meta.get("twitter:title") or meta.get("title") or "")
    if not is_publishable_product_title(title):
        h1 = soup.find("h1")
        heading_title = _clean_title(h1.get_text(" ", strip=True) if h1 else "")
        title = heading_title if is_publishable_product_title(heading_title) else ""
    image = image or meta.get("og:image") or meta.get("twitter:image") or meta.get("twitter:image:src") or ""
    image = urljoin(url, image) if image else ""

    if current_price is None:
        for key in ("product:price:amount", "og:price:amount", "product:price", "price"):
            if meta.get(key):
                current_price = _money_to_toman(meta[key], meta.get("product:price:currency") or meta.get("pricecurrency") or "")
                if current_price:
                    break

    if original_price is None:
        for key in ("product:original_price", "product:price:standard_amount", "og:price:standard_amount", "price:regular"):
            if meta.get(key):
                original_price = _money_to_toman(meta[key], meta.get("product:price:currency") or "")
                if original_price:
                    break

    # Public page text as a limited fallback, only when it contains explicit toman labels.
    visible = soup.get_text(" ", strip=True)
    visible_norm = normalize_digits(visible).replace("٬", ",").replace("،", ",")
    explicit_prices = []
    for match in re.finditer(r"(?<!\d)(\d{1,3}(?:,\d{3})+|\d{4,})(?!\d)\s*(?:تومان|تومن)", visible_norm):
        amount = _money_to_toman(match.group(1))
        if amount:
            explicit_prices.append(amount)
    explicit_prices = list(dict.fromkeys(explicit_prices))
    if current_price is None and explicit_prices:
        current_price = explicit_prices[0]
    if original_price is None and len(explicit_prices) > 1:
        original_price = max(explicit_prices)

    if current_price and original_price and original_price <= current_price:
        original_price = None
    availability, availability_source = _availability_from_page(soup, product_obj)
    return {
        "product_id": product_id(url),
        "product_url": safe_product_url(url),
        "title": title,
        "image_url": image,
        "current_price": current_price,
        "original_price": original_price,
        "rating": rating,
        "review_count": max(0, review_count),
        "availability": availability,
        "availability_source": availability_source,
        "checked_at": datetime.now(timezone.utc).isoformat(),
    }


def fetch_page(url: str):
    response = SESSION.get(url, timeout=HTTP_TIMEOUT, allow_redirects=True)
    response.raise_for_status()
    if len(response.content) > 5_000_000:
        raise RuntimeError("Page exceeded 5 MB safety limit")
    return response.url, response.text


def _textual_availability(value):
    text = str(value or "").lower().replace("_", "").replace("-", "").rsplit("/", 1)[-1]
    if any(token in text for token in ("outofstock", "soldout", "notavailable", "discontinued", "ناموجود")):
        return "out_of_stock"
    if any(token in text for token in ("instock", "marketable", "limitedavailability", "onlineonly")):
        return "in_stock"
    return "unknown"


def _api_product_url(obj):
    # Never synthesize a product URL from a generic numeric "id": API payloads
    # also contain category, seller, campaign, and recommendation IDs.
    for key in ("url", "product_url", "web_url", "canonical_url", "productUrl"):
        raw = obj.get(key)
        if isinstance(raw, dict):
            raw = raw.get("uri") or raw.get("url") or ""
        if isinstance(raw, str):
            candidate = safe_product_url(urljoin("https://www.digikala.com/", raw))
            if candidate:
                return candidate
    return ""


def api_search_product_urls(payload):
    """Read the product array only; never confuse filter/category IDs with product IDs."""
    data = payload.get("data", {}) if isinstance(payload, dict) else {}
    product_items = data.get("products", []) if isinstance(data, dict) else []
    found = []
    for obj in product_items if isinstance(product_items, list) else []:
        if not isinstance(obj, dict):
            continue
        title = obj.get("title_fa") or obj.get("product_title") or obj.get("title")
        raw_id = obj.get("id") or obj.get("product_id")
        product_shape = any(k in obj for k in ("default_variant", "variants", "images", "product_type", "status"))
        if not title or not product_shape or not is_publishable_product_title(title):
            continue
        candidate = _api_product_url(obj)
        if not candidate and (isinstance(raw_id, int) or (isinstance(raw_id, str) and raw_id.isdigit())):
            candidate = safe_product_url(f"https://www.digikala.com/product/dkp-{int(raw_id)}/")
        if candidate and candidate not in found:
            found.append(candidate)
        if len(found) >= MAX_PER_QUERY:
            break
    return found


def _offer_discount_percent(obj: dict) -> int:
    """Get the retailer-declared discount or derive one from current/list prices."""
    sources = []
    if isinstance(obj.get("price"), dict):
        sources.append(obj["price"])
    variant = obj.get("default_variant")
    if isinstance(variant, dict) and isinstance(variant.get("price"), dict):
        sources.append(variant["price"])
    sources.append(obj)
    for source in sources:
        raw = source.get("discount_percent")
        try:
            discount = int(float(normalize_digits(str(raw))))
            if 0 < discount <= 100:
                return discount
        except (TypeError, ValueError, OverflowError):
            pass
        current = None
        original = None
        for key in ("selling_price_toman", "selling_price_tooman", "price_toman"):
            if source.get(key) is not None:
                current = _money_to_toman(source[key], "IRT")
                if current:
                    break
        if current is None:
            for key in ("selling_price", "selling_price_rial", "price"):
                if source.get(key) is not None:
                    current = _money_to_toman(source[key], "IRR")
                    if current:
                        break
        for key in ("rrp_price_toman", "original_price_toman", "list_price_toman"):
            if source.get(key) is not None:
                original = _money_to_toman(source[key], "IRT")
                if original:
                    break
        if original is None:
            for key in ("rrp_price", "rrp_price_rial", "original_price", "regular_price"):
                if source.get(key) is not None:
                    original = _money_to_toman(source[key], "IRR")
                    if original:
                        break
        if current and original and original > current:
            return max(1, min(100, round(100 * (original - current) / original)))
    return 0


def _offer_savings_toman(obj: dict) -> int:
    sources = []
    if isinstance(obj.get("price"), dict):
        sources.append(obj["price"])
    variant = obj.get("default_variant")
    if isinstance(variant, dict) and isinstance(variant.get("price"), dict):
        sources.append(variant["price"])
    sources.append(obj)
    for source in sources:
        current = None
        original = None
        for key in ("selling_price_toman", "selling_price_tooman", "price_toman"):
            if source.get(key) is not None:
                current = _money_to_toman(source[key], "IRT")
                if current:
                    break
        if current is None:
            for key in ("selling_price", "selling_price_rial", "price"):
                if source.get(key) is not None:
                    current = _money_to_toman(source[key], "IRR")
                    if current:
                        break
        for key in ("rrp_price_toman", "original_price_toman", "list_price_toman"):
            if source.get(key) is not None:
                original = _money_to_toman(source[key], "IRT")
                if original:
                    break
        if original is None:
            for key in ("rrp_price", "rrp_price_rial", "original_price", "regular_price"):
                if source.get(key) is not None:
                    original = _money_to_toman(source[key], "IRR")
                    if original:
                        break
        if current and original and original > current:
            return int(original - current)
    return 0


def _parse_deal_expiry_value(value):
    """Parse an explicitly absolute offer deadline into a UTC ISO timestamp."""
    return parse_absolute_deadline(value) or None


def extract_deal_expiry(obj: dict, now: datetime | None = None) -> str:
    """Use the shared site-countdown parser for both discovery and caption refresh."""
    return extract_offer_expiry(obj, now=now)


def api_incredible_offer_product_candidates(payload, now: datetime | None = None) -> list[dict]:
    """Extract and rank product URLs from Digikala's public Incredible Offers feed."""
    by_url = {}
    for obj in _walk_dicts(payload):
        if not isinstance(obj, dict):
            continue
        title = obj.get("title_fa") or obj.get("product_title") or obj.get("title")
        raw_id = obj.get("id") or obj.get("product_id")
        has_product_shape = bool(title) and any(
            key in obj for key in ("url", "default_variant", "variants", "price", "status", "product_type", "is_incredible")
        )
        if (
            not has_product_shape
            or is_prohibited_product_title(title)
            or not is_publishable_product_title(title)
        ):
            continue
        status = str(obj.get("status", "")).lower()
        if status and status not in {"marketable", "active", "available"}:
            continue
        discount = _offer_discount_percent(obj)
        if discount <= 0:
            continue
        candidate = _api_product_url(obj)
        if not candidate and (isinstance(raw_id, int) or (isinstance(raw_id, str) and raw_id.isdigit())):
            candidate = safe_product_url(f"https://www.digikala.com/product/dkp-{int(raw_id)}/")
        if not candidate:
            continue
        review_count = 0
        rating = 0.0
        metric_sources = [obj]
        for metric_key in ("aggregateRating", "rating_info", "statistics", "stats", "default_variant"):
            nested = obj.get(metric_key)
            if isinstance(nested, dict):
                metric_sources.append(nested)
        for source in metric_sources:
            if not review_count:
                for key in ("review_count", "reviews_count", "reviewCount", "comments_count", "comment_count", "rate_count"):
                    raw = source.get(key)
                    if raw is None:
                        continue
                    try:
                        review_count = max(0, int(float(normalize_digits(str(raw)))))
                    except (TypeError, ValueError, OverflowError):
                        continue
                    if review_count:
                        break
            if not rating:
                for key in ("rating", "rating_value", "ratingValue", "average_rating", "rate"):
                    raw = source.get(key)
                    if isinstance(raw, dict):
                        raw = raw.get("value") or raw.get("average") or raw.get("rate")
                    try:
                        rating = float(normalize_digits(str(raw)))
                    except (TypeError, ValueError, OverflowError):
                        continue
                    if rating:
                        break
        row = {
            "product_url": candidate,
            "title": _clean_title(title),
            "discount_percent": discount,
            "savings_toman": _offer_savings_toman(obj),
            "review_count": review_count,
            "rating": rating,
            "deal_expires_at": extract_deal_expiry(obj, now=now),
        }
        old = by_url.get(candidate)
        if not old:
            by_url[candidate] = row
            continue

        # Multiple nested nodes can describe the same product: the highest
        # discount node may omit the card's expiry timer. Merge the timer before
        # replacing the ranking row, or the best-priced node erases the only
        # deadline source and the scheduler cannot publish anything.
        merged_deadline = str(old.get("deal_expires_at") or row.get("deal_expires_at") or "").strip()
        if (row["discount_percent"], row["savings_toman"]) > (old["discount_percent"], old["savings_toman"]):
            replacement = dict(row)
            if merged_deadline:
                replacement["deal_expires_at"] = merged_deadline
            by_url[candidate] = replacement
        elif merged_deadline and not old.get("deal_expires_at"):
            by_url[candidate]["deal_expires_at"] = merged_deadline
    return sorted(
        by_url.values(),
        key=lambda row: (row["discount_percent"], row["savings_toman"]),
        reverse=True,
    )


def api_incredible_offer_product_urls(payload) -> list[str]:
    """Return the URLs of discounted products, highest listed discount first."""
    return [row["product_url"] for row in api_incredible_offer_product_candidates(payload)]


def _search_api_sample(payload):
    data = payload.get("data", {}) if isinstance(payload, dict) else {}
    products = data.get("products", []) if isinstance(data, dict) else []
    if isinstance(products, list) and products:
        out = []
        for obj in products[:6]:
            if not isinstance(obj, dict):
                continue
            image_value = obj.get("images")
            image_keys = list(image_value.keys())[:8] if isinstance(image_value, dict) else type(image_value).__name__
            variant = obj.get("default_variant") if isinstance(obj.get("default_variant"), dict) else {}
            out.append({
                "id": obj.get("id"),
                "url": obj.get("url"),
                "title": _clean_title(obj.get("title_fa") or obj.get("title_en") or obj.get("name") or "")[:70],
                "keys": list(obj.keys())[:26],
                "status": obj.get("status"),
                "variant_keys": list(variant.keys())[:22],
                "images_shape": image_keys,
                "url_type": type(obj.get("url")).__name__,
                "url_parse": safe_product_url(urljoin("https://www.digikala.com/", obj.get("url") if isinstance(obj.get("url"), str) else "")),
            })
        return out
    sample = []
    for obj in _walk_dicts(payload):
        title = obj.get("title_fa") or obj.get("product_title") or obj.get("title") or obj.get("name")
        if not title:
            continue
        sample.append({
            "id": obj.get("product_id") or obj.get("id"),
            "url": obj.get("url") or obj.get("product_url") or obj.get("web_url") or obj.get("canonical_url"),
            "title": _clean_title(title)[:55],
            "keys": list(obj.keys())[:18],
        })
        if len(sample) >= 6:
            break
    return sample


def _api_structure(value, path="$", depth=0, max_depth=5, found=None):
    if found is None:
        found = []
    if depth >= max_depth or len(found) >= 30:
        return found
    if isinstance(value, dict):
        if depth <= 2:
            found.append({"path": path, "type": "dict", "keys": list(value.keys())[:28]})
        for key, child in value.items():
            if isinstance(child, list):
                first = child[0] if child else None
                found.append({
                    "path": f"{path}.{key}",
                    "type": "list",
                    "length": len(child),
                    "first_type": type(first).__name__ if first is not None else "empty",
                    "first_keys": list(first.keys())[:24] if isinstance(first, dict) else [],
                })
                if child and isinstance(first, (dict, list)):
                    _api_structure(first, f"{path}.{key}[0]", depth + 1, max_depth, found)
            elif isinstance(child, dict):
                _api_structure(child, f"{path}.{key}", depth + 1, max_depth, found)
            if len(found) >= 30:
                break
    elif isinstance(value, list) and value:
        _api_structure(value[0], f"{path}[0]", depth + 1, max_depth, found)
    return found


def _image_from_api(value):
    if isinstance(value, str):
        v = value.strip()
        if v.startswith("//"):
            v = "https:" + v
        if v.startswith("https://") and any(token in v.lower() for token in ("image", "static", "digikala", ".jpg", ".jpeg", ".png", ".webp")):
            return v
        return ""
    if isinstance(value, list):
        for item in value:
            found = _image_from_api(item)
            if found:
                return found
    if isinstance(value, dict):
        for key in ("main", "image", "image_url", "webp_url", "url", "src", "large", "original"):
            if key in value:
                found = _image_from_api(value[key])
                if found:
                    return found
        for child in value.values():
            found = _image_from_api(child)
            if found:
                return found
    return ""


def _int_value(value):
    try:
        return int(float(normalize_digits(str(value))))
    except (TypeError, ValueError, OverflowError):
        return None


def parse_product_api(payload: dict, url: str, now: datetime | None = None) -> dict:
    """Parse the public Digikala product JSON endpoint using flexible nested-key matching."""
    target_number = product_id(url).replace("dkp-", "")
    candidates = []
    for obj in _walk_dicts(payload):
        title = _clean_title(obj.get("title_fa") or obj.get("product_title") or obj.get("name_fa") or obj.get("title") or obj.get("name"))
        if not is_publishable_product_title(title):
            continue
        obj_id = str(obj.get("product_id") or obj.get("id") or "")
        has_data = any(k in obj for k in ("default_variant", "variants", "images", "image", "price", "rating", "url"))
        if not has_data:
            continue
        score = 5 + (12 if obj_id == target_number else 0)
        score += 5 if "default_variant" in obj else 0
        score += 3 if "variants" in obj else 0
        score += 3 if "images" in obj or "image" in obj else 0
        score += 2 if "rating" in obj or "rating_rate" in obj else 0
        candidates.append((score, obj, title))
    if not candidates:
        return {}

    candidates.sort(key=lambda item: item[0], reverse=True)
    _, product_obj, title = candidates[0]
    variants = product_obj.get("variants")
    if isinstance(variants, dict):
        variants = list(variants.values())
    variants = variants if isinstance(variants, list) else []
    variant = product_obj.get("default_variant")
    if not isinstance(variant, dict):
        variant = next((v for v in variants if isinstance(v, dict) and (
            v.get("marketable") is True or _textual_availability(v.get("status")) == "in_stock"
        )), None)
    if not isinstance(variant, dict) and variants and isinstance(variants[0], dict):
        variant = variants[0]
    variant = variant if isinstance(variant, dict) else {}
    price_obj = variant.get("price") if isinstance(variant.get("price"), dict) else {}
    if not price_obj:
        price_obj = product_obj.get("price") if isinstance(product_obj.get("price"), dict) else {}
    def price_toman(keys, currency):
        for source in (price_obj, variant, product_obj):
            for key in keys:
                if source.get(key) is not None:
                    value = _money_to_toman(source.get(key), currency)
                    if value:
                        return value
        return None

    current = price_toman(("selling_price_toman", "selling_price_tooman", "price_toman", "current_price_toman"), "IRT")
    if current is None:
        current = price_toman(("selling_price_rial", "price_rial", "current_price_rial"), "IRR")
    if current is None:
        current = price_toman(("selling_price", "discounted_price", "final_price", "price"), "IRR")
    original = price_toman(("rrp_price_toman", "original_price_toman", "list_price_toman"), "IRT")
    if original is None:
        original = price_toman(("rrp_price_rial", "original_price_rial", "list_price_rial"), "IRR")
    if original is None:
        original = price_toman(("rrp_price", "original_price", "regular_price", "list_price"), "IRR")

    image = ""
    for key in ("images", "image", "main_image", "image_url", "thumbnail"):
        if product_obj.get(key):
            image = _image_from_api(product_obj[key])
            if image:
                break
    if not image:
        image = _image_from_api(variant.get("images") or variant.get("image") or "")
    if image.startswith("//"):
        image = "https:" + image

    rating = None
    review_count = 0
    rating_obj = product_obj.get("rating") if isinstance(product_obj.get("rating"), dict) else {}
    for raw in (rating_obj.get("rate"), rating_obj.get("rating"), rating_obj.get("rating_value"),
                product_obj.get("rating_rate"), product_obj.get("rating_value")):
        if raw is not None:
            try:
                rating = float(normalize_digits(str(raw)))
                # Digikala's detail API encodes its average rating on a 0–100
                # scale (e.g. 68.12), while retailer markup commonly uses 0–5.
                if 5 < rating <= 100:
                    rating = round(rating / 20, 2)
                if rating < 0 or rating > 5:
                    rating = None
                if rating is not None:
                    break
            except ValueError:
                pass
    for raw in (rating_obj.get("count"), rating_obj.get("rating_count"), rating_obj.get("review_count"),
                product_obj.get("rating_count"), product_obj.get("review_count"), product_obj.get("reviews_count")):
        value = _int_value(raw)
        if value is not None:
            review_count = max(0, value)
            break

    statuses = []
    for node in (variant, product_obj):
        for key in ("availability", "stock_status", "status", "availability_status"):
            if node.get(key) is not None:
                status = _textual_availability(node.get(key))
                if status != "unknown":
                    statuses.append(status)
        for key in ("marketable", "has_stock", "hasStock", "is_in_stock", "isAvailable", "available"):
            if isinstance(node.get(key), bool):
                statuses.append("in_stock" if node[key] else "out_of_stock")
        for key in ("stock_quantity", "stockQuantity", "inventory_quantity", "quantity", "available_quantity"):
            value = _int_value(node.get(key))
            if value is not None:
                statuses.append("in_stock" if value > 0 else "out_of_stock")
    if "out_of_stock" in statuses:
        availability, availability_source = "out_of_stock", "digikala_api"
    elif "in_stock" in statuses:
        availability, availability_source = "in_stock", "digikala_api"
    else:
        availability, availability_source = "unknown", "digikala_api_no_stock_signal"

    # Product detail APIs commonly expose prices in rials; all outward copy is in toman.
    if current and original and original <= current:
        original = None
    variant_label_parts = []
    themes = variant.get("themes") if isinstance(variant.get("themes"), list) else []
    for theme in themes:
        if not isinstance(theme, dict):
            continue
        value_obj = theme.get("value") if isinstance(theme.get("value"), dict) else {}
        label = value_obj.get("title") or theme.get("title") or ""
        if label:
            variant_label_parts.append(str(label).strip())
    variant_label = " ".join(variant_label_parts) or _clean_title(variant.get("title_fa") or variant.get("title") or "")
    direct_deadline = ""
    for _score, candidate_obj, _candidate_title in candidates:
        candidate_id = str(candidate_obj.get("product_id") or candidate_obj.get("id") or "")
        if candidate_id != target_number:
            continue
        direct_deadline = extract_deal_expiry(candidate_obj, now=now)
        if direct_deadline:
            break
    return {
        "product_id": product_id(url),
        "product_url": safe_product_url(url),
        "title": title,
        "image_url": image,
        "current_price": current,
        "original_price": original,
        "variant_label": variant_label,
        "rating": rating,
        "review_count": review_count,
        "availability": availability,
        "availability_source": availability_source,
        "deal_expires_at": direct_deadline,
        "expiry_source": "digikala_product_detail_api" if direct_deadline else "unavailable",
        "expiry_deadline_verified_directly": bool(direct_deadline),
        "expiry_estimated": False,
        "checked_at": datetime.now(timezone.utc).isoformat(),
    }


def verify_live_page_price(product: dict) -> dict:
    """Re-read the live DigiKala API first, using HTML as fallback; fail closed if neither verifies price."""
    url = safe_product_url(product.get("product_url", ""))
    expected_id = product_id(url) if url else ""
    try:
        expected_price = int(product.get("current_price") or 0)
    except (TypeError, ValueError, OverflowError):
        expected_price = 0
    if not url or not expected_id or expected_price <= 0:
        return {"ok": False, "reason": "invalid_product_or_price", "page_price": None}

    live = {}
    api_errors = []
    numeric_id = expected_id.replace("dkp-", "")
    if numeric_id.isdigit():
        for api_version in ("v2", "v1"):
            try:
                response = SESSION.get(
                    f"https://api.digikala.com/{api_version}/product/{numeric_id}/",
                    timeout=HTTP_TIMEOUT,
                    allow_redirects=True,
                )
                if not response.ok:
                    api_errors.append(f"{api_version}_http_{response.status_code}")
                    continue
                candidate = parse_product_api(response.json(), url)
                if candidate and product_id(candidate.get("product_url") or url) != expected_id:
                    api_errors.append(f"{api_version}_product_identity_mismatch")
                    continue
                if candidate.get("current_price"):
                    live = candidate
                    break
                api_errors.append(f"{api_version}_price_unavailable")
            except Exception as exc:
                api_errors.append(f"{api_version}_{type(exc).__name__}")

    price_source = "digikala_live_api" if live.get("current_price") else ""
    if live.get("availability") == "out_of_stock":
        return {
            "ok": False,
            "reason": "live_product_out_of_stock",
            "page_price": live.get("current_price"),
            "price_source": price_source,
        }

    if not live.get("current_price"):
        # Some API responses omit price temporarily; use page data as fallback.
        # Missing HTML price alone is not evidence of a mismatch.
        try:
            final_url, page_html = fetch_page(url)
            final_url = safe_product_url(final_url) or url
            if product_id(final_url) != expected_id:
                return {"ok": False, "reason": "product_identity_mismatch", "page_price": None}
            page_product = parse_product_page(final_url, page_html)
            if page_product.get("current_price"):
                live = page_product
                price_source = "digikala_product_page"
        except Exception as exc:
            api_errors.append(f"html_{type(exc).__name__}")

    if live.get("availability") == "out_of_stock":
        return {
            "ok": False,
            "reason": "live_product_out_of_stock",
            "page_price": live.get("current_price"),
            "price_source": price_source,
        }
    try:
        live_price = int(live.get("current_price") or 0)
    except (TypeError, ValueError, OverflowError):
        live_price = 0
    if live_price <= 0:
        return {
            "ok": False,
            "reason": "live_price_unverified",
            "page_price": None,
            "api_errors": api_errors[:6],
        }

    delta_percent = abs(live_price - expected_price) * 100.0 / expected_price
    if delta_percent > 1.0:
        return {
            "ok": False,
            "reason": "live_page_price_mismatch",
            "page_price": live_price,
            "api_price": expected_price,
            "price_source": price_source,
            "delta_percent": round(delta_percent, 2),
        }

    try:
        listed_original = int(product.get("original_price") or 0)
        live_original = int(live.get("original_price") or 0)
    except (TypeError, ValueError, OverflowError):
        listed_original, live_original = 0, 0
    if listed_original > 0 and live_original > 0:
        original_delta = abs(live_original - listed_original) * 100.0 / listed_original
        if original_delta > 2.0:
            return {
                "ok": False,
                "reason": "live_page_original_price_mismatch",
                "page_price": live_price,
                "api_price": expected_price,
                "page_original_price": live_original,
                "api_original_price": listed_original,
                "price_source": price_source,
                "delta_percent": round(original_delta, 2),
            }

    return {
        "ok": True,
        "reason": "verified",
        "page_price": live_price,
        "api_price": expected_price,
        "price_source": price_source,
        "delta_percent": round(delta_percent, 2),
        "deal_expires_at": live.get("deal_expires_at", ""),
        "expiry_source": live.get("expiry_source", ""),
        "expiry_deadline_verified_directly": live.get("expiry_deadline_verified_directly") is True,
    }


def _snappshop_request_headers() -> dict[str, str]:
    return {
        "Accept": "application/json, text/plain, */*",
        "Content-Type": "application/json",
        "Origin": "https://snappshop.ir",
        "Referer": "https://snappshop.ir/",
        "User-Agent": "Mozilla/5.0 (Linux; Android 15) AppleWebKit/537.36 Chrome/140.0.0.0 Mobile Safari/537.36",
    }


def _snappshop_search_items(payload: dict) -> list[dict]:
    data = payload.get("data") if isinstance(payload, dict) else None
    structure = data.get("structure", []) if isinstance(data, dict) else []
    items = []
    if isinstance(structure, list):
        for section in structure:
            if not isinstance(section, dict):
                continue
            raw_items = section.get("items", [])
            if isinstance(raw_items, list):
                items.extend(item for item in raw_items if isinstance(item, dict))
    return items


def parse_snappshop_product_api(payload: dict, url: str, search_card: dict | None = None) -> dict:
    """Parse SnappShop's public JSON product response; require an explicit stock signal."""
    canonical = safe_product_url(url)
    if not canonical or not product_id(canonical).startswith("snp-"):
        return {}
    data = payload.get("data") if isinstance(payload, dict) and isinstance(payload.get("data"), dict) else payload
    if not isinstance(data, dict):
        return {}
    content = data.get("content") if isinstance(data.get("content"), dict) else {}
    card = search_card if isinstance(search_card, dict) else {}
    title = _clean_title(
        content.get("title_fa") or content.get("title") or content.get("name")
        or data.get("title_fa") or data.get("title") or card.get("title")
    )
    if not is_publishable_product_title(title):
        return {}

    vendors_seen = 0
    availability_signals = []
    in_stock_offers = []
    variants = data.get("variants") or []
    if isinstance(variants, dict):
        variants = list(variants.values())
    if isinstance(variants, list):
        for variant in variants:
            if not isinstance(variant, dict):
                continue
            vendors = variant.get("vendor") or variant.get("vendors") or []
            if isinstance(vendors, dict):
                vendors = list(vendors.values())
            if not isinstance(vendors, list):
                continue
            for vendor in vendors:
                if not isinstance(vendor, dict):
                    continue
                vendors_seen += 1
                signals = []
                for key in ("is_available_in_vendor_inventory", "is_available_in_shop"):
                    if isinstance(vendor.get(key), bool):
                        signals.append(vendor[key])
                quantity = _int_value(vendor.get("stock"))
                if quantity is None:
                    quantity = _int_value(vendor.get("stock_quantity"))
                if quantity is not None:
                    signals.append(quantity > 0)
                if signals:
                    availability_signals.extend(signals)
                available = any(signals) if signals else None
                regular_raw = vendor.get("price") or vendor.get("original_price")
                special_raw = vendor.get("special_price") or vendor.get("discounted_price")
                regular = _money_to_toman(regular_raw, "IRR")
                special = _money_to_toman(special_raw, "IRR")
                current = special if special and special > 0 and (not regular or special < regular) else regular
                if available is not True or not current:
                    continue
                original = regular if regular and regular > current else None
                in_stock_offers.append({
                    "current_price": int(current),
                    "original_price": int(original) if original else None,
                    "discounted": bool(original and original > current),
                })

    # Do not infer availability from a search result, title, price, or empty error response.
    if in_stock_offers:
        availability = "in_stock"
        availability_source = "snappshop_product_api"
        discounted = [offer for offer in in_stock_offers if offer["discounted"]]
        chosen = min(discounted or in_stock_offers, key=lambda offer: offer["current_price"])
        current_price = chosen["current_price"]
        original_price = chosen["original_price"] if chosen["discounted"] else None
    elif vendors_seen and availability_signals and not any(availability_signals):
        availability = "out_of_stock"
        availability_source = "snappshop_product_api"
        current_price = None
        original_price = None
    else:
        availability = "unknown"
        availability_source = "snappshop_api_no_stock_signal"
        current_price = None
        original_price = None

    rating_raw = data.get("rating") or data.get("rate") or card.get("state") or {}
    if isinstance(rating_raw, dict):
        rating_value = rating_raw.get("rate") or rating_raw.get("rating") or rating_raw.get("rating_value")
        review_raw = (
            rating_raw.get("rate_count") or rating_raw.get("review_count")
            or rating_raw.get("rating_count") or rating_raw.get("count")
        )
    else:
        rating_value = rating_raw
        review_raw = None
    card_state = card.get("state") if isinstance(card.get("state"), dict) else {}
    if rating_value in (None, ""):
        rating_value = card_state.get("rate")
    if review_raw in (None, ""):
        review_raw = card_state.get("rate_count")
    try:
        rating = float(normalize_digits(str(rating_value))) if rating_value not in (None, "") else None
        if rating is not None and not 0 <= rating <= 5:
            rating = None
    except (TypeError, ValueError, OverflowError):
        rating = None
    review_count = max(0, _int_value(review_raw) or 0)

    image = ""
    for value in (
        data.get("images"), content.get("images"), data.get("image"), data.get("image_url"),
        data.get("main_image"), content.get("image"), card.get("image"), card.get("images"),
        card.get("image_url"), card.get("thumbnail"),
    ):
        image = _image_from_api(value)
        if image:
            break

    return {
        "product_id": product_id(canonical),
        "product_url": canonical,
        "title": title,
        "image_url": image,
        "current_price": current_price,
        "original_price": original_price,
        "rating": rating,
        "review_count": review_count,
        "availability": availability,
        "availability_source": availability_source,
        "checked_at": datetime.now(timezone.utc).isoformat(),
        "expiry_source": "snappshop_no_confirmed_expiry",
        "deal_expires_at": "",
        "expiry_deadline_verified_directly": False,
        "expiry_deadline_verified_from_site_card": False,
        "expiry_estimated": False,
    }


def fetch_snappshop_product_record(url: str) -> dict:
    """Fetch and verify a SnappShop product using its public JSON API, not blocked HTML."""
    canonical = safe_product_url(url)
    if not canonical:
        return {}
    api_id = str(SNAPPSHOP_API_IDS_BY_URL.get(canonical) or "").strip()
    if not api_id:
        api_id = product_id(canonical).removeprefix("snp-")
    params = {"lat": SNAPPSHOP_LATITUDE, "lng": SNAPPSHOP_LONGITUDE}
    response = SESSION.get(
        f"{SNAPPSHOP_API_BASE_URL}/products/v2/{api_id}",
        params=params,
        headers=_snappshop_request_headers(),
        timeout=HTTP_TIMEOUT,
    )
    response.raise_for_status()
    if len(response.content) > 8_000_000:
        raise RuntimeError("SnappShop product API response exceeded 8 MB")
    payload = response.json()
    record = parse_snappshop_product_api(
        payload, canonical, SNAPPSHOP_SEARCH_CARDS_BY_URL.get(canonical)
    )
    if not record:
        raise RuntimeError("SnappShop product API returned no verifiable product record")
    print(
        f"SNAPPSHOP_PRODUCT_API id={product_id(canonical)} title=True "
        f"price={bool(record.get('current_price'))} stock={record.get('availability')} "
        f"discount={bool(record.get('original_price') and record.get('current_price') and record['original_price'] > record['current_price'])}"
    )
    return record


def fetch_product_record(url: str) -> dict:
    """Use the store's JSON product API first, then HTML only for DigiKala."""
    canonical = safe_product_url(url)
    if canonical and product_id(canonical).startswith("snp-"):
        return fetch_snappshop_product_record(canonical)
    pid = product_id(url).replace("dkp-", "")
    api_product = {}
    if pid.isdigit():
        for api_version in ("v2", "v1"):
            api_url = f"https://api.digikala.com/{api_version}/product/{pid}/"
            try:
                response = SESSION.get(api_url, timeout=HTTP_TIMEOUT, allow_redirects=True)
                if not response.ok:
                    continue
                payload = response.json()
                api_product = parse_product_api(payload, url)
                if api_product.get("title") or api_product.get("current_price") or api_product.get("availability") == "in_stock":
                    print(f"PRODUCT_API id={product_id(url)} version={api_version} title={bool(api_product.get('title'))} price={bool(api_product.get('current_price'))} stock={api_product.get('availability')}")
                    break
            except Exception as exc:
                print(f"PRODUCT_API_FAILED id={product_id(url)} version={api_version} error={type(exc).__name__}")

    needs_html = (
        not is_publishable_product_title(api_product.get("title"))
        or not api_product.get("current_price")
        or not api_product.get("image_url")
        or api_product.get("availability") == "unknown"
    )
    html_product = {}
    if needs_html:
        try:
            final_url, page = fetch_page(url)
            canonical = safe_product_url(final_url) or safe_product_url(url)
            html_product = parse_product_page(canonical, page)
        except Exception as exc:
            print(f"PRODUCT_HTML_FAILED id={product_id(url)} error={type(exc).__name__}")

    merged = dict(html_product)
    for key in (
        "product_id", "product_url", "title", "image_url", "current_price", "original_price",
        "variant_label", "rating", "review_count", "deal_expires_at", "expiry_source",
        "expiry_deadline_verified_directly", "expiry_estimated",
    ):
        value = api_product.get(key)
        if value in (None, "", 0):
            continue
        if key == "title" and not is_publishable_product_title(value):
            continue
        merged[key] = value
    if not is_publishable_product_title(merged.get("title")):
        merged["title"] = ""
    statuses = [x for x in (api_product.get("availability"), html_product.get("availability")) if x in {"in_stock", "out_of_stock"}]
    # If public sources conflict, fail closed to avoid advertising unavailable goods.
    if "out_of_stock" in statuses:
        merged["availability"] = "out_of_stock"
        merged["availability_source"] = "conflicting_or_explicit_out_signal"
    elif statuses:
        merged["availability"] = "in_stock"
        merged["availability_source"] = api_product.get("availability_source") if api_product.get("availability") == "in_stock" else html_product.get("availability_source")
    else:
        merged["availability"] = "unknown"
        merged["availability_source"] = api_product.get("availability_source") or html_product.get("availability_source") or "no_reliable_stock_signal"
    merged.setdefault("product_id", product_id(url))
    merged.setdefault("product_url", safe_product_url(url))
    merged.setdefault("checked_at", datetime.now(timezone.utc).isoformat())
    return merged


def _history_price_toman(raw) -> int | None:
    """Digikala's price-chart API returns Rials; normalize it to Toman."""
    try:
        value = int(float(normalize_digits(str(raw))))
    except (TypeError, ValueError, OverflowError):
        return None
    return value // 10 if value >= 10_000 else None


def _stable_low(prices: list[int]) -> int | None:
    """Lowest price seen on two adjacent available daily observations."""
    if len(prices) < 2:
        return None
    return min(max(left, right) for left, right in zip(prices, prices[1:]))


def _history_metrics(prices: list[int], days: list[str], source: str) -> dict:
    prices = [int(x) for x in prices if isinstance(x, (int, float)) and x > 0]
    return {
        "history_status": "verified" if len(prices) >= MIN_HISTORICAL_PRICE_DAYS else "insufficient_history",
        "history_source": source,
        "history_days": len(prices),
        "history_start_day": days[0] if days else None,
        "history_end_day": days[-1] if days else None,
        "history_low_toman": min(prices) if prices else None,
        "history_stable_low_toman": _stable_low(prices),
        "history_median_toman": int(round(statistics.median(prices))) if prices else None,
        "history_high_toman": max(prices) if prices else None,
    }


def is_historically_discount_eligible(product: dict) -> bool:
    """Only trust a deal when recent history supports it, not merely the listed RRP."""
    if product.get("history_status") != "verified":
        return False
    current = product.get("current_price")
    median = product.get("history_median_toman")
    stable_low = product.get("history_stable_low_toman")
    below_median = bool(
        current and median and median > 0
        and current <= median * (100 - MIN_HISTORICAL_DISCOUNT_PERCENT) / 100
    )
    # A flat or barely moving price at its own low is not a real deal. Accept the
    # stable-low route only when the typical price was at least 10% higher and today's
    # price remains within 3% of that stable low (both configurable).
    near_stable_low = bool(
        current and stable_low and stable_low > 0 and median
        and median >= stable_low * (100 + MIN_STABLE_LOW_GAP_PERCENT) / 100
        and current <= stable_low * (100 + MAX_STABLE_LOW_DISTANCE_PERCENT) / 100
    )
    return below_median or near_stable_low


def _add_history_comparison(product: dict) -> dict:
    current = product.get("current_price")
    median = product.get("history_median_toman")
    low = product.get("history_stable_low_toman")
    if current and median and median > 0:
        product["discount_vs_30d_median_pct"] = round(100 * (median - current) / median)
        product["historical_discount_savings_toman"] = max(0, int(median - current))
    else:
        product["discount_vs_30d_median_pct"] = None
        product["historical_discount_savings_toman"] = None
    product["historical_deal_eligible"] = is_historically_discount_eligible(product)
    if current and low and low > 0:
        product["pct_above_stable_low"] = round(100 * (current - low) / low)
    else:
        product["pct_above_stable_low"] = None
    return product


def _normalized_variant_label(value) -> str:
    text = str(value or "").lower().replace("ي", "ی").replace("ك", "ک")
    return "".join(char for char in text if char.isalnum())


def parse_price_history(payload: dict, current_price: int | None, variant_label: str = "") -> dict:
    """Parse the public chart, preferring an identifiable matching color/variant."""
    data = payload.get("data", {}) if isinstance(payload, dict) else {}
    charts = data.get("price_chart", []) if isinstance(data, dict) else []
    requested_label = _normalized_variant_label(variant_label)
    choices = []
    for chart in charts if isinstance(charts, list) else []:
        if not isinstance(chart, dict):
            continue
        rows = []
        for point in chart.get("history", []) if isinstance(chart.get("history"), list) else []:
            if not isinstance(point, dict) or not point.get("is_marketable"):
                continue
            price = _history_price_toman(point.get("selling_price"))
            if not price:
                continue
            rows.append((str(point.get("day") or "").strip(), price))
        if not rows:
            continue
        prices = [price for _, price in rows]
        days = [day for day, _ in rows]
        last_price = prices[-1]
        distance = abs(last_price - current_price) / current_price if current_price else 0.0
        title = str(chart.get("title") or "")
        normalized_title = _normalized_variant_label(title)
        label_match = bool(
            requested_label and normalized_title
            and (normalized_title in requested_label or requested_label in normalized_title)
        )
        choices.append((0 if label_match else 1, distance, -len(prices), title, prices, days, last_price, label_match))
    if not choices:
        return {
            "history_status": "unavailable",
            "history_source": "digikala_price_chart",
            "history_days": 0,
        }

    # If we can identify the selected variant, a large price drop may be a real sale.
    # With multiple series and no matching label, fail closed when the closest history
    # still differs sharply from today's price.
    choices.sort(key=lambda item: (item[0], item[1], item[2]))
    _, distance, _, variant_title, prices, days, last_price, label_match = choices[0]
    if current_price and len(choices) > 1 and not label_match and distance > 0.20:
        return {
            "history_status": "variant_mismatch",
            "history_source": "digikala_price_chart",
            "history_days": len(prices),
            "history_variant": str(variant_title or "")[:100],
            "history_last_price_toman": last_price,
            "history_match_delta_pct": round(distance * 100),
        }
    result = _history_metrics(prices, days, "digikala_price_chart")
    result["history_variant"] = str(variant_title or "")[:100]
    result["history_variant_match"] = "label" if label_match else "closest_price"
    result["history_last_price_toman"] = last_price
    result["history_match_delta_pct"] = round(distance * 100) if current_price else None
    result["history_checked_at"] = datetime.now(timezone.utc).isoformat()
    return _add_history_comparison(result | {"current_price": current_price})


def fetch_price_history_record(url: str, current_price: int | None, variant_label: str = "") -> dict:
    """Read Digikala's public daily chart; failures are handled by the snapshot fallback."""
    pid = product_id(url).replace("dkp-", "")
    if not pid.isdigit():
        return {"history_status": "unavailable", "history_source": "digikala_price_chart", "history_days": 0}
    response = SESSION.get(
        f"https://api.digikala.com/v1/product/{pid}/price-chart/",
        headers={"Accept": "application/json", "Referer": "https://www.digikala.com/"},
        timeout=HISTORY_TIMEOUT,
        allow_redirects=True,
    )
    response.raise_for_status()
    if len(response.content) > 3_000_000:
        raise RuntimeError("price history response exceeded 3 MB safety limit")
    payload = response.json()
    if isinstance(payload, dict) and isinstance(payload.get("status"), int) and payload["status"] >= 300:
        raise RuntimeError(f"price history API body status {payload['status']}")
    return parse_price_history(payload, current_price, variant_label)


def update_price_snapshots(state: dict, products: list[dict]) -> None:
    """Store one price observation per product/day as a durable fallback history."""
    snapshots_by_product = state.get("price_history")
    if not isinstance(snapshots_by_product, dict):
        snapshots_by_product = {}
        state["price_history"] = snapshots_by_product
    now = datetime.now(timezone.utc)
    today = now.date().isoformat()
    cutoff = (now.date() - timedelta(days=45)).isoformat()
    for product in products:
        pid = str(product.get("product_id") or product_id(product.get("product_url", "")))
        price = product.get("current_price")
        if not pid or not price or int(price) <= 0:
            continue
        entry = snapshots_by_product.get(pid)
        if not isinstance(entry, dict):
            entry = {"snapshots": []}
            snapshots_by_product[pid] = entry
        samples = entry.get("snapshots")
        if not isinstance(samples, list):
            samples = []
        samples = [
            sample for sample in samples
            if isinstance(sample, dict) and str(sample.get("day", "")) >= cutoff and int(sample.get("price") or 0) > 0
        ]
        existing = next((sample for sample in samples if sample.get("day") == today), None)
        if existing:
            existing["price"] = int(price)
        else:
            samples.append({"day": today, "price": int(price)})
        samples.sort(key=lambda sample: str(sample.get("day", "")))
        entry["snapshots"] = samples[-45:]
        entry["last_seen_day"] = today

    # Retain only recent product histories; avoid unbounded growth in state.json.
    for pid, entry in list(snapshots_by_product.items()):
        if not isinstance(entry, dict) or str(entry.get("last_seen_day", "")) < cutoff:
            snapshots_by_product.pop(pid, None)
    if len(snapshots_by_product) > 2000:
        keep = sorted(
            snapshots_by_product.items(),
            key=lambda pair: str((pair[1] or {}).get("last_seen_day", "")),
        )[-2000:]
        state["price_history"] = dict(keep)


def apply_snapshot_price_history(product: dict, state: dict) -> dict:
    pid = str(product.get("product_id") or product_id(product.get("product_url", "")))
    history = state.get("price_history", {})
    entry = history.get(pid, {}) if isinstance(history, dict) else {}
    samples = entry.get("snapshots", []) if isinstance(entry, dict) else []
    samples = [
        sample for sample in samples
        if isinstance(sample, dict) and int(sample.get("price") or 0) > 0 and sample.get("day")
    ]
    samples = sorted(samples, key=lambda sample: str(sample["day"]))
    prices = [int(sample["price"]) for sample in samples]
    days = [str(sample["day"]) for sample in samples]
    metrics = _history_metrics(prices, days, "radar_daily_snapshots")
    if metrics["history_status"] == "verified":
        product.update(metrics)
        product["history_checked_at"] = datetime.now(timezone.utc).isoformat()
        return _add_history_comparison(product)
    # Keep partial API metrics, if any, but never mark a thin or missing history as verified.
    if product.get("history_status") != "insufficient_history" or not product.get("history_median_toman"):
        product["history_status"] = "pending_history"
        product["history_source"] = "radar_daily_snapshots"
        product["history_days"] = len(prices)
        product["history_median_toman"] = metrics.get("history_median_toman")
        product["history_low_toman"] = metrics.get("history_low_toman")
        product["history_stable_low_toman"] = metrics.get("history_stable_low_toman")
        product["history_high_toman"] = metrics.get("history_high_toman")
        product["history_start_day"] = metrics.get("history_start_day")
        product["history_end_day"] = metrics.get("history_end_day")
        product["history_checked_at"] = datetime.now(timezone.utc).isoformat()
    return _add_history_comparison(product)


def enrich_price_history(products: list[dict], state: dict) -> None:
    """Validate top listed-discount candidates and persist snapshots for fallback verification."""
    update_price_snapshots(state, products)
    ranked = sorted(products, key=deal_sort_key, reverse=True)
    checked = {str(p.get("product_id") or product_id(p.get("product_url", ""))): p for p in ranked[:PRICE_HISTORY_CHECK_LIMIT]}
    for index, (pid, product) in enumerate(checked.items()):
        if index:
            time.sleep(0.20)  # keep calls to the public endpoint modest
        try:
            history = fetch_price_history_record(
                product.get("product_url", ""),
                product.get("current_price"),
                product.get("variant_label", ""),
            )
            product.update(history)
            print(
                f"PRICE_HISTORY id={pid} status={product.get('history_status')} "
                f"days={product.get('history_days')} median={product.get('history_median_toman')} "
                f"vs_median_pct={product.get('discount_vs_30d_median_pct')} "
                f"variant_match={product.get('history_variant_match')}"
            )
        except Exception as exc:
            product["history_api_error"] = type(exc).__name__
            status_code = getattr(getattr(exc, "response", None), "status_code", None)
            if status_code in {403, 429}:
                print("PRICE_HISTORY_PAUSE: endpoint rate-limited; remaining items use local snapshots.")
                break
            print(f"PRICE_HISTORY_FAILED id={pid} error={type(exc).__name__} status={status_code or 'n/a'}")
    for product in products:
        if product.get("history_status") != "verified":
            apply_snapshot_price_history(product, state)
        else:
            _add_history_comparison(product)



def _torob_rpc(method: str, params: dict | None = None, request_id: int = 1) -> dict:
    """Call the public, read-only Torob MCP endpoint using Streamable HTTP."""
    if not TOROB_MCP_URL.startswith("https://"):
        raise RuntimeError("Torob MCP endpoint must use HTTPS")
    response = requests.post(
        TOROB_MCP_URL,
        data=json.dumps({
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params or {},
        }).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": "affilio-product-radar/1.0",
        },
        timeout=(10, 30),
    )
    if response.status_code == 429:
        wait = response.headers.get("Retry-After", "60")
        raise RuntimeError(f"Torob MCP rate limited the request; retry-after={wait}s")
    response.raise_for_status()
    if len(response.content) > 2_000_000:
        raise RuntimeError("Torob MCP response exceeded 2 MB safety limit")
    body_text = response.text.strip()
    if not body_text:
        return {}
    # Streamable HTTP may return either JSON or an SSE frame with one JSON data line.
    data_lines = [
        line[5:].strip()
        for line in body_text.splitlines()
        if line.startswith("data:") and line[5:].strip() and line[5:].strip() != "[DONE]"
    ]
    if data_lines:
        body_text = data_lines[-1]
    payload = json.loads(body_text)
    if not isinstance(payload, dict):
        raise RuntimeError("Torob MCP returned an unexpected response shape")
    if payload.get("error"):
        error = payload["error"]
        raise RuntimeError(
            str(error.get("message") or error)[:240] if isinstance(error, dict)
            else str(error)[:240]
        )
    return payload


def _prepare_torob_mcp() -> None:
    initialized = _torob_rpc(
        "initialize",
        {
            "protocolVersion": "2024-11-05",
            "capabilities": {},
            "clientInfo": {"name": "affilio-product-radar", "version": "1.0.0"},
        },
        request_id=1,
    )
    if not initialized.get("result", {}).get("serverInfo"):
        raise RuntimeError("Torob MCP initialization did not confirm serverInfo")
    time.sleep(TOROB_MCP_GAP_SECONDS)
    # Some hosted MCP demos do not dispatch notification methods even though
    # they accept initialize/tools/list. Ignore only this specific unsupported
    # notification; all real tool/list errors still fail closed.
    try:
        _torob_rpc("notifications/initialized", {}, request_id=2)
    except Exception as exc:
        if "method not found" not in str(exc).lower():
            raise
        print("TOROB_MCP_NOTE: endpoint does not implement notifications/initialized; continuing with tools/list.")
    time.sleep(TOROB_MCP_GAP_SECONDS)
    listed = _torob_rpc("tools/list", {}, request_id=3)
    names = {
        str(item.get("name"))
        for item in listed.get("result", {}).get("tools", [])
        if isinstance(item, dict)
    }
    missing = {"search_products", "product_details"} - names
    if missing:
        raise RuntimeError("Torob MCP is missing required tools: " + ", ".join(sorted(missing)))
    time.sleep(TOROB_MCP_GAP_SECONDS)


def _torob_tool(name: str, arguments: dict, request_id: int) -> dict:
    """Invoke one Torob MCP tool; never retry automatically after a challenge."""
    try:
        reply = _torob_rpc(
            "tools/call",
            {"name": name, "arguments": arguments},
            request_id=request_id,
        )
        result = reply.get("result", {})
        content = result.get("content", []) if isinstance(result, dict) else []
        text_result = next(
            (str(item.get("text") or "") for item in content if isinstance(item, dict) and item.get("type") == "text"),
            "",
        )
        if result.get("isError"):
            raise RuntimeError(text_result[:300] or f"Torob MCP tool {name} returned an error")
        if not text_result:
            raise RuntimeError(f"Torob MCP tool {name} returned no text payload")
        parsed = json.loads(text_result)
        if not isinstance(parsed, dict):
            raise RuntimeError(f"Torob MCP tool {name} returned an unexpected data shape")
        return parsed
    finally:
        # The hosted demo is rate-limited; respect its documented per-client request pacing.
        time.sleep(TOROB_MCP_GAP_SECONDS)


def market_query_from_title(title: str) -> str:
    """Use the model-identifying part of a title, not the full marketing description."""
    text = re.sub(r"\s+", " ", str(title or "")).strip()
    head = re.split(r"[,،;؛]", text, maxsplit=1)[0].strip()
    if len(_market_tokens(head)) < 3 and len(_market_tokens(text)) >= 3:
        head = text
    return head[:95].strip()


MARKET_GENERIC_TOKENS = {
    # Product forms/categories and packaging words are not proof that two listings
    # describe the same product (e.g. two different tablets from one brand).
    "قرص", "کپسول", "ژلاتینی", "نرم", "بسته", "عددی", "عدد", "تایی",
    "هندزفری", "هدفون", "اسپیکر", "بلوتوثی", "بلوتوث", "قابل", "حمل",
    "بی", "سیم", "ماوس", "موس", "جوراب", "مردانه", "زنانه",
    "شارژر", "کابل", "سشوار", "برس", "حرارتی", "وزن", "حجم",
    "میلی", "گرم", "کیلوگرم", "لیتر", "وات", "آمپر", "ظرفیت",
    "tablet", "tablets", "capsule", "capsules", "speaker", "bluetooth",
    "headphone", "headphones", "earbuds", "pack", "pcs", "piece", "pieces",
    "count", "model", "size", "weight", "volume", "watt", "mah", "ml", "mg",
}


def _market_tokens(value: str) -> set[str]:
    text = normalize_digits(str(value or "")).lower()
    text = text.replace("ي", "ی").replace("ك", "ک").replace("ـ", "")
    text = text.replace("\u200c", " ").replace("\u200f", " ")
    text = re.sub(r"کیو\s+سی\s+وای", "qcy", text)
    text = re.sub(r"[^\w]+", " ", text, flags=re.UNICODE)
    stopwords = {
        "و", "از", "با", "برای", "مناسب", "حاوی", "دارای", "شامل",
        "خرید", "قیمت", "مدل", "نسخه", "جدید", "اورجینال", "اصل",
        "ویژه", "است", "میباشد", "بسته",
    }
    tokens = text.split()
    return {token for token in tokens if (len(token) > 1 or token.isdigit()) and token not in stopwords}


def _market_pack_numbers(value: str) -> set[str]:
    """Numbers explicitly describing pack count are not model/strength identifiers."""
    text = normalize_digits(str(value or "")).lower()
    text = text.replace("ي", "ی").replace("ك", "ک").replace("\u200c", " ")
    pattern = r"(?<!\w)(\d+(?:[.,]\d+)?)(?=\s*(?:عدد(?:ی)?|تایی|تایى|تا|pcs?|pieces?|tablets?|capsules?|count)(?:\s|$|[^\w]))"
    return set(re.findall(pattern, text))


def _market_identity_tokens(value: str) -> set[str]:
    tokens = _market_tokens(value)
    tokens -= MARKET_GENERIC_TOKENS
    tokens -= _market_pack_numbers(value)
    return tokens


def _market_identity_numbers(value: str) -> set[str]:
    text = normalize_digits(str(value or "")).lower().replace("\u200c", " ")
    all_numbers = set(re.findall(r"\d+(?:[.,]\d+)?", text))
    return all_numbers - _market_pack_numbers(value)


def market_query_variants(title: str) -> list[str]:
    """Try the full title first, then an identity-focused query without packaging words."""
    full = market_query_from_title(title)
    simplified = full
    # Strip pack counts before removing words such as "عدد" and "عددی".
    simplified = re.sub(
        r"(?<!\w)\d+(?:[.,]\d+)?(?=\s*(?:عدد|تایی|تایى|تا|pcs?|pieces?|tablets?|capsules?|count))",
        " ", simplified, flags=re.I,
    )
    for token in sorted(MARKET_GENERIC_TOKENS, key=len, reverse=True):
        simplified = re.sub(rf"(?<!\w){re.escape(token)}(?!\w)", " ", simplified, flags=re.I)
    simplified = re.sub(r"\s+", " ", simplified).strip()
    return list(dict.fromkeys(q for q in (full, simplified) if q and len(_market_tokens(q)) >= 2))


def market_name_match_score(query: str, candidate_name: str) -> int:
    """Require distinctive identity tokens and reject conflicting model/strength numbers."""
    query_tokens = _market_identity_tokens(query)
    candidate_tokens = _market_identity_tokens(candidate_name)
    if not query_tokens or not candidate_tokens:
        return 0

    # If a listing specifies a model, capacity, or strength, those numbers must
    # be represented by the candidate as well; a shared brand and pack count
    # cannot turn a different item into a match.
    query_numbers = _market_identity_numbers(query)
    candidate_numbers = _market_identity_numbers(candidate_name)
    if query_numbers and not query_numbers.issubset(candidate_numbers):
        return 0

    overlap = query_tokens & candidate_tokens
    minimum_overlap = 1 if len(query_tokens) == 1 else max(2, math.ceil(len(query_tokens) * 0.60))
    if len(overlap) < minimum_overlap:
        return 0
    return round(100 * len(overlap) / len(query_tokens))


def is_market_price_uncompetitive(product: dict) -> bool:
    """Block a reliable same-product comparison showing DigiKala >=5% above market."""
    return bool(
        product.get("market_status") == "verified"
        and product.get("market_reference_kind") == "seller_median"
        and product.get("market_price_advantage_pct") is not None
        and int(product["market_price_advantage_pct"]) <= -MARKET_UNDERCUT_BLOCK_PERCENT
    )


def is_market_value_publish_eligible(product: dict) -> bool:
    """Missing market data must not block a post; block only a verified, clearly uncompetitive price."""
    return not is_market_price_uncompetitive(product)


def apply_market_price_comparison(product: dict, card: dict, details: dict, match_score: int, query: str) -> dict:
    """Attach current comparable Torob prices; low-confidence matches stay informational."""
    product["market_query"] = query
    product["market_match_score"] = int(match_score)
    product["market_product_name"] = str(card.get("name_fa") or "")[:180]
    product["market_product_url"] = str(card.get("url") or "")[:500]
    offers = details.get("offers", []) if isinstance(details, dict) else []
    if not isinstance(offers, list):
        offers = []
    prices = []
    for offer in offers:
        if not isinstance(offer, dict) or offer.get("available") is False or offer.get("price_unreliable") is True:
            continue
        raw_price = offer.get("price_toman")
        try:
            price = int(float(raw_price))
        except (TypeError, ValueError, OverflowError):
            continue
        if price > 0:
            prices.append(price)

    try:
        card_price = int(float(card.get("price_toman")))
    except (TypeError, ValueError, OverflowError):
        card_price = None
    if card_price is not None and card_price <= 0:
        card_price = None

    if len(prices) >= 3 and details.get("available") is not False:
        reference_price = int(round(statistics.median(prices)))
        product["market_status"] = "verified"
        product["market_reference_kind"] = "seller_median"
    elif prices:
        reference_price = int(round(statistics.median(prices)))
        product["market_status"] = "limited"
        product["market_reference_kind"] = "limited_seller_sample"
    elif card_price:
        reference_price = card_price
        product["market_status"] = "limited"
        product["market_reference_kind"] = "lowest_torob_offer"
    else:
        reference_price = None
        product["market_status"] = "unavailable"
        product["market_reference_kind"] = "none"

    product["market_reference_price_toman"] = reference_price
    product["market_lowest_price_toman"] = min(prices) if prices else card_price
    product["market_highest_price_toman"] = max(prices) if prices else card_price
    product["market_available_offer_count"] = len(prices)
    try:
        product["market_reported_seller_count"] = int(details.get("offer_count") or 0)
    except (TypeError, ValueError):
        product["market_reported_seller_count"] = 0
    product["market_price_spread_toman"] = (max(prices) - min(prices)) if len(prices) > 1 else None
    product["market_price_checked_at"] = datetime.now(timezone.utc).isoformat()
    current = product.get("current_price")
    if current and reference_price:
        product["market_price_difference_toman"] = int(reference_price - int(current))
        product["market_price_advantage_pct"] = round(100 * (reference_price - int(current)) / reference_price)
        advantage = product["market_price_advantage_pct"]
        if advantage >= 5:
            product["market_value_status"] = "cheaper_than_market"
        elif advantage <= -5:
            product["market_value_status"] = "more_expensive_than_market"
        else:
            product["market_value_status"] = "near_market"
    else:
        product["market_price_difference_toman"] = None
        product["market_price_advantage_pct"] = None
        product["market_value_status"] = "unknown"
    product["market_publish_blocked"] = is_market_price_uncompetitive(product)
    return product


def enrich_market_prices(products: list[dict]) -> None:
    """Compare the top listed-discount candidates to current prices on Torob."""
    for product in products:
        product.setdefault("market_status", "not_checked")
        product.setdefault("market_publish_blocked", False)
        product.setdefault("market_price_advantage_pct", None)
        product.setdefault("market_value_status", "unknown")
    ranked = sorted(products, key=deal_sort_key, reverse=True)
    targets = ranked[:MARKET_PRICE_CHECK_LIMIT]
    if not targets:
        return
    request_id = 10
    try:
        _prepare_torob_mcp()
        print(
            f"MARKET_SOURCE=torob_mcp candidates={len(targets)} "
            f"match_threshold={MIN_MARKET_MATCH_SCORE}%"
        )
    except Exception as exc:
        print(f"MARKET_SOURCE_UNAVAILABLE error={type(exc).__name__} detail={str(exc)[:180]!r}")
        for item in targets:
            item["market_status"] = "unavailable"
            item["market_error"] = type(exc).__name__
        return

    for product in targets:
        title = str(product.get("title") or "")
        query = market_query_from_title(title)
        product["market_query"] = query
        variants = market_query_variants(title)
        if not variants:
            product["market_status"] = "no_confident_match"
            continue
        try:
            best_score, card, used_query = 0, {}, query
            best_scored = []
            for query_variant in variants:
                search = _torob_tool(
                    "search_products",
                    {"query": query_variant, "sort": "price", "limit": 10},
                    request_id,
                )
                request_id += 1
                rows = search.get("products", [])
                rows = [
                    row for row in rows
                    if isinstance(row, dict)
                    and row.get("available") is not False
                    and row.get("price_unreliable") is not True
                ]
                variant_scored = [
                    (market_name_match_score(query_variant, str(row.get("name_fa") or "")), row)
                    for row in rows
                ]
                variant_scored.sort(
                    key=lambda pair: (
                        pair[0],
                        bool(pair[1].get("price_toman")),
                        bool(pair[1].get("details_url")),
                    ),
                    reverse=True,
                )
                candidate_score, candidate = variant_scored[0] if variant_scored else (0, {})
                if candidate_score > best_score or (candidate_score == best_score and not card and candidate):
                    best_score, card, used_query, best_scored = candidate_score, candidate, query_variant, variant_scored
                if best_score >= MIN_MARKET_MATCH_SCORE and card.get("price_toman"):
                    break
            query = used_query
            product["market_query"] = query
            product["market_search_candidates"] = [
                {
                    "name": str(row.get("name_fa") or "")[:120],
                    "price_toman": row.get("price_toman"),
                    "url": row.get("url"),
                    "match_score": score,
                }
                for score, row in best_scored[:3]
            ]
            if best_score < MIN_MARKET_MATCH_SCORE or not card.get("price_toman"):
                product["market_status"] = "no_confident_match"
                product["market_match_score"] = best_score
                product["market_error"] = "no_sufficiently_similar_in_stock_product"
                print(
                    f"MARKET_PRICE id={product.get('product_id')} status=no_confident_match "
                    f"match={best_score}% query={query!r}"
                )
                continue
            details = {}
            if card.get("prk"):
                detail_args = {"prk": card["prk"], "max_offers": 30}
                if card.get("details_url"):
                    detail_args["details_url"] = card["details_url"]
                try:
                    details = _torob_tool("product_details", detail_args, request_id)
                    request_id += 1
                except Exception as exc:
                    # Search's price remains a low-offer signal; it is never upgraded to a median.
                    product["market_detail_error"] = type(exc).__name__
                    msg = str(exc).lower()
                    if any(token in msg for token in ("490", "429", "challenge", "rate limit", "temporarily paused", "blocked")):
                        product["market_status"] = "unavailable"
                        product["market_error"] = type(exc).__name__
                        print(f"MARKET_PRICE_PAUSE id={product.get('product_id')} detail_error={type(exc).__name__}")
                        break
            apply_market_price_comparison(product, card, details, best_score, query)
            print(
                f"MARKET_PRICE id={product.get('product_id')} status={product.get('market_status')} "
                f"match={best_score}% market_price={product.get('market_reference_price_toman')} "
                f"kind={product.get('market_reference_kind')} sellers={product.get('market_available_offer_count')} "
                f"advantage={product.get('market_price_advantage_pct')}% value={product.get('market_value_status')}"
            )
        except Exception as exc:
            product["market_status"] = "unavailable"
            product["market_error"] = type(exc).__name__
            message = str(exc).lower()
            print(
                f"MARKET_PRICE_FAILED id={product.get('product_id')} error={type(exc).__name__} "
                f"detail={str(exc)[:160]!r}"
            )
            # Stop after an upstream challenge/failure rather than causing a burst of retries.
            if any(token in message for token in ("490", "429", "challenge", "rate limit", "temporarily paused", "blocked")):
                print("MARKET_PRICE_PAUSE: remaining candidates stay unverified for this run.")
                break

    for item in targets:
        if item.get("market_status") == "not_checked":
            item["market_status"] = "unavailable"


def select_queued_records_for_recheck(
    queued_records: dict[str, dict],
    now: datetime | None = None,
    max_count: int | None = None,
) -> list[tuple[str, dict]]:
    """Select a fair batch by demand and deal quality, rotating the remainder."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    limit = MAX_QUEUED_RECHECKS if max_count is None else max(0, int(max_count))
    if limit <= 0 or not isinstance(queued_records, dict):
        return []

    eligible = []
    for raw_pid, record in queued_records.items():
        pid = str(raw_pid)
        if not isinstance(record, dict):
            continue
        canonical = safe_product_url(record.get("product_url", ""))
        deadline = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
        if not canonical or product_id(canonical) != pid:
            continue
        # An unknown timer is not proof that an offer has expired. It may be
        # rechecked as an open offer, then accepted only after live stock/price
        # validation. A known deadline must still leave the full publication runway.
        if deadline is not None and (
            deadline <= current or not has_minimum_publication_runway(record, current)
        ):
            continue
        eligible.append((pid, record))

    # Re-establish demand/deal-value priority before slicing, independent of JSON key order.
    eligible.sort(
        key=lambda pair: pending_queue_sort_key(pair[1], pair[1], current),
        reverse=True,
    )
    if len(eligible) <= limit:
        return eligible

    # Half the capacity is permanently reserved for the strongest offers. The second
    # half rotates every five-minute slot so older queued deals are eventually rechecked
    # even when they no longer appear near the front of the live feed.
    fixed_count = max(1, limit // 2)
    fixed = eligible[:fixed_count]
    tail = eligible[fixed_count:]
    rotating_count = limit - len(fixed)
    if rotating_count <= 0 or not tail:
        return fixed

    slot = int(current.timestamp() // 300)
    offset = (slot * rotating_count) % len(tail)
    rotated_tail = (tail + tail)[offset:offset + rotating_count]
    selected = fixed + rotated_tail
    print(
        f"QUEUE_RECHECK_BATCH pool={len(eligible)} selected={len(selected)} "
        f"fixed_priority={len(fixed)} rotating={len(rotated_tail)} offset={offset}"
    )
    return selected


def has_current_demand_signal(record: dict, now: datetime | None = None) -> bool:
    """Require fresh, measured review/rating growth; lifetime popularity is never sufficient."""
    if not isinstance(record, dict) or record.get("current_demand_verified") is not True:
        return False
    try:
        growth = int(record.get("recent_review_growth_window", record.get("recent_review_growth_7d")) or 0)
        window_hours = float(record.get("demand_window_hours") or 0)
    except (TypeError, ValueError, OverflowError):
        return False
    if growth < CURRENT_DEMAND_MIN_REVIEW_GROWTH:
        return False
    if not CURRENT_DEMAND_MIN_OBSERVATION_HOURS <= window_hours <= CURRENT_DEMAND_WINDOW_DAYS * 24:
        return False
    source = str(record.get("demand_signal_source") or "")
    if source not in {"digikala_recent_review_growth", "snappshop_recent_review_growth"}:
        return False
    observed_at = _parse_utc_datetime(record.get("demand_observed_at"))
    if observed_at is None:
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    age_hours = (current.astimezone(timezone.utc) - observed_at).total_seconds() / 3600
    return -0.1 <= age_hours <= CURRENT_DEMAND_MAX_SIGNAL_AGE_HOURS


def update_current_demand_signals(
    state: dict,
    products: list[dict],
    now: datetime | None = None,
) -> dict:
    """Track retailer review/rating-count movement; this is current interest, not sales volume."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    cutoff = current - timedelta(days=CURRENT_DEMAND_WINDOW_DAYS)
    history = state.get("current_demand_observations")
    if not isinstance(history, dict):
        history = {}
        state["current_demand_observations"] = history

    checked = 0
    verified = 0
    for product in products or []:
        if not isinstance(product, dict):
            continue
        pid = str(product.get("product_id") or product_id(product.get("product_url") or "")).strip()
        try:
            review_count = max(0, int(product.get("review_count") or 0))
        except (TypeError, ValueError, OverflowError):
            review_count = 0
        if not pid or review_count <= 0:
            product.update({
                "current_demand_verified": False,
                "current_demand_score": 0,
                "demand_score": 0,
                "recent_review_growth_window": 0,
                "recent_review_growth_7d": 0,
                "demand_window_hours": 0,
                "demand_observed_at": "",
                "demand_signal_source": "",
            })
            continue

        checked += 1
        entry = history.get(pid)
        if not isinstance(entry, dict):
            entry = {"samples": []}
        samples = []
        for sample in entry.get("samples", []) if isinstance(entry.get("samples"), list) else []:
            if not isinstance(sample, dict):
                continue
            observed = _parse_utc_datetime(sample.get("observed_at"))
            try:
                count = max(0, int(sample.get("review_count") or 0))
            except (TypeError, ValueError, OverflowError):
                continue
            if observed is not None and cutoff <= observed <= current and count > 0:
                samples.append({"observed_at": observed.isoformat(), "review_count": count})
        samples.sort(key=lambda item: item["observed_at"])
        last = samples[-1] if samples else None
        last_at = _parse_utc_datetime(last.get("observed_at")) if last else None
        last_count = int(last.get("review_count") or 0) if last else 0

        # An upstream count reset is not growth; start a new observation baseline.
        if last and review_count < last_count:
            samples = []
            last_at = None
            last_count = 0

        sample_due = (
            last_at is None
            or review_count != last_count
            or (current - last_at).total_seconds() >= CURRENT_DEMAND_SAMPLE_INTERVAL_HOURS * 3600
        )
        if sample_due:
            samples.append({
                "observed_at": current.isoformat(),
                "review_count": review_count,
            })
        samples = samples[-32:]
        history[pid] = {"samples": samples, "last_observed_at": current.isoformat()}

        baseline = next(
            (
                sample for sample in samples
                if CURRENT_DEMAND_MIN_OBSERVATION_HOURS * 3600
                <= (current - _parse_utc_datetime(sample["observed_at"])).total_seconds()
                <= CURRENT_DEMAND_WINDOW_DAYS * 86400
            ),
            None,
        )
        growth = 0
        window_hours = 0.0
        current_score = 0
        demand_verified = False
        if baseline:
            baseline_at = _parse_utc_datetime(baseline["observed_at"])
            baseline_count = int(baseline["review_count"])
            growth = max(0, review_count - baseline_count)
            window_hours = max(0.0, (current - baseline_at).total_seconds() / 3600)
            demand_verified = growth >= CURRENT_DEMAND_MIN_REVIEW_GROWTH
            if demand_verified:
                reviews_per_day = growth / max(window_hours / 24.0, 1.0)
                current_score = max(1, min(100, 20 + round(20 * math.log1p(reviews_per_day))))

        source = (
            "digikala_recent_review_growth" if pid.startswith("dkp-")
            else "snappshop_recent_review_growth"
        )
        product.update({
            "current_demand_verified": demand_verified,
            "current_demand_score": current_score,
            "demand_score": current_score,
            "recent_review_growth_window": growth,
            "recent_review_growth_7d": growth,  # Backward-compatible field for older state/tests.
            "demand_window_hours": round(window_hours, 1),
            "demand_observed_at": current.isoformat() if demand_verified else "",
            "demand_signal_source": source if demand_verified else "",
        })
        if demand_verified:
            verified += 1

    stale_before = current - timedelta(days=CURRENT_DEMAND_WINDOW_DAYS + 2)
    for pid, entry in list(history.items()):
        last_seen = _parse_utc_datetime((entry or {}).get("last_observed_at")) if isinstance(entry, dict) else None
        if last_seen is None or last_seen < stale_before:
            history.pop(pid, None)
    if len(history) > CURRENT_DEMAND_HISTORY_MAX_PRODUCTS:
        retained = sorted(
            history.items(),
            key=lambda pair: str((pair[1] or {}).get("last_observed_at") or ""),
        )[-CURRENT_DEMAND_HISTORY_MAX_PRODUCTS:]
        state["current_demand_observations"] = dict(retained)

    summary = {
        "checked": checked,
        "verified": verified,
        "window_days": CURRENT_DEMAND_WINDOW_DAYS,
        "minimum_recent_review_growth": CURRENT_DEMAND_MIN_REVIEW_GROWTH,
        "minimum_observation_hours": CURRENT_DEMAND_MIN_OBSERVATION_HOURS,
        "sample_interval_hours": CURRENT_DEMAND_SAMPLE_INTERVAL_HOURS,
        "maximum_signal_age_hours": CURRENT_DEMAND_MAX_SIGNAL_AGE_HOURS,
    }
    print(
        f"CURRENT_DEMAND_ACTIVITY checked={checked} verified={verified} "
        f"window_days={CURRENT_DEMAND_WINDOW_DAYS} "
        f"minimum_observation_hours={CURRENT_DEMAND_MIN_OBSERVATION_HOURS} "
        f"sample_interval_hours={CURRENT_DEMAND_SAMPLE_INTERVAL_HOURS} "
        f"minimum_recent_growth={CURRENT_DEMAND_MIN_REVIEW_GROWTH} "
        f"max_signal_age_hours={CURRENT_DEMAND_MAX_SIGNAL_AGE_HOURS}"
    )
    return summary


def _candidate_demand_score(record: dict) -> int:
    """Rank by measured recent review growth when available, then public popularity proxies."""
    if not isinstance(record, dict):
        return 0
    try:
        explicit = int(record.get("current_demand_score") or 0)
        if explicit <= 0:
            explicit = int(record.get("demand_score") or 0)
        if explicit > 0:
            return max(0, min(100, explicit))
        historical = int(record.get("historical_popularity_score") or 0)
        if historical > 0:
            return max(0, min(100, historical))
        reviews = max(0, int(record.get("review_count") or 0))
        rating = float(record.get("rating") or record.get("rating_value") or 0)
    except (TypeError, ValueError, OverflowError):
        return 0
    review_score = min(30, round(3.5 * math.log1p(reviews))) if reviews else 0
    rating_score = max(0, min(12, round((rating - 3.0) * 10))) if rating else 0
    return max(0, min(100, review_score + rating_score))


def _candidate_promo_score(record: dict) -> int:
    """Comparable fallback deal score for feed cards that have not been page-checked yet."""
    if not isinstance(record, dict):
        return 0
    try:
        explicit = max(0, int(record.get("promo_score") or 0))
    except (TypeError, ValueError, OverflowError):
        explicit = 0
    if explicit:
        return min(100, explicit)
    try:
        discount = max(0, int(record.get("discount_percent") or 0))
        savings = max(0, int(record.get("savings_toman") or 0))
        reviews = max(0, int(record.get("review_count") or 0))
        rating = float(record.get("rating") or record.get("rating_value") or 0)
    except (TypeError, ValueError, OverflowError):
        discount, savings, reviews, rating = 0, 0, 0, 0.0
    savings_score = min(20, round(3.0 * math.log1p(savings / 100_000))) if savings else 0
    review_score = min(10, round(1.5 * math.log1p(reviews))) if reviews else 0
    rating_score = max(0, min(5, round((rating - 3.0) * 2))) if rating else 0
    return max(0, min(100, round(discount * 0.65 + savings_score + review_score + rating_score)))



def has_meaningful_discount(
    record: dict,
    minimum_discount_percent: int | None = None,
) -> bool:
    """Accept every genuine price reduction; no minimum percentage or cash-saving floor applies."""
    if not isinstance(record, dict):
        return False
    try:
        discount = max(0, int(record.get("discount_percent") or 0))
        savings = max(0, int(record.get("savings_toman") or 0))
        floor = MIN_DISCOUNT_PERCENT if minimum_discount_percent is None else max(
            MIN_DISCOUNT_FALLBACK_PERCENT,
            min(100, int(minimum_discount_percent)),
        )
    except (TypeError, ValueError, OverflowError):
        return False
    return discount >= floor and savings > 0


def _candidate_popularity_score(record: dict) -> int:
    """Estimate broad product popularity from lifetime retailer reviews and rating."""
    if not isinstance(record, dict):
        return 0
    try:
        explicit = max(0, int(record.get("historical_popularity_score") or 0))
        reviews = max(0, int(record.get("review_count") or 0))
        rating = float(record.get("rating") or record.get("rating_value") or 0)
    except (TypeError, ValueError, OverflowError):
        return 0
    if explicit:
        return min(100, explicit)
    review_proxy = min(30, round(3.5 * math.log1p(reviews))) if reviews else 0
    rating_proxy = max(0, min(12, round((rating - 3.0) * 10))) if rating else 0
    return min(100, review_proxy + rating_proxy)


def discovery_queue_sort_key(record: dict, now: datetime | None = None) -> tuple:
    """Rank broad product popularity first, recent activity second, then live discount."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    expiry = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
    active_deadline = bool(expiry and expiry > current)
    remaining = max(0.0, (expiry - current).total_seconds()) if active_deadline else 0.0
    has_runway = bool(active_deadline and remaining >= MIN_PUBLICATION_RUNWAY_MINUTES * 60)
    discount = max(0, int(record.get("discount_percent") or 0))
    savings = max(0, int(record.get("savings_toman") or 0))
    clicks = max(0, int(record.get("click_count_30d") or 0))
    reviews = max(0, int(record.get("review_count") or 0))
    try:
        rating_score = round(float(record.get("rating") or record.get("rating_value") or 0) * 10)
    except (TypeError, ValueError, OverflowError):
        rating_score = 0
    value_gate = int(has_meaningful_discount(record))
    market_verified = int(
        record.get("market_status") == "verified"
        and record.get("market_reference_kind") == "seller_median"
        and record.get("market_price_advantage_pct") is not None
    )
    try:
        market_advantage = int(record.get("market_price_advantage_pct") or 0) if market_verified else -101
    except (TypeError, ValueError, OverflowError):
        market_advantage = -101
    if not active_deadline:
        urgency_tier = -1
    elif remaining <= 120 * 60:
        urgency_tier = 2
    elif remaining <= 180 * 60:
        urgency_tier = 1
    else:
        urgency_tier = 0
    first_seen = _parse_utc_datetime(record.get("first_seen_at"))
    first_seen_ts = first_seen.timestamp() if first_seen else current.timestamp()
    return (
        _candidate_popularity_score(record), reviews, rating_score,
        _candidate_demand_score(record), discount,
        clicks, market_verified, market_advantage, value_gate,
        _candidate_promo_score(record), savings, int(has_runway), urgency_tier,
        -remaining if active_deadline else float("-inf"), -first_seen_ts,
    )

def merge_discovery_queue(
    queue: dict[str, dict],
    candidates: list[dict],
    now: datetime | None = None,
) -> dict[str, dict]:
    """Persist every safely identified deal-card candidate before expensive product checks."""
    current = (now or datetime.now(timezone.utc))
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    current_iso = current.isoformat()
    added = 0
    updated = 0

    for row in candidates if isinstance(candidates, list) else []:
        if not isinstance(row, dict):
            continue
        url = safe_product_url(str(row.get("product_url") or row.get("url") or ""))
        pid = product_id(url)
        title = str(row.get("title") or row.get("title_fa") or "").strip()[:180]
        if (
            not url or not pid or not is_publishable_product_title(title)
            or is_prohibited_product_title(title)
        ):
            continue

        old = queue.get(pid, {})
        if not isinstance(old, dict):
            old = {}
        first_seen = _parse_utc_datetime(old.get("first_seen_at")) or current
        new_expiry_raw = _parse_deal_expiry_value(row.get("deal_expires_at"))
        new_expiry = _parse_utc_datetime(new_expiry_raw)
        old_expiry = _parse_utc_datetime(_parse_deal_expiry_value(old.get("deal_expires_at")))
        if new_expiry is not None:
            # An explicitly expired deadline from the current feed supersedes any old deadline.
            expiry = new_expiry if new_expiry > current else None
        else:
            expiry = old_expiry if old_expiry and old_expiry > current else None

        raw_source = str(row.get("source") or row.get("discovery_source") or "digikala_live_deals_feed")[:80]
        record = {
            **old,
            "product_id": pid,
            "product_url": url,
            "title": title,
            "source": raw_source,
            "first_seen_at": first_seen.isoformat(),
            "last_seen_at": current_iso,
            "deal_expires_at": expiry.isoformat() if expiry else "",
            "listed_current_price": int(row.get("current_price") or old.get("listed_current_price") or 0),
            "listed_original_price": int(row.get("original_price") or old.get("listed_original_price") or 0),
            "discount_percent": int(row.get("discount_percent") or old.get("discount_percent") or 0),
            "savings_toman": int(row.get("savings_toman") or old.get("savings_toman") or 0),
            "review_count": max(0, int(row.get("review_count") or old.get("review_count") or 0)),
            "rating": row.get("rating") or row.get("rating_value") or old.get("rating") or 0,
            "click_count_30d": max(0, int(row.get("click_count_30d") or old.get("click_count_30d") or 0)),
            "demand_score": max(0, int(row.get("demand_score") or old.get("demand_score") or 0)),
            "promo_score": max(0, int(row.get("promo_score") or old.get("promo_score") or 0)),
        }
        # New candidates are immediately due for their first detailed validation.
        record.setdefault("last_check_status", "discovered")
        record.setdefault("check_count", 0)
        record.setdefault("last_checked_at", "")
        record.setdefault("next_check_at", "")
        queue[pid] = record
        if old:
            updated += 1
        else:
            added += 1

    # Expired offers are never re-queued for publication. Candidates without a verified
    # deadline are retained only for a bounded window so a later feed refresh can enrich them.
    for pid, record in list(queue.items()):
        if not isinstance(record, dict):
            queue.pop(pid, None)
            continue
        url = safe_product_url(record.get("product_url", ""))
        if not url or product_id(url) != str(pid):
            queue.pop(pid, None)
            continue
        expiry = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
        if expiry and expiry <= current:
            queue.pop(pid, None)
            continue
        if not expiry:
            last_seen = _parse_utc_datetime(record.get("last_seen_at")) or _parse_utc_datetime(record.get("first_seen_at"))
            if last_seen and (current - last_seen).total_seconds() > DISCOVERY_QUEUE_TTL_HOURS * 3600:
                queue.pop(pid, None)

    if len(queue) > DISCOVERY_QUEUE_LIMIT:
        ordered = sorted(
            queue.items(),
            key=lambda pair: discovery_queue_sort_key(pair[1], current),
            reverse=True,
        )
        keep_ids = {pid for pid, _ in ordered[:DISCOVERY_QUEUE_LIMIT]}
        for pid in list(queue):
            if pid not in keep_ids:
                queue.pop(pid, None)

    due_now = sum(
        1 for row in queue.values()
        if not _parse_utc_datetime(row.get("next_check_at"))
        or _parse_utc_datetime(row.get("next_check_at")) <= current
    )
    print(
        f"DISCOVERY_QUEUE seen={len(candidates) if isinstance(candidates, list) else 0} "
        f"added={added} refreshed={updated} retained={len(queue)} due_for_check={due_now}"
    )
    return queue



def _is_specific_product_family(category: str, family: str) -> bool:
    """Only apply the hard family cooldown to real subfamilies, not broad/unknown buckets."""
    category = str(category or "").strip()
    family = str(family or "").strip()
    return bool(family and family not in {"other", "unknown"} and family != category)


def _candidate_demand_comparable_for_diversity(candidate: dict, leader: dict) -> bool:
    """Allow variety only when demand, recent clicks, and deal discount remain reasonably close."""
    candidate = candidate if isinstance(candidate, dict) else {}
    leader = leader if isinstance(leader, dict) else {}
    if _candidate_demand_score(candidate) < _candidate_demand_score(leader) - 18:
        return False
    leader_discount = max(0, int(leader.get("discount_percent") or 0))
    candidate_discount = max(0, int(candidate.get("discount_percent") or 0))
    # Discount fields are sometimes absent before live detail validation.
    # Missing data is unknown, not a known zero-percent offer; enforce the
    # quality comparison only when both candidates have measured discounts.
    if leader_discount > 0 and candidate_discount > 0:
        minimum_comparable_discount = max(0, leader_discount - 25)
        if candidate_discount < minimum_comparable_discount:
            return False
    return True


def _diversify_ranked_records(
    records,
    limit: int | None = None,
    published: dict | None = None,
    recent_publications: list | None = None,
    label: str = "DISCOVERY",
    now: datetime | None = None,
):
    """Balance categories over 24 hours while keeping demand as the primary rank."""
    source = list(records or [])
    cap = len(source) if limit is None else max(0, int(limit))
    if cap <= 0 or not source:
        return []
    if not (published or recent_publications):
        return source[:cap]
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    try:
        recent = _recent_publication_diversity(
            published, limit=2000, durable_history=recent_publications, now=current
        )
    except Exception as exc:
        print(f"{label}_DIVERSITY_HISTORY_UNAVAILABLE error={type(exc).__name__}")
        return source[:cap]
    if not recent:
        return source[:cap]
    category_counts, family_counts, brand_counts = {}, {}, {}
    recent_product_ids = []
    for post in recent:
        category = str(post.get("category") or "other")
        family = str(post.get("family") or category)
        brand = str(post.get("brand") or "")
        category_counts[category] = category_counts.get(category, 0) + 1
        family_counts[family] = family_counts.get(family, 0) + 1
        if brand:
            brand_counts[brand] = brand_counts.get(brand, 0) + 1
        recent_product_ids.append(str(post.get("product_id") or ""))
    now_ts = current.timestamp()
    recent_categories = [
        str(post.get("category") or "other") for post in recent
        if float(post.get("order") or post.get("ts") or 0) >= now_ts - CATEGORY_REPEAT_COOLDOWN_MINUTES * 60
    ]
    recent_families = [
        str(post.get("family") or post.get("category") or "other") for post in recent
        if float(post.get("order") or post.get("ts") or 0) >= now_ts - FAMILY_REPEAT_COOLDOWN_HOURS * 3600
    ]
    recent_brands = [
        str(post.get("brand") or "") for post in recent
        if post.get("brand") and float(post.get("order") or post.get("ts") or 0) >= now_ts - BRAND_REPEAT_COOLDOWN_HOURS * 3600
    ]
    remaining, selected = list(source), []
    selection_anchor = None

    def _as_product(entry):
        if isinstance(entry, tuple) and len(entry) >= 2 and isinstance(entry[1], dict):
            return {**entry[1], "product_id": str(entry[0])}
        return entry if isinstance(entry, dict) else {}

    while remaining and len(selected) < cap:
        # A specific family published inside its cooldown window is ineligible.
        # Filter the full ranked pool before lookahead so a repeated leader cannot
        # win via a last-resort fallback or hide alternatives just beyond lookahead.
        fresh_remaining = []
        skipped_families = []
        for entry in remaining:
            item = _as_product(entry)
            category, family, _ = _publication_diversity_group(item)
            if _is_specific_product_family(category, family) and family in recent_families:
                skipped_families.append(family)
                continue
            fresh_remaining.append(entry)
        if skipped_families:
            print(
                f"{label}_DIVERSITY_FAMILY_COOLDOWN_SKIP "
                f"count={len(skipped_families)} families={','.join(sorted(set(skipped_families))[:5])}"
            )
        remaining = fresh_remaining
        if not remaining:
            break
        lookahead = remaining[:DIVERSITY_LOOKAHEAD_CANDIDATES]
        if selection_anchor is None:
            # The first eligible candidate becomes the fixed demand baseline for
            # this detail-check batch. Do not refill empty slots with much weaker
            # products after the repeated family has been filtered out.
            selection_anchor = _as_product(lookahead[0])
        leader = selection_anchor
        comparable = [
            (position, entry, _as_product(entry))
            for position, entry in enumerate(lookahead)
            if (not selected and position == 0)
            or _candidate_demand_comparable_for_diversity(_as_product(entry), leader)
        ]
        if not comparable:
            # Demand is a ranking signal, not a hard eligibility gate. Continue with
            # the next best remaining record so a large catalog can fill the bounded
            # live-detail budget and reveal the next available discount tier.
            print(
                f"{label}_DIVERSITY_DEMAND_GAP_CONTINUE "
                f"selected={len(selected)} baseline_product_id={leader.get('product_id') or 'unknown'} "
                f"next_product_id={_as_product(lookahead[0]).get('product_id') or 'unknown'}"
            )
            comparable = [(0, lookahead[0], _as_product(lookahead[0]))]
        ranked = []
        for position, entry, item in comparable:
            category, family, brand = _publication_diversity_group(item)
            pid = str(item.get("product_id") or item.get("id") or product_id(item.get("product_url") or item.get("url") or ""))
            penalty = float(position * 20)
            penalty += min(360.0, category_counts.get(category, 0) * 45.0)
            penalty += min(440.0, family_counts.get(family, 0) * 55.0)
            if brand:
                penalty += min(240.0, brand_counts.get(brand, 0) * 35.0)
            if category in recent_categories:
                penalty += 150.0
            if family in recent_families:
                penalty += 210.0
            if brand and brand in recent_brands:
                penalty += 160.0
            if pid and pid in recent_product_ids:
                penalty += 250.0
            ranked.append((penalty, position, entry, pid, category, family, brand))
        allowed = [
            row for row in ranked
            if row[4] not in recent_categories and row[5] not in recent_families
            and (not row[6] or row[6] not in recent_brands)
        ]
        if not allowed:
            allowed = [row for row in ranked if row[4] not in recent_categories and row[5] not in recent_families]
        if not allowed:
            allowed = [row for row in ranked if row[5] not in recent_families]
        if not allowed:
            allowed = [row for row in ranked if row[4] not in recent_categories]
        _, position, entry, pid, category, family, brand = min(allowed or ranked, key=lambda row: (row[0], row[1]))
        if position:
            print(f"{label}_DIVERSITY_REORDER product_id={pid or 'unknown'} original_rank={position + 1} category={category} family={family}")
        selected.append(entry)
        remaining.pop(position)
        category_counts[category] = category_counts.get(category, 0) + 1
        family_counts[family] = family_counts.get(family, 0) + 1
        if brand:
            brand_counts[brand] = brand_counts.get(brand, 0) + 1
        if pid:
            recent_product_ids.append(pid)
        recent_categories = (recent_categories + [category])[-3:]
        recent_families = (recent_families + [family])[-14:]
        if brand:
            recent_brands = (recent_brands + [brand])[-9:]
    return selected


def select_discovery_records_for_check(
    queue: dict[str, dict],
    now: datetime | None = None,
    max_count: int | None = None,
    published: dict | None = None,
    recent_publications: list | None = None,
) -> list[tuple[str, dict]]:
    """Select due, purchase-ready candidates by demand and deal value."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    limit = MAX_DISCOVERY_QUEUE_CHECKS if max_count is None else max(0, int(max_count))
    due = []
    for raw_pid, record in (queue.items() if isinstance(queue, dict) else []):
        pid = str(raw_pid)
        if not isinstance(record, dict):
            continue
        url = safe_product_url(record.get("product_url", ""))
        if not url or product_id(url) != pid:
            continue
        expiry = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
        # Open-ended offers may use a bounded detail check. Only a known expired
        # or too-near deadline is ineligible; live stock/price is checked afterwards.
        if expiry is not None and (
            expiry <= current or not has_minimum_publication_runway(record, current)
        ):
            continue
        next_check = _parse_utc_datetime(record.get("next_check_at"))
        if next_check and next_check > current:
            continue
        due.append((pid, record))
    due.sort(key=lambda pair: discovery_queue_sort_key(pair[1], current), reverse=True)
    selected = _diversify_ranked_records(
        due, limit=limit, published=published,
        recent_publications=recent_publications, label="DISCOVERY_QUEUE", now=current,
    )
    print(f"DISCOVERY_QUEUE_CHECK_BATCH due={len(due)} selected={len(selected)} limit={limit}")
    return selected


def mark_discovery_candidate_checked(
    queue: dict[str, dict],
    product_or_id: dict | str,
    status: str,
    now: datetime | None = None,
) -> None:
    """Record a detail-check result and schedule a bounded retry without discarding the discovery record."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    if isinstance(product_or_id, dict):
        product = product_or_id
        pid = str(product.get("product_id") or product_id(product.get("product_url", "")))
    else:
        product = {}
        raw = str(product_or_id or "")
        pid = raw if re.fullmatch(r"(?:dkp|snp)-\d{1,12}", raw) else product_id(raw)
    record = queue.get(pid) if isinstance(queue, dict) else None
    if not isinstance(record, dict):
        return

    record["last_checked_at"] = current.isoformat()
    record["last_check_status"] = str(status or "checked")[:80]
    record["check_count"] = max(0, int(record.get("check_count") or 0)) + 1
    if product:
        for source_key, target_key in (
            ("title", "title"),
            ("current_price", "last_checked_price"),
            ("original_price", "last_checked_original_price"),
            ("discount_percent", "discount_percent"),
            ("savings_toman", "savings_toman"),
            ("demand_score", "demand_score"),
            ("review_count", "review_count"),
        ):
            value = product.get(source_key)
            if value not in (None, ""):
                record[target_key] = str(value)[:180] if target_key == "title" else value
        refreshed_expiry = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
        if refreshed_expiry:
            record["deal_expires_at"] = refreshed_expiry.isoformat()

    expiry = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
    if expiry and expiry <= current:
        queue.pop(pid, None)
        return
    minutes_left = (expiry - current).total_seconds() / 60 if expiry else None
    if minutes_left is not None and minutes_left <= 30:
        retry_minutes = 5
    elif minutes_left is not None and minutes_left <= 90:
        retry_minutes = 10
    elif status == "eligible":
        retry_minutes = 10
    elif status == "fetch_failed":
        retry_minutes = 10 if minutes_left is not None else 30
    else:
        retry_minutes = 15 if minutes_left is not None else 30
    record["next_check_at"] = (current + timedelta(minutes=retry_minutes)).isoformat()


def mcp_scan_pages_for_cursor(page_count: int, cursor: int, pages_per_scan: int = 2):
    """Always read the newest live-offer page and rotate the supplemental page(s)."""
    try:
        count = max(1, min(5, int(page_count)))
    except (TypeError, ValueError, OverflowError):
        count = 1
    if count == 1:
        return [1], 1
    try:
        start = int(cursor)
    except (TypeError, ValueError, OverflowError):
        start = 2
    if start < 2 or start > count:
        start = 2
    try:
        extra_count = max(0, min(count - 1, int(pages_per_scan) - 1))
    except (TypeError, ValueError, OverflowError):
        extra_count = 1
    pages = [1]
    next_cursor = start
    for _ in range(extra_count):
        pages.append(next_cursor)
        next_cursor = 2 if next_cursor >= count else next_cursor + 1
    return pages, next_cursor


def _discovery_candidate_budgets(max_checks: int) -> tuple[int, int]:
    """Return (early-source cap, rotating category-search reserve).

    The reserved slots are for targeted category searches at the end of discovery.
    A retailer source or a warm queue must not be able to consume those slots early.
    """
    try:
        cap = max(1, int(max_checks))
    except (TypeError, ValueError, OverflowError):
        cap = 1
    reserve = min(20, max(1, cap // 3)) if cap > 1 else 0
    return max(1, cap - reserve), reserve


def _snappshop_retry_cooldown_minutes(consecutive_failures: int) -> int:
    """Back off a retailer that repeatedly blocks every supported public entry point."""
    try:
        failures = max(1, int(consecutive_failures))
    except (TypeError, ValueError, OverflowError):
        failures = 1
    return min(24 * 60, 6 * 60 * (2 ** min(failures - 1, 2)))


def _discovery_early_source_candidate_limit(
    presearch_candidate_limit: int,
    retailer_reserved_slots: int,
    usable_optional_retailer_candidates: int,
) -> int:
    """Release every unused optional-retailer slot back to the primary DigiKala pool."""
    try:
        cap = max(1, int(presearch_candidate_limit))
    except (TypeError, ValueError, OverflowError):
        cap = 1
    try:
        reserved = max(0, min(cap - 1, int(retailer_reserved_slots)))
    except (TypeError, ValueError, OverflowError):
        reserved = 0
    try:
        usable = max(0, int(usable_optional_retailer_candidates))
    except (TypeError, ValueError, OverflowError):
        usable = 0
    unused_reserve = max(0, reserved - min(reserved, usable))
    return max(1, cap - unused_reserve)


def _rotating_search_terms(slot: int, batch_size: int) -> list[str]:
    """Rotate by a full query batch, not one term, to cover the catalog quickly."""
    if not SEARCH_TERMS:
        return []
    try:
        safe_slot = max(0, int(slot))
    except (TypeError, ValueError, OverflowError):
        safe_slot = 0
    try:
        safe_batch = max(1, min(len(SEARCH_TERMS), int(batch_size)))
    except (TypeError, ValueError, OverflowError):
        safe_batch = 1
    offset = (safe_slot * safe_batch) % len(SEARCH_TERMS)
    return SEARCH_TERMS[offset:] + SEARCH_TERMS[:offset]


def discover_product_urls(
    queued_records: dict[str, dict] | None = None,
    discovery_queue: dict[str, dict] | None = None,
    state_to_persist: dict | None = None,
) -> tuple[list[str], list[dict], dict[str, str]]:
    """Recheck persisted offers first, scan every live-deal page, then rotate broader searches."""
    found = []
    diagnostics = []
    queued_records = queued_records if isinstance(queued_records, dict) else {}
    queue_now = datetime.now(timezone.utc)
    queued_expiries: dict[str, str] = {}
    # Compute the cap before touching the persistent queue. This is deliberately
    # first: the normal five-minute scan often begins with queued candidates, so a
    # later assignment used to raise UnboundLocalError and abort every live scan.
    presearch_candidate_limit, search_reserve = _discovery_candidate_budgets(MAX_PRODUCT_CHECKS)
    # Hold a small reserve for SnappShop provisionally. If its API yields fewer
    # usable candidates, the unused capacity is returned to DigiKala in this scan.
    early_source_candidate_limit = _discovery_early_source_candidate_limit(
        presearch_candidate_limit, SNAPPSHOP_RESERVED_CANDIDATES, 0
    )
    print(
        f"DISCOVERY_SOURCE_BUDGET checks={MAX_PRODUCT_CHECKS} "
        f"early_sources_cap={early_source_candidate_limit} "
        f"reserved_snappshop_candidates={SNAPPSHOP_RESERVED_CANDIDATES} "
        f"reserved_rotating_search_slots={search_reserve}"
    )

    # Recheck persistent candidates, but do not let already-published/cooldown items
    # consume discovery slots before the live feed and rotating search terms run.
    queued_repeat_or_active_skips = 0
    for pid, record in select_queued_records_for_recheck(
        queued_records, queue_now
    ):
        if len(found) >= early_source_candidate_limit:
            break
        if (
            not is_fresh_selection_candidate(state_to_persist or {}, pid, record, queue_now)
            and not _has_pending_channel_retry(state_to_persist or {}, pid)
        ):
            queued_repeat_or_active_skips += 1
            continue
        canonical = safe_product_url(record.get("product_url", ""))
        deadline = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
        if not canonical or (deadline is not None and deadline <= queue_now):
            continue
        found.append(canonical)
        if deadline is not None:
            queued_expiries[str(pid)] = deadline.isoformat()
    if queued_repeat_or_active_skips:
        print(
            "DISCOVERY_PENDING_QUEUE_FILTERED "
            f"repeat_or_active={queued_repeat_or_active_skips}"
        )

    publish_history = state_to_persist.get("published", {}) if isinstance(state_to_persist, dict) else {}
    recent_history = state_to_persist.get("recent_publications", []) if isinstance(state_to_persist, dict) else []

    # The catalog crawler runs on its own schedule and writes an acknowledged
    # candidate sidecar. Import its fresh listing-card candidates into the same
    # bounded discovery queue used by the existing deep price/stock verification.
    # This path is deliberately best-effort: a crawler/schema problem must never
    # stop the normal live-offer feed or the publishing cycle.
    if isinstance(discovery_queue, dict) and isinstance(state_to_persist, dict):
        try:
            handoff_limit = max(
                1, min(80, int(os.getenv("AFFILIO_CATALOG_SWEEP_HANDOFF_PER_RUN", "40")))
            )
            catalog_batch = load_catalog_candidates_for_handoff(
                CATALOG_SWEEP_CANDIDATES,
                state_to_persist,
                max_count=handoff_limit,
                now=queue_now,
            )
            if catalog_batch:
                merge_discovery_queue(discovery_queue, catalog_batch, queue_now)
                state_to_persist["discovery_queue"] = discovery_queue
            print(
                f"CATALOG_SWEEP_HANDOFF candidates={len(catalog_batch)} "
                f"limit={handoff_limit} backlog_source={CATALOG_SWEEP_CANDIDATES.name}"
            )
        except Exception as exc:
            print(f"CATALOG_SWEEP_HANDOFF_FAILED error={type(exc).__name__}; normal_discovery_continues=true")

    # The live Incredible Offers feed is the primary discovery source.
    deals_found = []
    deal_expiries: dict[str, str] = dict(queued_expiries)
    direct_feed_expiries: dict[str, str] = {}
    mcp_card_expiries: dict[str, str] = {}
    for page_number in range(1, DEAL_LIST_PAGES + 1):
        try:
            response = SESSION.get(
                "https://api.digikala.com/v1/incredible-offers/products/",
                params={"page": page_number, "q": ""},
                timeout=HTTP_TIMEOUT,
            )
            response.raise_for_status()
            if len(response.content) > 8_000_000:
                raise RuntimeError("incredible offers API response exceeded 8 MB")
            payload = response.json()
            local = api_incredible_offer_product_candidates(payload)
            deals_found.extend(local)
            # Capture the first-party page's own timer immediately. Later MCP data
            # may fill gaps but must never replace this product's source timer.
            for candidate_row in local:
                candidate_pid = product_id(candidate_row.get("product_url", ""))
                candidate_deadline = str(candidate_row.get("deal_expires_at") or "").strip()
                if candidate_pid and candidate_deadline:
                    candidate_row["expiry_source"] = "digikala_live_deals_feed"
                    candidate_row["expiry_deadline_verified_directly"] = True
                    candidate_row["expiry_estimated"] = False
                    direct_feed_expiries[candidate_pid] = candidate_deadline
                    deal_expiries[candidate_pid] = candidate_deadline
            diagnostics.append({
                "term": f"incredible_offers_page_{page_number}",
                "ok": bool(local),
                "products_found": len(local),
                "source": "incredible_offers_api",
                "status": "ok" if local else "no_discounted_product_urls",
            })
            timed_urls = sum(bool(str(row.get("deal_expires_at") or "").strip()) for row in local)
            print(
                f"INCREDIBLE_OFFERS_API page={page_number} status={response.status_code} "
                f"discounted_urls={len(local)} timed_urls={timed_urls} "
                f"data_keys={list(payload.get('data', {}).keys())[:24] if isinstance(payload, dict) and isinstance(payload.get('data'), dict) else 'n/a'}"
            )
            if page_number == 1 and local and timed_urls == 0:
                deadline_nodes = []
                deadline_field_names = set()
                for node in _walk_dicts(payload):
                    if not isinstance(node, dict):
                        continue
                    relevant = {
                        str(key): value
                        for key, value in node.items()
                        if any(term in str(key).lower() for term in ("end", "expir", "countdown", "remaining", "campaign"))
                    }
                    if relevant:
                        deadline_field_names.update(relevant.keys())
                        if len(deadline_nodes) < 3:
                            deadline_nodes.append({
                                "product_id": node.get("id") or node.get("product_id"),
                                "title": str(node.get("title_fa") or node.get("product_title") or node.get("title") or "")[:100],
                                "fields": list(relevant.keys())[:20],
                            })
                print(
                    "FIRST_PARTY_DEADLINE_DIAGNOSTIC "
                    + json.dumps({
                        "page": page_number,
                        "timer_fields_anywhere": sorted(deadline_field_names)[:40],
                        "sample_nodes": deadline_nodes,
                    }, ensure_ascii=False, sort_keys=True)
                )
            if not local:
                # An empty/partial page is not proof that later pages are empty.
                continue
        except Exception as exc:
            diagnostics.append({
                "term": f"incredible_offers_page_{page_number}",
                "ok": False,
                "products_found": 0,
                "source": "incredible_offers_api",
                "status": type(exc).__name__,
            })
            print(f"INCREDIBLE_OFFERS_API_FAILED page={page_number} error={type(exc).__name__} detail={str(exc)[:180]!r}")
            # Keep trying the remaining pages; a transient failure on page 1 must not
            # suppress offers visible on another page.

    # Persist direct-feed sightings before the slower MCP countdown request. If MCP is slow
    # or the later detail-check stage fails, this first set of candidates is already on disk.
    if isinstance(discovery_queue, dict) and deals_found:
        merge_discovery_queue(discovery_queue, deals_found, queue_now)
        if isinstance(state_to_persist, dict):
            state_to_persist["discovery_queue"] = discovery_queue
            save_json(STATE, state_to_persist)
        print(f"DISCOVERY_QUEUE_PERSISTED stage=direct_feed retained={len(discovery_queue)}")

    # MCP page 1 yielded all usable timed offers on recent scans, while later
    # pages often returned no cards. Always refresh page 1, then rotate a supplement.
    mcp_cursor = 2
    if isinstance(state_to_persist, dict) and DEAL_LIST_PAGES > 1:
        try:
            mcp_cursor = int(state_to_persist.get("mcp_offer_page_cursor", 2) or 2)
        except (TypeError, ValueError, OverflowError):
            mcp_cursor = 2
    mcp_scan_pages, next_mcp_cursor = mcp_scan_pages_for_cursor(
        DEAL_LIST_PAGES, mcp_cursor, MCP_OFFER_PAGES_PER_SCAN
    )
    mcp_expiries = {}
    try:
        from expiration_monitor import fetch_mcp_offer_candidates
        mcp_expiries, mcp_candidate_nodes = fetch_mcp_offer_candidates(page_numbers=mcp_scan_pages)
        for pid, expiry in mcp_expiries.items():
            # The MCP wrapper returns current DigiKala offer-card timers keyed by exact
            # product ID. Keep this source distinct and strictly lower priority than
            # DigiKala's own REST responses; never mix in a cached queue deadline.
            if str(pid) not in direct_feed_expiries and str(expiry or "").strip():
                clean_expiry = str(expiry).strip()
                deal_expiries[str(pid)] = clean_expiry
                mcp_card_expiries[str(pid)] = clean_expiry
        mcp_candidates = api_incredible_offer_product_candidates(mcp_candidate_nodes)
        for row in mcp_candidates:
            pid = product_id(row.get("product_url", ""))
            expiry = str(
                direct_feed_expiries.get(pid)
                or row.get("deal_expires_at")
                or mcp_expiries.get(pid)
                or deal_expiries.get(pid)
                or ""
            ).strip()
            if expiry:
                row["deal_expires_at"] = expiry
                if pid not in direct_feed_expiries:
                    deal_expiries[pid] = expiry
        deals_found.extend(mcp_candidates)

        # Save these additional sightings before ranking or deep product-page checks.
        if isinstance(discovery_queue, dict):
            merge_discovery_queue(discovery_queue, mcp_candidates, datetime.now(timezone.utc))
        if isinstance(state_to_persist, dict):
            state_to_persist["mcp_offer_page_cursor"] = next_mcp_cursor
            if isinstance(discovery_queue, dict):
                state_to_persist["discovery_queue"] = discovery_queue
            save_json(STATE, state_to_persist)

        print(
            f"MCP_OFFER_CANDIDATES pages={mcp_scan_pages} extracted={len(mcp_candidates)} "
            f"deadline_verified={sum(bool(row.get('deal_expires_at')) for row in mcp_candidates)} "
            f"next_cursor={next_mcp_cursor}"
        )
    except Exception as exc:
        print(f"EXPIRY_MCP_LOOKUP_FAILED error={type(exc).__name__} detail={str(exc)[:140]!r}")

    best_by_url = {}
    for row in deals_found:
        url = row["product_url"]
        if (
            is_prohibited_product_title(row.get("title", ""))
            or not is_publishable_product_title(row.get("title", ""))
        ):
            continue
        pid = product_id(url)
        expiry = str(
            direct_feed_expiries.get(pid)
            or row.get("deal_expires_at")
            or deal_expiries.get(pid)
            or ""
        ).strip()
        if expiry:
            row["deal_expires_at"] = expiry
            if pid not in direct_feed_expiries:
                deal_expiries[pid] = expiry
        old = best_by_url.get(url)
        key = (int(bool(expiry)), int(row.get("discount_percent") or 0), int(row.get("savings_toman") or 0))
        old_key = (
            int(bool(old and old.get("deal_expires_at"))),
            int(old.get("discount_percent") or 0),
            int(old.get("savings_toman") or 0),
        ) if old else (-1, -1, -1)
        if old is None or key > old_key:
            best_by_url[url] = row
        elif old and not old.get("deal_expires_at") and expiry:
            best_by_url[url]["deal_expires_at"] = expiry

    discovery_now = datetime.now(timezone.utc)

    def discovery_key(row):
        # Use the same candidate-ranking policy as the persistent queue. Exact
        # deadline is only a later tie-breaker, never the lead ranking field.
        return discovery_queue_sort_key(row, discovery_now)

    # Persist the full discovered candidate set before applying the per-run detail-check budget.
    # The selected batch below is only a work queue; it does not cap what we remember.
    if isinstance(discovery_queue, dict):
        merge_discovery_queue(discovery_queue, list(best_by_url.values()), discovery_now)
        queued_due = select_discovery_records_for_check(
            discovery_queue, discovery_now,
            published=publish_history, recent_publications=recent_history,
        )
        queued_added = 0
        excluded_repeat_or_active_queue_candidates = 0
        for pid, record in queued_due:
            queued_url = safe_product_url(record.get("product_url", ""))
            if not queued_url or queued_url in found or len(found) >= early_source_candidate_limit:
                continue
            # Previously published/queued products are not new content candidates.
            # Failed Telegram/Bale delivery retries remain discoverable through the
            # separate pending-delivery path, but must never reserve a fresh slot.
            if (
                not is_fresh_selection_candidate(state_to_persist or {}, pid, record, discovery_now)
                and not _has_pending_channel_retry(state_to_persist or {}, pid)
            ):
                excluded_repeat_or_active_queue_candidates += 1
                continue
            found.append(queued_url)
            queued_added += 1
            queued_expiry = _parse_utc_datetime(_parse_deal_expiry_value(record.get("deal_expires_at")))
            if queued_expiry:
                deal_expiries[pid] = queued_expiry.isoformat()
        print(
            f"DISCOVERY_QUEUE_URLS_ADDED count={queued_added} "
            f"already_selected_or_capacity={len(queued_due) - queued_added - excluded_repeat_or_active_queue_candidates} "
            f"excluded_repeat_or_active={excluded_repeat_or_active_queue_candidates}"
        )

    eligible_discovery_deals = []
    skipped_short_or_expired = 0
    skipped_repeat_or_active = 0
    for row in best_by_url.values():
        pid = product_id(row.get("product_url", ""))
        # Rank unseen/currently publishable products above repeatedly surfaced
        # products. Otherwise the top feed rows can all be inside cooldown, leaving
        # one already-published item as the only hand-off candidate.
        if (
            not is_fresh_selection_candidate(state_to_persist or {}, pid, row, discovery_now)
            and not _has_pending_channel_retry(state_to_persist or {}, pid)
        ):
            skipped_repeat_or_active += 1
            continue
        expiry = _parse_utc_datetime(_parse_deal_expiry_value(row.get("deal_expires_at")))
        if expiry is None:
            # Keep unknown deadlines behind verified, actionable offers; detail checks
            # may later recover an authoritative deadline from the product page.
            eligible_discovery_deals.append(row)
            continue
        remaining = (expiry - discovery_now).total_seconds()
        if expiry <= discovery_now or remaining < MIN_PUBLICATION_RUNWAY_MINUTES * 60:
            skipped_short_or_expired += 1
            continue
        eligible_discovery_deals.append(row)

    sorted_deals = sorted(eligible_discovery_deals, key=discovery_key, reverse=True)
    selected_deals = _diversify_ranked_records(
        sorted_deals, limit=MAX_INCREDIBLE_OFFER_CANDIDATES,
        published=publish_history, recent_publications=recent_history,
        label="INCREDIBLE_FEED",
    )
    print(
        f"DEAL_DEMAND_ORDER pool={len(best_by_url)} eligible={len(eligible_discovery_deals)} "
        f"selected={len(selected_deals)} skipped_expired_or_short={skipped_short_or_expired} "
        f"skipped_repeat_or_active={skipped_repeat_or_active}"
    )

    for row in selected_deals:
        url = row["product_url"]
        if url not in found and len(found) < early_source_candidate_limit:
            found.append(url)
        pid = product_id(url)
        expiry = str(row.get("deal_expires_at") or deal_expiries.get(pid) or "").strip()
        if expiry:
            deal_expiries[pid] = expiry

    print(
        f"DEAL_DISCOVERY unique_filtered_urls={len(best_by_url)} "
        f"selected_incredible_offers={len(selected_deals)} "
        f"verified_deadline_candidates={sum(bool(str(row.get('deal_expires_at') or '').strip()) for row in selected_deals)}"
    )

    # SnappShop blocks homepage HTML requests from this runner (403), so query the
    # public JSON surface used by its frontend. Its internal API IDs differ from
    # the public /product/snp-... suffix, so persist the mapping for later detail checks.
    search_slot = int(time.time() // 300)
    global SNAPPSHOP_API_IDS_BY_URL, SNAPPSHOP_SEARCH_CARDS_BY_URL
    SNAPPSHOP_SEARCH_CARDS_BY_URL = {}
    saved_api_ids = state_to_persist.get("snappshop_api_ids", {}) if isinstance(state_to_persist, dict) else {}
    SNAPPSHOP_API_IDS_BY_URL = {}
    if isinstance(saved_api_ids, dict):
        for raw_url, raw_id in saved_api_ids.items():
            canonical = safe_product_url(str(raw_url))
            api_id = str(raw_id or "").strip()
            if canonical and product_id(canonical).startswith("snp-") and api_id:
                SNAPPSHOP_API_IDS_BY_URL[canonical] = api_id

    # SnappShop is an optional source. After repeated failures from both its API
    # and indexable public pages, pause only this source with bounded backoff.
    snapp_candidates = []
    snapp_queries = []
    snappshop_queries_succeeded = 0
    snappshop_query_failures = []
    snappshop_access_denied = False
    snapp_fallback_found = []
    snapp_fallback_failures = []
    snapp_fallback_sources = [
        ("category", "https://snappshop.ir/category/digital"),
        ("category", "https://snappshop.ir/category/home"),
        ("category", "https://snappshop.ir/category/beauty"),
        ("category", "https://snappshop.ir/category/fashion"),
        ("category", "https://snappshop.ir/category/supermarket"),
        ("sitemap", "https://snappshop.ir/sitemap.xml"),
        ("sitemap", "https://snappshop.ir/sitemap/v1/static_0.xml"),
        ("sitemap", "https://snappshop.ir/plus/sitemap_index.xml"),
    ]
    snappshop_status = "not_attempted"
    retry_until = _parse_utc_datetime(
        state_to_persist.get("snappshop_retry_after") if isinstance(state_to_persist, dict) else None
    )
    snappshop_cooldown_active = bool(retry_until and retry_until > datetime.now(timezone.utc))
    if snappshop_cooldown_active:
        snappshop_status = "cooldown"
        print(
            f"SNAPPSHOP_OPTIONAL_SOURCE_COOLDOWN retry_at={retry_until.isoformat()} "
            "primary_digikala_discovery_continues=true"
        )

    # SnappShop discovery shares the early-source budget. It cannot consume the
    # reserved slots needed for rotating DigiKala category searches below.
    if len(found) < presearch_candidate_limit and not snappshop_cooldown_active:
        snapp_queries = _rotating_search_terms(search_slot, SNAPPSHOP_QUERIES_PER_SCAN)[:SNAPPSHOP_QUERIES_PER_SCAN]
        headers = _snappshop_request_headers()
        for term in snapp_queries:
            response = None
            try:
                response = SESSION.post(
                    f"{SNAPPSHOP_API_BASE_URL}/search/v1",
                    params={"lat": SNAPPSHOP_LATITUDE, "lng": SNAPPSHOP_LONGITUDE},
                    json={"query": term, "render": 4},
                    headers=headers,
                    timeout=SNAPPSHOP_HTTP_TIMEOUT,
                )
                response.raise_for_status()
                snappshop_queries_succeeded += 1
                if len(response.content) > 8_000_000:
                    raise RuntimeError("SnappShop search API response exceeded 8 MB")
                payload = response.json()
                items = _snappshop_search_items(payload)
                added_this_query = 0
                discounted_seen = 0
                for card in items:
                    raw_href = str(card.get("href") or card.get("url") or "").strip()
                    candidate = safe_product_url(urljoin("https://snappshop.ir/", raw_href))
                    if not candidate or not product_id(candidate).startswith("snp-"):
                        continue
                    raw_api_id = card.get("id") or card.get("product_id")
                    if raw_api_id is None or not str(raw_api_id).strip():
                        # Without the retailer's internal API identity the public
                        # product slug cannot be live-validated; don't waste a slot.
                        continue
                    SNAPPSHOP_API_IDS_BY_URL[candidate] = str(raw_api_id).strip()
                    SNAPPSHOP_SEARCH_CARDS_BY_URL[candidate] = card
                    price_obj = card.get("price") if isinstance(card.get("price"), dict) else {}
                    listed = _money_to_toman(price_obj.get("price") or price_obj.get("original_price"), "IRR")
                    discounted = _money_to_toman(price_obj.get("discounted_price") or price_obj.get("special_price"), "IRR")
                    if not listed or not discounted or discounted >= listed:
                        continue
                    discount = round(100 * (listed - discounted) / listed)
                    savings = listed - discounted
                    discount_candidate = {
                        **card,
                        "current_price": discounted,
                        "discount_percent": discount,
                        "savings_toman": savings,
                    }

                    # Keep discounted cards in discovery so demand is ranked first;
                    # the same discount floor is enforced before publication.
                    discounted_seen += 1
                    if candidate not in snapp_candidates:
                        snapp_candidates.append(candidate)
                    if candidate not in found and len(found) < presearch_candidate_limit:
                        found.append(candidate)
                        added_this_query += 1
                    if len(snapp_candidates) >= min(12, MAX_PER_QUERY * 2):
                        break
                print(
                    f"SNAPPSHOP_API_SEARCH term={term!r} status={response.status_code} "
                    f"cards={len(items)} discounted_candidates={discounted_seen} added={added_this_query}"
                )
            except Exception as exc:
                status_code = getattr(response, "status_code", None)
                failure = {
                    "term": term,
                    "error": type(exc).__name__,
                    "http_status": int(status_code) if isinstance(status_code, int) else None,
                }
                snappshop_query_failures.append(failure)
                if status_code == 403:
                    # A host-level access denial is not a query-specific miss.
                    # Stop probing the same blocked domain in this scan.
                    snappshop_access_denied = True
                print(
                    f"SNAPPSHOP_API_SEARCH_FAILED term={term!r} "
                    f"error={type(exc).__name__} http_status={failure['http_status']} "
                    f"detail={str(exc)[:160]!r}"
                )
                if snappshop_access_denied:
                    print("SNAPPSHOP_HOST_ACCESS_DENIED stop_repeating_requests=true")
                    break
        if isinstance(state_to_persist, dict):
            state_to_persist["snappshop_api_ids"] = dict(list(SNAPPSHOP_API_IDS_BY_URL.items())[-1000:])
        if snapp_candidates:
            snappshop_status = "ok"
        elif snappshop_access_denied:
            snappshop_status = "host_access_denied"
        elif snappshop_queries_succeeded == 0:
            snappshop_status = "api_unavailable"
        elif snappshop_query_failures:
            snappshop_status = "partial_api_failure_no_discounted_cards"
        else:
            snappshop_status = "no_discounted_product_cards"
        diagnostics.append({
            "term": "snappshop_public_api_search",
            "ok": bool(snapp_candidates),
            "products_found": len(snapp_candidates),
            "source": "snappshop_public_api",
            "status": snappshop_status,
            "queries_attempted": len(snapp_queries),
            "queries_succeeded": snappshop_queries_succeeded,
            "queries_failed": len(snappshop_query_failures),
            "query_failures": snappshop_query_failures,
        })
        print(
            f"SNAPPSHOP_DISCOVERY source=public_api queries={len(snapp_queries)} "
            f"products={len(snapp_candidates)} retained_api_ids={len(SNAPPSHOP_API_IDS_BY_URL)}"
        )

        # Fallback discovery is attempted only after the API attempt, and only
        # while the optional source is not in cooldown.
        if not snappshop_access_denied and len(snapp_candidates) < min(12, MAX_PER_QUERY * 2):
            for fallback_kind, fallback_url in snapp_fallback_sources:
                if len(snapp_fallback_found) >= min(24, MAX_PRODUCT_CHECKS):
                    break
                fallback_response = None
                try:
                    fallback_response = SESSION.get(
                        fallback_url, headers=headers, timeout=SNAPPSHOP_HTTP_TIMEOUT,
                    )
                    fallback_response.raise_for_status()
                    if len(fallback_response.content) > 12_000_000:
                        raise RuntimeError("SnappShop fallback response exceeded 12 MB")
                    content_type = str(fallback_response.headers.get("content-type") or "").lower()
                    if fallback_kind == "sitemap" or "xml" in content_type or fallback_response.text.lstrip().startswith("<?xml"):
                        soup_fallback = BeautifulSoup(fallback_response.content, "xml")
                        hrefs = [node.get_text(strip=True) for node in soup_fallback.find_all("loc")]
                    else:
                        soup_fallback = BeautifulSoup(fallback_response.text, "html.parser")
                        hrefs = [urljoin(fallback_response.url, a.get("href", "")) for a in soup_fallback.select("a[href]")]
                    added_fallback = 0
                    for raw_href in hrefs:
                        candidate = safe_product_url(urljoin(fallback_response.url, raw_href))
                        if not candidate or not product_id(candidate).startswith("snp-"):
                            continue
                        if candidate not in snapp_fallback_found:
                            snapp_fallback_found.append(candidate)
                            added_fallback += 1
                        # Sitemap/category URLs alone lack the API ID needed for
                        # live stock/price verification, so never hand them to publisher.
                        if len(snapp_fallback_found) >= min(24, MAX_PRODUCT_CHECKS):
                            break
                    print(
                        f"SNAPPSHOP_FALLBACK kind={fallback_kind} url={fallback_url} "
                        f"status={fallback_response.status_code} added={added_fallback}"
                    )
                except Exception as exc:
                    status_code = getattr(fallback_response, "status_code", None)
                    snapp_fallback_failures.append({
                        "kind": fallback_kind, "url": fallback_url,
                        "error": type(exc).__name__,
                        "http_status": int(status_code) if isinstance(status_code, int) else None,
                    })
                    if status_code == 403:
                        snappshop_access_denied = True
                    print(
                        f"SNAPPSHOP_FALLBACK_FAILED kind={fallback_kind} url={fallback_url} "
                        f"error={type(exc).__name__} http_status={status_code}"
                    )
                    if snappshop_access_denied:
                        print("SNAPPSHOP_HOST_ACCESS_DENIED stop_repeating_requests=true")
                        break
        if snapp_fallback_found:
            diagnostics.append({
                "term": "snappshop_public_pages_fallback", "ok": True,
                "products_found": len(snapp_fallback_found),
                "source": "public_category_pages_or_sitemaps", "status": "ok",
                "failures": snapp_fallback_failures,
            })
        else:
            diagnostics.append({
                "term": "snappshop_public_pages_fallback", "ok": False,
                "products_found": 0,
                "source": "public_category_pages_or_sitemaps",
                "status": (
                    "skipped_host_access_denied" if snappshop_access_denied
                    else "unavailable" if snapp_fallback_failures
                    else "no_product_urls"
                ),
                "failures": snapp_fallback_failures,
            })
        print(
            f"SNAPPSHOP_DISCOVERY_FALLBACK products={len(snapp_fallback_found)} "
            f"failed_sources={len(snapp_fallback_failures)}"
        )

        # Set a source-local cooldown only when every query and every public
        # fallback failed. Other discovery sources and destination publishers
        # continue normally. A successful API response resets the failure streak.
        if snappshop_queries_succeeded > 0:
            # The public API is reachable even if this rotating query batch has no
            # products above the campaign floor; stop carrying an obsolete outage.
            if isinstance(state_to_persist, dict):
                state_to_persist.pop("snappshop_retry_after", None)
                state_to_persist["snappshop_consecutive_failures"] = 0
        elif (
            snapp_queries
            and (
                (snappshop_access_denied and snappshop_queries_succeeded == 0)
                or len(snappshop_query_failures) == len(snapp_queries)
            )
        ):
            try:
                previous_failures = (
                    state_to_persist.get("snappshop_consecutive_failures", 0)
                    if isinstance(state_to_persist, dict) else 0
                )
                failures = max(0, int(previous_failures or 0)) + 1
            except (TypeError, ValueError, OverflowError):
                failures = 1
            cooldown_minutes = _snappshop_retry_cooldown_minutes(failures)
            retry_at = datetime.now(timezone.utc) + timedelta(minutes=cooldown_minutes)
            if isinstance(state_to_persist, dict):
                state_to_persist["snappshop_consecutive_failures"] = failures
                state_to_persist["snappshop_retry_after"] = retry_at.isoformat()
            snappshop_status = "api_and_public_pages_unavailable_backoff"
            print(
                f"SNAPPSHOP_OPTIONAL_SOURCE_BACKOFF failures={failures} "
                f"cooldown_minutes={cooldown_minutes} retry_at={retry_at.isoformat()} "
                "primary_digikala_discovery_continues=true"
            )
        if isinstance(state_to_persist, dict):
            save_json(STATE, state_to_persist)

    if snappshop_cooldown_active:
        diagnostics.append({
            "term": "snappshop_optional_source",
            "ok": False,
            "products_found": 0,
            "source": "snappshop_public_api",
            "status": "cooldown",
            "retry_after": retry_until.isoformat(),
        })

    # Rebalance unused optional-retailer capacity immediately. A blocked or
    # empty SnappShop source must never reduce DigiKala coverage or starve the
    # existing category-search rotation.
    usable_snappshop_candidates = min(
        SNAPPSHOP_RESERVED_CANDIDATES, len(snapp_candidates)
    ) if "snapp_candidates" in locals() else 0
    rebalanced_limit = _discovery_early_source_candidate_limit(
        presearch_candidate_limit,
        SNAPPSHOP_RESERVED_CANDIDATES,
        usable_snappshop_candidates,
    )
    if rebalanced_limit > early_source_candidate_limit:
        previous_limit = early_source_candidate_limit
        early_source_candidate_limit = rebalanced_limit
        recovered = 0
        for row in selected_deals:
            if len(found) >= early_source_candidate_limit:
                break
            url = str(row.get("product_url") or "").strip()
            if url and url not in found:
                found.append(url)
                recovered += 1
                pid = product_id(url)
                expiry = str(row.get("deal_expires_at") or deal_expiries.get(pid) or "").strip()
                if expiry:
                    deal_expiries[pid] = expiry
        print(
            f"DISCOVERY_SOURCE_BUDGET_REBALANCED primary=digikala "
            f"previous_cap={previous_limit} new_cap={early_source_candidate_limit} "
            f"usable_snappshop_candidates={usable_snappshop_candidates} "
            f"recovered_digikala_candidates={recovered}"
        )
    elif usable_snappshop_candidates:
        print(
            f"DISCOVERY_SOURCE_BUDGET_RETAINED snappshop_candidates={usable_snappshop_candidates} "
            f"early_sources_cap={early_source_candidate_limit}"
        )
    else:
        print(
            "SNAPPSHOP_OPTIONAL_SOURCE_UNAVAILABLE "
            f"status={snappshop_status if 'snappshop_status' in locals() else 'not_attempted'} "
            "primary_digikala_discovery_continues=true"
        )

    # The reserved slot count determines batch stride. The expanded 90-term
    # catalog is swept in five scans when 20 category-search slots are available.
    search_offset = (search_slot * max(1, search_reserve)) % len(SEARCH_TERMS)
    rotated_search_terms = _rotating_search_terms(search_slot, max(1, search_reserve))
    print(f"SEARCH_ROTATION offset={search_offset} batch_size={max(1, search_reserve)} first_term={rotated_search_terms[0]!r}")

    # Fill remaining slots with targeted searches for tech, home, and practical gadgets.
    for term in rotated_search_terms:
        if len(found) >= MAX_PRODUCT_CHECKS:
            break
        local = []
        api_error = ""
        try:
            response = SESSION.get(
                "https://api.digikala.com/v1/search/",
                params={"q": term, "page": 1},
                timeout=HTTP_TIMEOUT,
            )
            response.raise_for_status()
            if len(response.content) > 8_000_000:
                raise RuntimeError("search API response exceeded 8 MB")
            payload = response.json()
            local = api_search_product_urls(payload)
            print(
                f"SEARCH_API term={term!r} status={response.status_code} "
                f"data_keys={list(payload.get('data', {}).keys())[:24] if isinstance(payload, dict) and isinstance(payload.get('data'), dict) else 'n/a'} "
                f"sample={json.dumps(_search_api_sample(payload), ensure_ascii=False)[:700]}"
            )
            if local:
                diagnostics.append({"term": term, "ok": True, "products_found": len(local), "source": "public_api", "status": "ok"})
            else:
                api_error = "api_no_product_urls"
        except Exception as exc:
            api_error = type(exc).__name__
            print(f"SEARCH_API_FAILED term={term!r} error={type(exc).__name__} detail={str(exc)[:220]!r}")

        if not local:
            try:
                search_url = f"https://www.digikala.com/search/?q={quote(term)}"
                final_url, page = fetch_page(search_url)
                soup = BeautifulSoup(page, "html.parser")
                for a in soup.select("a[href]"):
                    candidate = safe_product_url(urljoin(final_url, a.get("href", "")))
                    if candidate and candidate not in local:
                        local.append(candidate)
                    if len(local) >= MAX_PER_QUERY:
                        break
            except Exception as exc:
                print(f"HTML_DISCOVERY_FAILED term={term!r} error={type(exc).__name__}")
            if local:
                diagnostics.append({"term": term, "ok": True, "products_found": len(local), "source": "html_fallback", "status": "ok"})
            else:
                diagnostics.append({"term": term, "ok": False, "products_found": 0, "source": "api_and_html", "status": api_error or "no_product_urls"})

        added = 0
        # Limit each rotated query to one new product; a busy first query must not
        # suppress all later product categories in this scan.
        for url in local:
            if url not in found and len(found) < MAX_PRODUCT_CHECKS and added < 1:
                found.append(url)
                added += 1
        print(f"DISCOVERY term={term!r} products={len(local)} added={added} source={diagnostics[-1].get('source')}")
    return found, diagnostics, deal_expiries, direct_feed_expiries, mcp_card_expiries


def classify_category(title: str) -> str:
    value = (title or "").lower().replace("\u200c", " ")
    # Specific product families first; "other" should be the true fallback.
    patterns = [
        # Keep dedicated families ahead of broad matches; otherwise the rotation can't see them as distinct.
        ("mobile_devices", r"گوشی\s*(?:موبایل|هوشمند)|گوشی\s+(?:سامسونگ|شیائومی|ردمی|پوکو|اپل|آیفون|هواوی|آنر|نوکیا|realme)|آیفون|iphone|smartphone|mobile phone|تبلت|آیپد|ipad"),
        ("tv_audio_video", r"تلویزیون|android\s*tv|smart\s*tv|پروژکتور|سینما خانگی|گیرنده دیجیتال|اندروید باکس|دوربین عکاسی|لنز دوربین|camcorder"),
        ("large_appliances", r"یخچال|فریزر|ماشین لباسشویی|لباسشویی|ماشین ظرفشویی|ظرفشویی|کولر گازی|اسپلیت|بخاری برقی|آبگرمکن|اجاق گاز|فر توکار|مایکروویو|آون توستر"),
        ("power_backup", r"پاور\s*بانک|شارژر|باتری|چراغ اضطراری|برق اضطراری|چراغ قوه|چراغ دستی"),
        ("lighting", r"چراغ پیشانی|هدلامپ|چراغ مطالعه|چراغ خواب|چراغ روشنایی|چراغ کار|لامپ|نورافکن|چراغ کمپینگ|ریسه روشنایی"),
        ("home_cleaning", r"جارو(?:برقی| شارژی)?|تی زمین شوی|تی چرخشی|زمین شوی|بخارشوی|مواد شوینده|شوینده سطوح|تمیزکننده سطوح|دستمال نظافت|نظافت خانه"),
        ("pet_supplies", r"حیوانات خانگی|حیوان خانگی|غذای سگ|غذای گربه|تشویقی سگ|تشویقی گربه|قلاده|خاک گربه|اسکرچر|پد بهداشتی سگ"),
        ("arts_crafts", r"بوم نقاشی|لوازم نقاشی|لوازم هنری|قلم طراحی|رنگ اکریلیک|رنگ روغن|لوازم خیاطی|چرخ خیاطی|کاموا|قلاب بافی|بافتنی"),
        ("presentation_tools", r"لیزر پوینتر|پوینتر ارائه|ریموت ارائه|کنترل ارائه"),
        ("audio_wearables", r"هندزفری|هدفون|ایرپاد|اسپیکر|ساعت\s*هوشمند|اسمارت\s*واچ"),
        ("digital_accessories", r"کابل|مبدل|گلس|محافظ صفحه|قاب گوشی|پایه نگهدارنده|فلش مموری|هاب\s*usb|نگهدارنده گوشی"),
        ("computer_network", r"لپ\s*تاپ|لپتاپ|کامپیوتر|مینی\s*پی\s*سی|کارت گرافیک|پردازنده|\bcpu\b|\bgpu\b|حافظه\s*(?:اس\s*اس\s*دی|ssd|رم)|\bram\b|\bssd\b|مودم|روتر|مانیتور|پرینتر|کیبورد|ماوس"),
        # Put children before sport terms so «کفش ورزشی کودک» remains a kids product.
        ("kids_sports", r"نوزاد|نوزادی|کودک|اسباب\s*بازی|بازی فکری|بازی آموزشی"),
        ("sports_outdoor", r"ورزشی|کمپینگ|کوهنوردی|سفر و طبیعت|دوچرخه|اسکی|شنا|بدنسازی|دمبل|تردمیل|توپ فوتبال|چادر مسافرتی"),
        ("gaming", r"گیم|بازی ویدیویی|بازی رایانه.?ای|بازی کامپیوتری|کنسول|پلی\s*استیشن|xbox"),
        ("jewelry", r"زیورآلات|بدلیجات|گوشواره|انگشتر|دستبند|گردنبند|نقره زنانه|نقره مردانه|پرسته"),
        ("books_stationery", r"کتاب|دفتر|خودکار|مداد|لوازم التحریر|لوازم‌التحریر|نوشت افزار"),
        ("beauty_fragrance", r"عطر|ادکلن|ادو\s*پرفیوم|ادوپرفیوم|ادو\s*تویلت|ادوتویلت|تستر\s*ادو|بادی\s*اسپلش"),
        ("personal_care", r"پوست|(?<!\w)مو(?!\w)|کرم|سرم|آبرسان|اصلاح|ماساژور|بهداشت|آرایش|ضدآفتاب|مسواک|دندان|سشوار|برس حرارتی|اتو مو|ریش.?تراش|موزن|اپیلاتور|دستگاه بخور|تونر|پاک کننده آرایش|سنگ پا|پاشنه کش|سوهان پا"),
        ("automotive", r"خودرو|ماشین|موتور سیکلت|داشبورد|کمپرسور باد|لوازم خودرو|شارژر فندکی|روکش صندلی|کفپوش خودرو|مراقبت خودرو"),
        ("home", r"آشپزخانه|نظم دهنده|ارگانایزر|خردکن|ظرف|ابزار آشپزخانه|خانه|قهوه ساز|فلاسک|ماگ|قمقمه|بطری آب|ظروف|حمام|سرویس بهداشتی|باغبانی|گلدان"),
        ("fashion", r"تی\s*شرت|تیشرت|پولو\s*شرت|پولوشرت|سویشرت|سوییشرت|هودی|شلوار|بلوز|شومیز|تاپ|مانتو|دامن|پیراهن|پوشاک|لباس|کفش|صندل|بوت|کاپشن|کوله|کیف|جاکارتی|کمربند|کراوات|کلاه|دستکش|جوراب|زیرپوش|شورت|شال|روسری|عینک|ساعت مچی|لباس زیر|مام فیت|پالتو"),
    ]
    for category, pattern in patterns:
        if re.search(pattern, value, re.I):
            return category
    return "other"


def score_product(p: dict) -> dict:
    # Category is retained for diagnostics only; it never adds or subtracts ranking points.
    category = classify_category(p.get("title", ""))
    score = 0
    # Product price and category never define demand; high-ticket goods compete on
    # the same retailer review/rating signals as low-priced goods.
    price = p.get("current_price")

    original = p.get("original_price")
    if original and price and original > price:
        discount = round(100 * (original - price) / original)
        p["discount_percent"] = max(0, min(100, discount))
        p["savings_toman"] = int(original - price)
    else:
        p["discount_percent"] = 0
        p["savings_toman"] = 0

    rating = p.get("rating")
    if rating is not None:
        if rating >= 4.5:
            score += 12
        elif rating >= 4.0:
            score += 9
        elif rating >= 3.5:
            score += 5
        elif rating < 3.0:
            score -= 5

    reviews = max(0, int(p.get("review_count") or 0))
    # Review volume and rating are demand proxies; deal value belongs in promo_score.
    score += min(30, round(3.5 * math.log1p(reviews)))
    # Image availability is an eligibility requirement, not a market-demand signal.

    discount_pct = int(p.get("discount_percent") or 0)
    savings = int(p.get("savings_toman") or 0)
    savings_score = min(20, round(3.0 * math.log1p(savings / 100_000))) if savings else 0
    review_score = min(10, round(1.5 * math.log1p(reviews))) if reviews else 0
    p["category"] = category
    p["historical_popularity_score"] = max(0, min(100, int(score)))
    p["current_demand_verified"] = has_current_demand_signal(p)
    p["current_demand_score"] = (
        _candidate_demand_score(p) if p["current_demand_verified"]
        else p["historical_popularity_score"]
    )
    p["demand_score"] = p["current_demand_score"]
    # Offer quality is scored independently from lifetime reviews and ratings.
    p["promo_score"] = max(0, min(100, int(discount_pct * 0.65 + savings_score)))
    p["qualifies_as_deal"] = has_meaningful_discount(p)
    return p



def deal_sort_key(p: dict) -> tuple:
    """Rank broad product popularity first, recent activity second, then the largest live markdown."""
    verified_median = (
        p.get("market_status") == "verified"
        and p.get("market_reference_kind") == "seller_median"
        and p.get("market_price_advantage_pct") is not None
    )
    market_known = 1 if verified_median else 0
    try:
        market_advantage = int(p.get("market_price_advantage_pct") or 0) if verified_median else -101
    except (TypeError, ValueError, OverflowError):
        market_advantage = -101
    try:
        reviews = max(0, int(p.get("review_count") or 0))
        rating_score = round(float(p.get("rating") or p.get("rating_value") or 0) * 10)
    except (TypeError, ValueError, OverflowError):
        reviews = 0
        rating_score = 0
    return (
        _candidate_popularity_score(p),
        reviews,
        rating_score,
        _candidate_demand_score(p),
        max(0, int(p.get("discount_percent") or 0)),
        market_known, market_advantage, int(has_meaningful_discount(p)),
        int(p.get("promo_score") or 0), max(0, int(p.get("savings_toman") or 0)),
    )

def _fetch_click_statistics_snapshot() -> dict:
    """Fetch a complete aggregate 30-day click snapshot; analytics outages never block publication."""
    base = AFFILIO_CLICK_TRACKER_BASE_URL.strip().rstrip("/")
    if not base.startswith("https://"):
        print("CLICK_STATS_UNAVAILABLE reason=tracker_url_not_https")
        return {}
    try:
        response = SESSION.get(
            f"{base}/stats",
            headers={"Accept": "application/json", "User-Agent": "AffilioRadarAnalytics/1.0"},
            timeout=(4, 8),
        )
        response.raise_for_status()
        payload = response.json()
        products = payload.get("products") if isinstance(payload, dict) else None
        if payload.get("ok") is not True or payload.get("complete") is not True or not isinstance(products, dict):
            print("CLICK_STATS_UNAVAILABLE reason=incomplete_or_invalid_snapshot")
            return {}
        return payload
    except Exception as exc:
        print(f"CLICK_STATS_UNAVAILABLE error={type(exc).__name__}")
        return {}


def _valid_click_counts(raw_counts) -> dict[str, int]:
    if not isinstance(raw_counts, dict):
        return {}
    counts = {}
    for pid, raw_count in raw_counts.items():
        if not re.fullmatch(r"(?:dkp-\d{1,12}|snp-\d{1,20})", str(pid)):
            continue
        try:
            count = int(raw_count)
        except (TypeError, ValueError, OverflowError):
            continue
        if count >= 0:
            counts[str(pid)] = count
    return counts


def fetch_click_statistics() -> dict[str, int]:
    """Return aggregate click totals by product for backwards-compatible ranking."""
    payload = _fetch_click_statistics_snapshot()
    counts = _valid_click_counts(payload.get("products") if isinstance(payload, dict) else {})
    if payload:
        print(
            f"CLICK_STATS_LOADED days={payload.get('days', 30)} products={len(counts)} "
            f"total_clicks={int(payload.get('totalClicks') or 0)} "
            f"updated_at={payload.get('updatedAt', 'unknown')}"
        )
    return counts


def enrich_click_statistics(products: list[dict]) -> None:
    """Attach aggregate 30-day click counts; source-level click details stay private in Cloudflare KV."""
    counts = fetch_click_statistics()
    for product in products:
        pid = str(product.get("product_id") or product_id(product.get("product_url", "")))
        product["click_count_30d"] = counts.get(pid, 0)


def load_catalog() -> list[dict]:
    try:
        data = json.loads(CONFIG.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return []
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"Could not read {CONFIG}: {type(exc).__name__}") from exc
    items = data.get("products", []) if isinstance(data, dict) else []
    valid = []
    for item in items if isinstance(items, list) else []:
        if not isinstance(item, dict):
            continue
        product_url = safe_product_url(item.get("product_url", ""))
        affiliate_url = str(item.get("affiliate_url", "")).strip()
        parsed_aff = urlsplit(affiliate_url) if affiliate_url else None
        if not product_url:
            print("CATALOG_SKIP invalid product_url")
            continue
        if not parsed_aff or parsed_aff.scheme != "https" or not parsed_aff.netloc:
            print(f"CATALOG_SKIP {product_id(product_url)} no valid HTTPS Affilio link")
            continue
        valid.append({**item, "product_url": product_url, "affiliate_url": affiliate_url})
    return valid


def load_state(*, apply_integrity_ledger: bool = True) -> dict:
    try:
        data = json.loads(STATE.read_text(encoding="utf-8"))
        state = data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError):
        state = {}
    # Overlay confirmed price/discount/stock invalidations and platform deletion
    # outcomes from the independent audit ledger, without a concurrent state write.
    if apply_integrity_ledger:
        apply_integrity_audit_ledger(state)
    return state


def save_json(path: Path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def link_map(catalog: list[dict]) -> dict:
    return {product_id(item["product_url"]): item for item in catalog if product_id(item["product_url"])}


def is_publish_eligible(product: dict) -> bool:
    """A post requires confirmed stock, current price, image, and affiliate link."""
    return bool(
        product.get("availability") == "in_stock"
        and product.get("current_price")
        and product.get("image_url")
        and str(product.get("affiliate_url", "")).startswith("https://")
    )


def is_discount_publish_eligible(
    product: dict,
    minimum_discount_percent: int | None = None,
    now: datetime | None = None,
) -> bool:
    """Require verified stock/price/image, a valid product, and a genuine markdown."""
    return bool(
        is_publish_eligible(product)
        and not is_prohibited_product_title(product.get("title", ""))
        and is_publishable_product_title(product.get("title", ""))
        and has_meaningful_discount(product, minimum_discount_percent)
    )


def _shape(text: str) -> str:
    return get_display(arabic_reshaper.reshape(str(text or "")))


def _font(size: int, bold=False):
    candidates = [
        "/usr/share/fonts/truetype/noto/NotoSansArabic-Bold.ttf" if bold else "/usr/share/fonts/truetype/noto/NotoSansArabic-Regular.ttf",
        "/usr/share/fonts/truetype/noto/NotoNaskhArabic-Bold.ttf" if bold else "/usr/share/fonts/truetype/noto/NotoNaskhArabic-Regular.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    ]
    for path in candidates:
        if Path(path).exists():
            try:
                return ImageFont.truetype(path, size=size)
            except OSError:
                pass
    return ImageFont.load_default()


def _latin_font(size: int):
    """Return a Latin-capable bold font for ASCII badge labels such as '89% OFF'."""
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
    ]
    for path in candidates:
        if Path(path).exists():
            try:
                return ImageFont.truetype(path, size=size)
            except OSError:
                pass
    return ImageFont.load_default()


def format_price(value):
    return f"{int(value):,} تومان" if value else "در صفحه محصول بررسی شود"


def gregorian_to_jalali(gy: int, gm: int, gd: int) -> tuple[int, int, int]:
    """Convert a Gregorian calendar date to the Solar Hijri (Jalali) calendar."""
    g_days_before_month = (0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334)
    if not 1 <= gm <= 12 or not 1 <= gd <= 31:
        raise ValueError("Invalid Gregorian month or day")
    if gy > 1600:
        jy = 979
        gy -= 1600
    else:
        jy = 0
        gy -= 621
    gy2 = gy + 1 if gm > 2 else gy
    days = (
        365 * gy
        + (gy2 + 3) // 4
        - (gy2 + 99) // 100
        + (gy2 + 399) // 400
        - 80
        + gd
        + g_days_before_month[gm - 1]
    )
    jy += 33 * (days // 12053)
    days %= 12053
    jy += 4 * (days // 1461)
    days %= 1461
    if days > 365:
        jy += (days - 1) // 365
        days = (days - 1) % 365
    if days < 186:
        jm = 1 + days // 31
        jd = 1 + days % 31
    else:
        jm = 7 + (days - 186) // 30
        jd = 1 + (days - 186) % 30
    return jy, jm, jd


def format_deal_expiry(value) -> str:
    """Format a confirmed deal deadline as a Persian date and Iran-local time."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        try:
            from zoneinfo import ZoneInfo
            local = parsed.astimezone(ZoneInfo("Asia/Tehran"))
        except Exception:
            local = parsed.astimezone(timezone(timedelta(hours=3, minutes=30)))
        # For display only, represent an exact midnight cutoff as the preceding
        # calendar day at 23:59, which is clearer for Persian-language audiences.
        if local.hour == 0 and local.minute == 0:
            local -= timedelta(minutes=1)
        jalali_year, jalali_month, jalali_day = gregorian_to_jalali(
            local.year, local.month, local.day
        )
    except (TypeError, ValueError, OverflowError):
        return ""
    weekdays = {
        "Monday": "دوشنبه", "Tuesday": "سه‌شنبه", "Wednesday": "چهارشنبه",
        "Thursday": "پنجشنبه", "Friday": "جمعه", "Saturday": "شنبه", "Sunday": "یکشنبه",
    }
    months = {
        1: "فروردین", 2: "اردیبهشت", 3: "خرداد", 4: "تیر",
        5: "مرداد", 6: "شهریور", 7: "مهر", 8: "آبان",
        9: "آذر", 10: "دی", 11: "بهمن", 12: "اسفند",
    }
    rendered = (
        f"{weekdays.get(local.strftime('%A'), '')} {jalali_day} "
        f"{months[jalali_month]} {jalali_year}، ساعت {local:%H:%M}"
    )
    return rendered.translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))


def to_persian_digits(value) -> str:
    """Render ASCII digits with Persian digits and thousands separators."""
    return str(value).translate(str.maketrans("0123456789,", "۰۱۲۳۴۵۶۷۸۹٬"))


def format_persian_number(value) -> str:
    """Format an integer using Persian digits and the Persian thousands separator."""
    return to_persian_digits(f"{int(value):,}")


def unicode_strikethrough(value: str) -> str:
    """Render a visible strike-through without relying on a platform's text-markup parser."""
    overlay = "\u0336"
    return "".join(char if char.isspace() else char + overlay for char in str(value))


def unicode_underline(value: str) -> str:
    """Render an underline for Bale clients without relying on undocumented markup."""
    overlay = "\u0332"
    return "".join(char if char.isspace() else char + overlay for char in str(value))


def format_remaining_time(
    value,
    now: datetime | None = None,
    safety_buffer_minutes: int = 0,
) -> str:
    """Display a deadline countdown, optionally stopping before the source-site cutoff."""
    deadline = _parse_utc_datetime(value)
    if deadline is None:
        return ""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    try:
        buffer_minutes = max(0, min(30, int(safety_buffer_minutes)))
    except (TypeError, ValueError, OverflowError):
        buffer_minutes = 0
    effective_deadline = deadline - timedelta(minutes=buffer_minutes)
    remaining_seconds = (effective_deadline - current).total_seconds()
    if remaining_seconds <= 0:
        return "مهلت آفر به پایان رسیده"
    if remaining_seconds < 60:
        return "کمتر از ۱ دقیقه مانده به پایان تخفیف"
    remaining_minutes = math.floor(remaining_seconds / 60)
    hours, minutes = divmod(remaining_minutes, 60)
    duration = []
    if hours:
        duration.append(f"{format_persian_number(hours)} ساعت")
    if minutes:
        duration.append(f"{format_persian_number(minutes)} دقیقه")
    return f"{' و '.join(duration)} مانده به پایان تخفیف"


def _escape_bale_markdown(value: str) -> str:
    """Escape characters that could change Bale's documented Markdown formatting."""
    return re.sub(r"([\\_*()\[\]])", lambda match: "\\" + match.group(1), str(value or ""))


def build_caption(
    p: dict,
    affiliate_url: str,
    channel_label: str = TELEGRAM_CHANNEL_URL,
    use_unicode_strikethrough: bool = False,
) -> str:
    """Build a concise cross-platform caption with a clear price hierarchy and channel CTA."""
    is_bale = use_unicode_strikethrough

    def bold(value: str) -> str:
        return f"*{value}*" if is_bale else f"<b>{value}</b>"

    raw_title = (p.get("title") or "پیشنهاد ویژه").strip()
    raw_title = to_persian_digits(raw_title)
    if len(raw_title) > 140:
        raw_title = raw_title[:137].rstrip() + "…"
    title = _escape_bale_markdown(raw_title) if is_bale else html.escape(raw_title)

    current = p.get("current_price")
    discount = p.get("discount_percent")
    channel_url = str(channel_label or (BALE_CHANNEL_URL if is_bale else TELEGRAM_CHANNEL_URL)).strip()
    if not urlsplit(channel_url).scheme:
        channel_url = "https://" + channel_url
    channel_href = html.escape(channel_url, quote=True)
    channel_text = (
        "➕ عضویت در کانال آفِرچین"
        if is_bale
        else "➕ عضویت در کانال آفِرچین"
    )
    if is_bale:
        channel_footer = f"[{channel_text}]({html.unescape(channel_href)})"
    else:
        channel_footer = f'<a href="{channel_href}">{channel_text}</a>'

    merchant = p.get("merchant") or product_merchant(p.get("product_url") or affiliate_url)
    merchant_marker = "🟣" if "اسنپ" in str(merchant) or "snapp" in str(merchant).lower() else "🔴"
    parts = [
        f"🔥 فروش ویژه {merchant} {merchant_marker}",
        "",
        f"🛍️ {title}",
    ]

    # Keep the offer's two decision-making facts prominent, with no list price,
    # savings amount, countdown, or redundant instruction to press the buy button.
    if current or (discount is not None and int(discount) > 0):
        parts += ["", "────────────"]
    if current:
        price = format_persian_number(current)
        parts.append(bold(f"💚 قیمت فعلی: {price} تومان"))
    if discount is not None and int(discount) > 0:
        discount_value = format_persian_number(discount) + "٪"
        parts.append(bold(f"⚡️ {discount_value} تخفیف"))
    # Show the installment notice consistently across all retailer posts.
    # The eligibility caveat avoids promising approval on products/accounts where
    # DigiPay does not present the option or the buyer does not qualify.
    parts.append("💳 امکان خرید اقساطی با دیجی‌پی (در صورت نمایش گزینه و احراز شرایط)")

    # Keep one source-channel membership link for forwarded posts; the purchase button
    # remains a separate inline button and its presence is validated by the sender.
    parts += ["", "────────────", "", channel_footer]
    caption = "\n".join(parts)
    if len(caption) > 1024:
        footer = f"\n\n────────────\n\n{channel_footer}"
        body = "\n".join(parts[:-4])
        caption = body[:1024 - len(footer)].rstrip() + footer
    return caption

def format_discount_badge(discount_percent) -> str:
    """Return a compact Persian badge label such as '۸۱٪ تخفیف'."""
    try:
        discount = int(discount_percent)
    except (TypeError, ValueError):
        return ""
    if not 0 < discount <= 100:
        return ""
    persian_digits = str(discount).translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))
    return f"{persian_digits}٪ تخفیف"


def _draw_platform_watermark_icon(draw, platform: str, x: int, y: int, size: int) -> None:
    """Draw a tiny self-contained platform mark so each card remains dependency-free."""
    right, bottom = x + size, y + size
    if platform == "telegram":
        # Telegram's recognizable paper-plane mark in its blue circular field.
        draw.ellipse((x, y, right, bottom), fill="#2AABEE", outline="#ffffff", width=max(1, size // 16))
        plane = [
            (x + size * 0.18, y + size * 0.43),
            (x + size * 0.82, y + size * 0.20),
            (x + size * 0.65, y + size * 0.81),
            (x + size * 0.48, y + size * 0.62),
            (x + size * 0.36, y + size * 0.72),
            (x + size * 0.39, y + size * 0.53),
        ]
        draw.polygon(plane, fill="#ffffff")
        draw.polygon([
            (x + size * 0.39, y + size * 0.53),
            (x + size * 0.65, y + size * 0.35),
            (x + size * 0.48, y + size * 0.62),
        ], fill="#BCEBFF")
        return

    # Bale's compact green/teal app mark with a white badge and check.
    draw.rounded_rectangle(
        (x, y, right, bottom),
        radius=max(3, size // 5),
        fill="#00B894",
        outline="#ffffff",
        width=max(1, size // 16),
    )
    inset = size * 0.18
    draw.ellipse((x + inset, y + inset, right - inset, bottom - inset), fill="#ffffff")
    draw.line(
        [
            (x + size * 0.31, y + size * 0.51),
            (x + size * 0.45, y + size * 0.65),
            (x + size * 0.70, y + size * 0.37),
        ],
        fill="#00B894",
        width=max(2, size // 8),
        joint="curve",
    )


def build_discount_image(
    image_bytes: bytes,
    discount_percent=None,
    watermark: str = "T.me/OfferChin",
    merchant: str = "دیجی‌کالا",
) -> bytes:
    """Prepare a product image with store identity, discount badge, and OfferChin channel watermark."""
    from io import BytesIO
    with Image.open(BytesIO(image_bytes)) as raw:
        raw.load()
        image = raw.convert("RGB")
    image.thumbnail((1600, 1600), Image.Resampling.LANCZOS)
    width, height = image.size
    min_dim = min(width, height)
    brand_margin = max(10, int(min_dim * 0.025))
    # Both top-corner tiles share one width. Reserve half the available canvas
    # width for each so equal-sized tiles cannot overlap on small source images.
    max_badge_width = max(1, (width - 2 * brand_margin) // 2)
    store_badge_width = min(max_badge_width, max(124, min(320, int(min_dim * 0.38))))
    store_badge_height = max(48, min(88, int(min_dim * 0.14)))
    label = format_discount_badge(discount_percent)
    draw = ImageDraw.Draw(image)
    if label:
        badge_width, badge_height = discount_badge_dimensions_for_reference_bounds(store_badge_width, store_badge_height)
        badge_left = max(0, width - brand_margin - badge_width)
        badge_top = brand_margin
        try:
            discount_value = int(discount_percent)
        except (TypeError, ValueError, OverflowError):
            discount_value = 0
        if 0 < discount_value <= 100:
            draw_discount_burst(
                draw,
                badge_left,
                badge_top,
                min(badge_width, width - badge_left),
                min(badge_height, height - badge_top),
                discount_value,
                merchant=merchant,
            )

    # Store identity sits opposite the discount tile; DigiKala additionally gets
    # the official DigiPay mark directly below it, at identical target dimensions.
    draw_retailer_badge(image, brand_margin, brand_margin, store_badge_width, store_badge_height, merchant)
    is_snappshop = "snapp" in str(merchant or "").lower() or "اسنپ" in str(merchant or "")
    if not is_snappshop:
        digipay_gap = max(4, int(store_badge_height * 0.08))
        draw_digipay_badge(
            image,
            brand_margin,
            brand_margin + store_badge_height + digipay_gap,
            store_badge_width,
            store_badge_height,
        )

    # Keep the channel IDs at the lower-left without a card or solid panel.
    # Choose each text color from the pixels directly behind it; use a thin opposing
    # stroke to retain legibility over both pale and dark product photography.
    watermarks = [("telegram", "T.me/OfferChin"), ("bale", "ble.ir/OfferChin")]
    margin = max(10, min_dim // 35)
    icon_size = max(12, min(48, min_dim // 32))
    icon_gap = max(5, icon_size // 4)
    row_gap = max(3, min_dim // 180)
    font = _latin_font(max(12, min_dim // 34))
    rows = []
    for platform, label_text in watermarks:
        box = draw.textbbox((0, 0), label_text, font=font)
        rows.append((platform, label_text, max(1, box[2]-box[0]), max(font.size, box[3]-box[1])))
    max_width = max(1, width - 2 * margin)
    while icon_size + icon_gap + max(r[2] for r in rows) > max_width and font.size > 9:
        font = _latin_font(font.size - 1)
        rows = []
        for platform, label_text in watermarks:
            box = draw.textbbox((0, 0), label_text, font=font)
            rows.append((platform, label_text, max(1, box[2]-box[0]), max(font.size, box[3]-box[1])))
    row_height = max(icon_size, max(r[3] for r in rows))
    box_top = max(0, height - margin - (2 * row_height + row_gap))
    stroke_width = max(1, min(3, min_dim // 320))
    for index, (platform, label_text, text_width, text_height) in enumerate(rows):
        row_top = box_top + index * (row_height + row_gap)
        icon_x = margin
        icon_y = row_top + (row_height - icon_size) // 2
        _draw_platform_watermark_icon(draw, platform, icon_x, icon_y, icon_size)
        text_x = icon_x + icon_size + icon_gap
        text_y = row_top + (row_height - text_height) // 2 + text_height // 2
        region = (text_x - 2, row_top - 1, min(width, text_x + text_width + 3), row_top + row_height + 2)
        fill, stroke = adaptive_text_colors(image, region)
        draw.text(
            (text_x, text_y), label_text, font=font, fill=fill, anchor="lm",
            stroke_width=stroke_width, stroke_fill=stroke,
        )
    output = BytesIO()
    image.save(output, format="JPEG", quality=92, optimize=True)
    return output.getvalue()


def _fetch_image(url: str) -> bytes:
    if not url or urlsplit(url).scheme != "https":
        raise RuntimeError("No safe HTTPS product image URL")

    # Retry only transient connection/timeout/server failures. A short second attempt
    # reduces the chance that a temporary CDN handshake issue blocks both photo channels.
    attempts = 2
    for attempt in range(1, attempts + 1):
        response = None
        try:
            response = SESSION.get(url, timeout=(8, HTTP_TIMEOUT), stream=True)
            response.raise_for_status()
            content_type = response.headers.get("Content-Type", "").lower()
            if not content_type.startswith("image/"):
                raise RuntimeError("product image URL did not return an image")
            parts, total = [], 0
            for chunk in response.iter_content(64 * 1024):
                if not chunk:
                    continue
                total += len(chunk)
                if total > 10_000_000:
                    raise RuntimeError("product image exceeded 10 MB")
                parts.append(chunk)
            data = b"".join(parts)
            from io import BytesIO
            with Image.open(BytesIO(data)) as check:
                check.verify()
            if attempt > 1:
                print(f"PRODUCT_IMAGE_FETCH_RETRY_OK attempt={attempt}")
            return data
        except requests.exceptions.RequestException as exc:
            retryable = isinstance(
                exc, (requests.exceptions.Timeout, requests.exceptions.ConnectionError)
            )
            if response is not None:
                status_code = getattr(response, "status_code", 0) or 0
                retryable = retryable or status_code in {408, 425, 429} or status_code >= 500
            if not retryable or attempt >= attempts:
                raise
            print(
                f"PRODUCT_IMAGE_FETCH_RETRY attempt={attempt} "
                f"error={type(exc).__name__}"
            )
            time.sleep(1)
        finally:
            if response is not None:
                try:
                    response.close()
                except Exception:
                    pass

    raise RuntimeError("product image fetch failed after bounded retry")


def _send_photo(photo_bytes: bytes, caption: str, affiliate_url: str = ""):
    if not BOT_TOKEN:
        raise RuntimeError("Missing TELEGRAM_BOT_TOKEN secret; no post sent")
    endpoint = f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto"
    data = {"chat_id": TARGET_CHAT, "caption": caption, "parse_mode": "HTML"}
    if not _is_valid_affilio_tracking_url(affiliate_url):
        raise RuntimeError("Refusing to publish or edit a post without a verified Affilio purchase button")
    button_url = tracked_affiliate_button_url(affiliate_url, "telegram")
    data["reply_markup"] = json.dumps({
        "inline_keyboard": [[{
            "text": purchase_button_label(affiliate_url),
            "url": button_url,
        }]]
    }, ensure_ascii=False)
    response = requests.post(
        endpoint,
        data=data,
        files={"photo": ("product.jpg", photo_bytes, "image/jpeg")},
        timeout=(20, 120),
    )
    response.raise_for_status()
    payload = response.json()
    if not payload.get("ok"):
        raise RuntimeError("Telegram sendPhoto returned ok=false")
    return payload["result"]


def _send_bale_photo(photo_bytes: bytes, caption: str, affiliate_url: str = ""):
    """Send a photo post through Bale's Bot API, independently of Telegram delivery."""
    if not BALE_BOT_TOKEN:
        raise RuntimeError("Missing BALE_BOT_TOKEN secret")
    if not BALE_CHANNEL_ID:
        raise RuntimeError("Missing BALE_CHANNEL_ID secret")
    endpoint = f"https://tapi.bale.ai/bot{BALE_BOT_TOKEN}/sendPhoto"
    data = {"chat_id": BALE_CHANNEL_ID, "caption": caption}
    if not _is_valid_affilio_tracking_url(affiliate_url):
        raise RuntimeError("Refusing to publish or edit a post without a verified Affilio purchase button")
    button_url = tracked_affiliate_button_url(affiliate_url, "bale")
    data["reply_markup"] = json.dumps({
        "inline_keyboard": [[{
            "text": purchase_button_label(affiliate_url),
            "url": button_url,
        }]]
    }, ensure_ascii=False)
    response = requests.post(
        endpoint,
        data=data,
        files={"photo": ("product.jpg", photo_bytes, "image/jpeg")},
        timeout=(20, 120),
    )
    response.raise_for_status()
    payload = response.json()
    if not payload.get("ok") or not isinstance(payload.get("result"), dict):
        # Never include the request URL: it contains the private bot token.
        description = str(payload.get("description") or "Bale sendPhoto returned ok=false")
        raise RuntimeError(description[:180])
    return payload["result"]


def _delivery_retry_platforms(record: dict) -> list[str]:
    """Return failed destinations whose credentials are currently configured."""
    statuses = record.get("delivery_status")
    if record.get("delivery_version") != 1 or not isinstance(statuses, dict):
        return []
    platforms = []
    if statuses.get("telegram") == "failed" and BOT_TOKEN:
        platforms.append("telegram")
    if statuses.get("bale") == "failed" and BALE_BOT_TOKEN and BALE_CHANNEL_ID:
        platforms.append("bale")
    return platforms


def _has_pending_delivery(record: dict) -> bool:
    return bool(_delivery_retry_platforms(record))


def _send_platform_photo(platform: str, item: dict, image_bytes: bytes, affiliate_url: str):
    """Render and send only offers that pass their own selected discount tier."""
    raw_floor = item.get("selection_discount_floor")
    minimum_discount_percent = None
    if raw_floor is not None:
        try:
            minimum_discount_percent = int(raw_floor)
        except (TypeError, ValueError, OverflowError):
            raise RuntimeError("Refusing to send an OfferChin post with an invalid discount tier")
        if minimum_discount_percent not in DISCOUNT_FALLBACK_FLOORS:
            raise RuntimeError("Refusing to send an OfferChin post with an unsupported discount tier")
    if not is_discount_publish_eligible(
        item,
        minimum_discount_percent=minimum_discount_percent,
        now=datetime.now(timezone.utc),
    ):
        floor_label = minimum_discount_percent or DISCOUNT_FALLBACK_FLOORS[0]
        raise RuntimeError(
            "Refusing to send an OfferChin post that fails the hard discount/current-demand gate "
            f"({floor_label}% minimum plus verified recent activity)"
        )
    if platform == "telegram":
        photo = build_discount_image(
            image_bytes, item.get("discount_percent"),
            watermark="T.me/OfferChin", merchant=item.get("merchant") or "دیجی‌کالا",
        )
        return _send_photo(photo, build_caption(item, affiliate_url, TELEGRAM_CHANNEL_URL), affiliate_url)
    if platform == "bale":
        photo = build_discount_image(
            image_bytes, item.get("discount_percent"),
            watermark="ble.ir/OfferChin", merchant=item.get("merchant") or "دیجی‌کالا",
        )
        return _send_bale_photo(
            photo,
            build_caption(item, affiliate_url, BALE_CHANNEL_URL, use_unicode_strikethrough=True),
            affiliate_url,
        )
    raise ValueError("Unsupported publication platform")



def _edit_telegram_caption(message_id: int, caption: str, affiliate_url: str = ""):
    """Edit a published Telegram photo caption, retaining the purchase button and handling flood limits."""
    if not BOT_TOKEN:
        raise RuntimeError("Missing TELEGRAM_BOT_TOKEN secret")
    endpoint = f"https://api.telegram.org/bot{BOT_TOKEN}/editMessageCaption"
    data = {
        "chat_id": TARGET_CHAT,
        "message_id": int(message_id),
        "caption": caption,
        "parse_mode": "HTML",
    }
    if not _is_valid_affilio_tracking_url(affiliate_url):
        raise RuntimeError("Refusing to publish or edit a post without a verified Affilio purchase button")
    button_url = tracked_affiliate_button_url(affiliate_url, "telegram")
    data["reply_markup"] = json.dumps({
        "inline_keyboard": [[{
            "text": purchase_button_label(affiliate_url),
            "url": button_url,
        }]]
    }, ensure_ascii=False)

    for attempt in range(4):
        response = requests.post(endpoint, data=data, timeout=(20, 40))
        try:
            payload = response.json()
        except ValueError:
            response.raise_for_status()
            raise RuntimeError("Telegram editMessageCaption returned invalid JSON")
        if payload.get("ok"):
            response.raise_for_status()
            return payload.get("result")

        description = str(payload.get("description") or "Telegram editMessageCaption returned ok=false")
        lowered = description.lower()
        if "message is not modified" in lowered:
            return {"message_id": int(message_id), "not_modified": True}
        if "message to edit not found" in lowered or "message not found" in lowered:
            return {"message_id": int(message_id), "not_found": True}

        error_code = int(payload.get("error_code") or response.status_code or 0)
        if error_code == 429 and attempt < 3:
            parameters = payload.get("parameters") if isinstance(payload.get("parameters"), dict) else {}
            try:
                retry_after = max(1, min(60, int(parameters.get("retry_after") or (3 * (2 ** attempt)))))
            except (TypeError, ValueError, OverflowError):
                retry_after = min(60, 3 * (2 ** attempt))
            print(f"TELEGRAM_CAPTION_RATE_LIMIT message_id={int(message_id)} retry_after={retry_after}s")
            time.sleep(retry_after + 1)
            continue
        raise RuntimeError(description[:180])
    raise RuntimeError("Telegram editMessageCaption retry limit reached")


def _edit_bale_caption(message_id: int, caption: str, affiliate_url: str = ""):
    """Edit an existing Bale photo caption, retaining the purchase button and retrying rate limits."""
    if not BALE_BOT_TOKEN:
        raise RuntimeError("Missing BALE_BOT_TOKEN secret")
    if not BALE_CHANNEL_ID:
        raise RuntimeError("Missing BALE_CHANNEL_ID secret")
    endpoint = f"https://tapi.bale.ai/bot{BALE_BOT_TOKEN}/editMessageCaption"
    data = {
        "chat_id": BALE_CHANNEL_ID,
        "message_id": int(message_id),
        "caption": caption,
    }
    if not _is_valid_affilio_tracking_url(affiliate_url):
        raise RuntimeError("Refusing to publish or edit a post without a verified Affilio purchase button")
    button_url = tracked_affiliate_button_url(affiliate_url, "bale")
    data["reply_markup"] = json.dumps({
        "inline_keyboard": [[{
            "text": purchase_button_label(affiliate_url),
            "url": button_url,
        }]]
    }, ensure_ascii=False)

    for attempt in range(4):
        response = requests.post(endpoint, data=data, timeout=(20, 40))
        try:
            payload = response.json()
        except ValueError:
            response.raise_for_status()
            raise RuntimeError("Bale editMessageCaption returned invalid JSON")
        if payload.get("ok"):
            response.raise_for_status()
            return payload.get("result")

        description = str(payload.get("description") or "Bale editMessageCaption returned ok=false")
        lowered = description.lower()
        if "message is not modified" in lowered:
            return {"message_id": int(message_id), "not_modified": True}
        if "message to edit not found" in lowered or "message not found" in lowered:
            return {"message_id": int(message_id), "not_found": True}

        error_code = int(payload.get("error_code") or response.status_code or 0)
        if error_code == 429 and attempt < 3:
            parameters = payload.get("parameters") if isinstance(payload.get("parameters"), dict) else {}
            try:
                retry_after = max(1, min(60, int(parameters.get("retry_after") or (3 * (2 ** attempt)))))
            except (TypeError, ValueError, OverflowError):
                retry_after = min(60, 3 * (2 ** attempt))
            print(f"BALE_CAPTION_RATE_LIMIT message_id={int(message_id)} retry_after={retry_after}s")
            time.sleep(retry_after + 1)
            continue
        raise RuntimeError(description[:180])
    raise RuntimeError("Bale editMessageCaption retry limit reached")



def repair_bale_caption(message_id: int) -> int:
    """Repair one existing Bale post from the persisted product record; never publishes a new post."""
    if not BALE_BOT_TOKEN or not BALE_CHANNEL_ID:
        raise RuntimeError("BALE_BOT_TOKEN and BALE_CHANNEL_ID are required")
    state = load_state()
    published = state.get("published", {})
    match = None
    product_key = ""
    for pid, record in published.items():
        if not isinstance(record, dict):
            continue
        try:
            saved_id = int(record.get("bale_message_id") or 0)
        except (TypeError, ValueError, OverflowError):
            saved_id = 0
        if saved_id == int(message_id):
            match = record
            product_key = str(pid)
            break
    if match is None:
        raise RuntimeError("No persisted product record matches the requested Bale message ID")
    product_url_value = safe_product_url(match.get("product_url", ""))
    affiliate_url = build_affilio_tracking_link(product_url_value)
    if not affiliate_url:
        raise RuntimeError("Could not rebuild the verified affiliate URL for this Bale post")
    product = {
        "title": match.get("title", "پیشنهاد ویژه"),
        "current_price": match.get("posted_current_price"),
        "original_price": match.get("posted_original_price"),
        "discount_percent": match.get("posted_discount_percent"),
        "deal_expires_at": match.get("expires_at", ""),
    }
    caption = build_caption(
        product,
        affiliate_url,
        BALE_CHANNEL_URL,
        use_unicode_strikethrough=True,
    )
    _edit_bale_caption(int(message_id), caption, affiliate_url)
    print(f"BALE_CAPTION_REPAIRED product_id={product_key} message_id={int(message_id)}")
    return 0



def _recent_caption_repair_records(published: dict, limit: int) -> list[tuple[str, dict]]:
    """Return the newest active product records that have an editable channel message."""
    try:
        limit = int(limit)
    except (TypeError, ValueError, OverflowError):
        raise ValueError("recent caption repair limit must be a positive integer")
    if limit < 1:
        raise ValueError("recent caption repair limit must be a positive integer")

    candidates = []
    for product_key, record in published.items():
        if not isinstance(record, dict):
            continue
        has_editable_message = False
        for id_field, status_field in (
            ("telegram_message_id", "expiry_status"),
            ("bale_message_id", "bale_expiry_status"),
        ):
            raw_id = record.get(id_field)
            if raw_id in (None, "", 0, "0") or record.get(status_field) in {"deleted", "already_absent"}:
                continue
            try:
                if int(raw_id) > 0:
                    has_editable_message = True
                    break
            except (TypeError, ValueError, OverflowError):
                continue
        if has_editable_message:
            candidates.append((str(product_key), record))

    def posted_at(item):
        try:
            return float(item[1].get("ts") or 0)
        except (TypeError, ValueError, OverflowError):
            return 0.0

    return sorted(candidates, key=posted_at, reverse=True)[:limit]


def repair_all_published_captions(max_products: int | None = None) -> int:
    """Edit tracked Telegram/Bale captions in place; never creates or deletes posts."""
    state = load_state()
    published = state.get("published", {})
    if not isinstance(published, dict):
        raise RuntimeError("Published state is not an object")

    results = {
        "telegram_updated": 0,
        "telegram_failed": 0,
        "telegram_missing": 0,
        "bale_updated": 0,
        "bale_failed": 0,
        "bale_missing": 0,
        "skipped": 0,
    }
    target_count = 0
    caption_format_v4_products = []
    state_changed = False
    now = datetime.now(timezone.utc)

    # Full repair keeps oldest-first pacing; bounded repair selects the newest
    # active product records and edits only their already-published channel posts.
    if max_products is None:
        records_to_repair = sorted(
            published.items(),
            key=lambda item: float(item[1].get("ts", 0)) if isinstance(item[1], dict) else 0,
        )
    else:
        records_to_repair = _recent_caption_repair_records(published, max_products)
        print(f"RECENT_CAPTION_REPAIR_SELECTION selected_products={len(records_to_repair)} requested={max_products}")

    for product_key, record in records_to_repair:
        if not isinstance(record, dict):
            results["skipped"] += 1
            continue

        message_targets = []
        platform_fields = (
            ("telegram", "telegram_message_id", bool(BOT_TOKEN)),
            ("bale", "bale_message_id", bool(BALE_BOT_TOKEN and BALE_CHANNEL_ID)),
        )
        for platform, id_field, token_ready in platform_fields:
            raw_id = record.get(id_field)
            if raw_id in (None, "", 0, "0"):
                continue
            try:
                message_id = int(raw_id)
                if message_id <= 0:
                    raise ValueError("invalid message ID")
            except (TypeError, ValueError, OverflowError):
                print(f"CAPTION_REPAIR_SKIPPED product_id={product_key} platform={platform} reason=invalid_message_id")
                results["skipped"] += 1
                continue
            # Expired messages successfully removed by the preceding cleanup pass must not be edited again.
            raw_expiry = record.get("expires_at")
            deadline = _parse_utc_datetime(raw_expiry) if raw_expiry else None
            status_field = "expiry_status" if platform == "telegram" else "bale_expiry_status"
            # Truly deleted or explicitly expired posts stay untouched. Posts marked
            # only because their deadline could not be verified remain repairable:
            # a missing countdown must not permanently remove a valid buy button.
            # Only a confirmed removal makes a message immutable. A failed
            # deletion must not leave a live post without its purchase button.
            non_editable_statuses = {"deleted", "already_absent"}
            if record.get(status_field) in non_editable_statuses:
                print(
                    f"CAPTION_REPAIR_SKIPPED product_id={product_key} platform={platform} "
                    f"message_id={message_id} reason=expiry_status_{record.get(status_field)}"
                )
                results["skipped"] += 1
                continue
            # The expiry monitor immediately before this pass performs verified
            # removal. Estimated or unavailable timestamps must not block caption cleanup.

            target_count += 1
            if not token_ready:
                print(f"CAPTION_REPAIR_FAILED product_id={product_key} platform={platform} message_id={message_id} error=missing_credentials")
                results[f"{platform}_failed"] += 1
            else:
                message_targets.append((platform, message_id))

        if not message_targets:
            continue

        product_url_value = safe_product_url(record.get("product_url", ""))
        affiliate_url = build_affilio_tracking_link(product_url_value)
        if not affiliate_url:
            for platform, message_id in message_targets:
                print(f"CAPTION_REPAIR_FAILED product_id={product_key} platform={platform} message_id={message_id} error=affiliate_url_unavailable")
                results[f"{platform}_failed"] += 1
            continue

        source = str(record.get("expiry_source") or "")
        verified_deadline = (
            source in {"digikala_live_deals_feed", "live_product_stock_or_price", "snappshop_recheck_window"}
            and record.get("expiry_estimated") is not True
            and _parse_utc_datetime(record.get("expires_at")) is not None
            and (source != "digikala_live_deals_feed" or record.get("expiry_deadline_verified_directly") is True)
        ) or (
            source == "digikala_mcp_offer_card"
            and record.get("expiry_deadline_verified_from_site_card") is True
            and record.get("expiry_estimated") is not True
            and _parse_utc_datetime(record.get("expires_at")) is not None
        )
        product = {
            "title": record.get("title", "پیشنهاد ویژه"),
            "current_price": record.get("posted_current_price"),
            "original_price": record.get("posted_original_price"),
            "discount_percent": record.get("posted_discount_percent"),
            "deal_expires_at": record.get("expires_at", "") if verified_deadline else "",
            "expiry_estimated": not verified_deadline,
        }
        product_repair_success = True
        for platform, message_id in message_targets:
            try:
                # Always send the verified product-specific affiliate link with caption edits.
                # Omitting reply_markup is not a reliable way to preserve an existing keyboard.
                edit_link = affiliate_url
                if platform == "telegram":
                    caption = build_caption(product, affiliate_url, TELEGRAM_CHANNEL_URL)
                    edit_result = _edit_telegram_caption(message_id, caption, edit_link)
                else:
                    caption = build_caption(
                        product,
                        affiliate_url,
                        BALE_CHANNEL_URL,
                        use_unicode_strikethrough=True,
                    )
                    edit_result = _edit_bale_caption(message_id, caption, edit_link)

                if (isinstance(edit_result, dict) and edit_result.get("not_found")) or edit_result == "already_absent":
                    results[f"{platform}_missing"] += 1
                    status_field = "expiry_status" if platform == "telegram" else "bale_expiry_status"
                    record[status_field] = "already_absent"
                    state_changed = True
                    print(f"CAPTION_REPAIR_UNAVAILABLE product_id={product_key} platform={platform} message_id={message_id} reason=confirmed_absent")
                else:
                    results[f"{platform}_updated"] += 1
                    print(f"CAPTION_REPAIRED product_id={product_key} platform={platform} message_id={message_id}")
            except Exception as exc:
                product_repair_success = False
                results[f"{platform}_failed"] += 1
                detail = str(exc) if isinstance(exc, RuntimeError) else ""
                for secret in (BOT_TOKEN, BALE_BOT_TOKEN):
                    if secret:
                        detail = detail.replace(secret, "[redacted]")
                detail = re.sub(r"https?://\S+", "[url]", detail)[:120]
                detail_suffix = f" detail={detail!r}" if detail else ""
                print(f"CAPTION_REPAIR_FAILED product_id={product_key} platform={platform} message_id={message_id} error={type(exc).__name__}{detail_suffix}")
            # Conservative pacing on both APIs; Telegram is kept well below one edit/second.
            time.sleep(3.1 if platform == "telegram" else 1.1)
        if product_repair_success:
            # Recover records previously marked only because their deadline could not
            # be verified. The message is still present, its button is restored, and
            # the timer remains omitted until a site-backed deadline is available.
            for platform, _message_id in message_targets:
                status_field = "expiry_status" if platform == "telegram" else "bale_expiry_status"
                if record.get(status_field) in {
                    "deadline_unavailable_marked", "deadline_unavailable_delete_failed", "unknown", "expired_marked",
                }:
                    if verified_deadline:
                        record[status_field] = "tracked"
                    elif record.get("expiry_estimated") is True:
                        record[status_field] = "tracked_estimated"
                    else:
                        record[status_field] = "unknown"
                    state_changed = True
            record["caption_deadline_format_version"] = CAPTION_DEADLINE_FORMAT_VERSION
            record["caption_countdown_refreshed_at"] = datetime.now(timezone.utc).isoformat()
            record["caption_without_expiry_migrated_at"] = datetime.now(timezone.utc).isoformat()
            record.pop("deadline_caption_refresh_required", None)
            caption_format_v4_products.append(str(product_key))
            state_changed = True

    if state_changed:
        save_json(STATE, state)

    # Missing IDs are recorded as already absent; actual edit/API failures remain fatal.
    successful = (
        results["telegram_failed"] == 0
        and results["bale_failed"] == 0
        and target_count > 0
    )
    report = {
        "finished_at": datetime.now(timezone.utc).isoformat(),
        "method": DEFAULT_AFFILIO_PUBLIC_LINK_TEMPLATE,
        "caption_deadline_format_version": CAPTION_DEADLINE_FORMAT_VERSION,
        "caption_format_v4_products": caption_format_v4_products,
        "tracked_products": len(published),
        "selected_products": len(records_to_repair),
        "targets": target_count,
        **results,
        "status": "success" if successful else ("partial_failure" if target_count > 0 else "no_targets"),
    }
    report_path = ROOT / "affiliate_link_repair_report.json"
    try:
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(f"CAPTION_REPAIR_REPORT_WRITTEN path={report_path.name} status={report['status']}")
    except OSError as exc:
        print(f"CAPTION_REPAIR_REPORT_WRITE_FAILED error={type(exc).__name__}")

    print(
        "CAPTION_REPAIR_SUMMARY "
        f"tracked_products={len(published)} targets={target_count} "
        f"telegram_updated={results['telegram_updated']} telegram_missing={results['telegram_missing']} telegram_failed={results['telegram_failed']} "
        f"bale_updated={results['bale_updated']} bale_missing={results['bale_missing']} bale_failed={results['bale_failed']} "
        f"skipped={results['skipped']}"
    )
    return 0 if successful else 1



def refresh_active_countdowns() -> int:
    """Migrate old captions to the static format and restore verified purchase buttons.

    The historic CLI name is kept for workflow compatibility. This routine never
    renders a countdown; each tracked post is repaired once per caption schema version.
    """
    try:
        max_records = int(os.getenv("AFFILIO_COUNTDOWN_REFRESH_MAX_RECORDS", "80"))
    except (TypeError, ValueError, OverflowError):
        max_records = 80
    max_records = max(1, min(100, max_records))

    state = load_state()
    published = state.get("published", {})
    if not isinstance(published, dict):
        raise RuntimeError("Published state is not an object")
    now = datetime.now(timezone.utc)
    terminal_statuses = {"deleted", "already_absent"}
    verified_sources = {"digikala_live_deals_feed", "digikala_product_detail_api", "digikala_mcp_offer_card", "live_product_stock_or_price", "snappshop_recheck_window"}
    due = []
    for product_key, record in published.items():
        if not isinstance(record, dict):
            continue
        try:
            current_version = int(record.get("caption_deadline_format_version") or 0)
        except (TypeError, ValueError, OverflowError):
            current_version = 0
        needs_button_retry = any(
            record.get(field) in {
                "delete_failed", "expired_marked",
                "deadline_unavailable_marked", "deadline_unavailable_delete_failed",
            }
            for field in ("expiry_status", "bale_expiry_status")
        )
        if (
            current_version >= CAPTION_DEADLINE_FORMAT_VERSION
            and not record.get("deadline_caption_refresh_required")
            and not needs_button_retry
        ):
            continue

        deadline = _parse_utc_datetime(record.get("expires_at"))
        expiry_source = str(record.get("expiry_source") or "")
        verified_deadline = (
            deadline is not None
            and expiry_source in verified_sources
            and record.get("expiry_estimated") is not True
            and (
                (expiry_source in {"digikala_live_deals_feed", "digikala_product_detail_api"} and record.get("expiry_deadline_verified_directly") is True)
                or (expiry_source == "digikala_mcp_offer_card" and record.get("expiry_deadline_verified_from_site_card") is True)
                or expiry_source == "live_product_stock_or_price"
            )
        )
        cutoff_passed = (
            verified_deadline
            and deadline - timedelta(minutes=COUNTDOWN_SAFETY_BUFFER_MINUTES) <= now
        )

        targets = []
        for platform, id_field, status_field, token_ready in (
            ("telegram", "telegram_message_id", "expiry_status", bool(BOT_TOKEN)),
            ("bale", "bale_message_id", "bale_expiry_status", bool(BALE_BOT_TOKEN and BALE_CHANNEL_ID)),
        ):
            raw_id = str(record.get(id_field) or "")
            status = str(record.get(status_field) or "")
            if not raw_id.isdigit() or status in terminal_statuses or not token_ready:
                continue
            # After a deletion failure, repair the live caption and button in place
            # while the next cleanup cycle retries permanent removal.
            if cutoff_passed and status not in {"delete_failed", "expired_marked"}:
                print(
                    f"STATIC_CAPTION_MIGRATION_SKIPPED product_id={product_key} "
                    f"platform={platform} message_id={raw_id} reason=verified_expiry_cutoff"
                )
                continue
            targets.append((platform, int(raw_id)))
        if not targets:
            continue
        try:
            posted_ts = float(record.get("ts") or 0)
        except (TypeError, ValueError, OverflowError):
            posted_ts = 0.0
        last_refresh = _parse_utc_datetime(record.get("caption_countdown_refreshed_at"))
        due.append((
            last_refresh or datetime.min.replace(tzinfo=timezone.utc),
            posted_ts,
            str(product_key),
            record,
            targets,
            verified_deadline,
        ))

    due.sort(key=lambda item: (item[0], item[1], item[2]))
    selected = due[:max_records]
    counters = {
        "telegram_updated": 0, "telegram_missing": 0, "telegram_failed": 0,
        "bale_updated": 0, "bale_missing": 0, "bale_failed": 0, "skipped": 0,
    }
    changed = False
    print(
        f"STATIC_CAPTION_MIGRATION_BATCH eligible={len(due)} selected={len(selected)} "
        f"limit={max_records} schema_version={CAPTION_DEADLINE_FORMAT_VERSION}"
    )

    for _, _, product_key, record, targets, verified_deadline in selected:
        affiliate_url = build_affilio_tracking_link(safe_product_url(record.get("product_url", "")))
        if not _is_valid_affilio_tracking_url(affiliate_url):
            counters["skipped"] += 1
            print(f"STATIC_CAPTION_MIGRATION_SKIPPED product_id={product_key} reason=affiliate_url_unavailable")
            continue

        product = {
            "title": record.get("title", "پیشنهاد ویژه"),
            "current_price": record.get("posted_current_price"),
            "original_price": record.get("posted_original_price"),
            "discount_percent": record.get("posted_discount_percent"),
        }
        product_had_failure = False
        for platform, message_id in targets:
            try:
                if platform == "telegram":
                    caption = build_caption(product, affiliate_url, TELEGRAM_CHANNEL_URL)
                    result = _edit_telegram_caption(message_id, caption, affiliate_url)
                else:
                    caption = build_caption(
                        product, affiliate_url, BALE_CHANNEL_URL,
                        use_unicode_strikethrough=True,
                    )
                    result = _edit_bale_caption(message_id, caption, affiliate_url)
                if (isinstance(result, dict) and result.get("not_found")) or result == "already_absent":
                    counters[f"{platform}_missing"] += 1
                    status_field = "expiry_status" if platform == "telegram" else "bale_expiry_status"
                    record[status_field] = "already_absent"
                    changed = True
                    print(
                        f"STATIC_CAPTION_MIGRATION_UNAVAILABLE product_id={product_key} "
                        f"platform={platform} message_id={message_id} reason=confirmed_absent"
                    )
                else:
                    counters[f"{platform}_updated"] += 1
                    print(
                        f"STATIC_CAPTION_MIGRATED product_id={product_key} "
                        f"platform={platform} message_id={message_id} button=restored countdown=removed"
                    )
            except Exception as exc:
                counters[f"{platform}_failed"] += 1
                product_had_failure = True
                print(
                    f"STATIC_CAPTION_MIGRATION_FAILED product_id={product_key} "
                    f"platform={platform} message_id={message_id} error={type(exc).__name__}"
                )
            time.sleep(1.1 if len(targets) > 1 else (3.1 if platform == "telegram" else 1.1))

        if not product_had_failure:
            record["caption_deadline_format_version"] = CAPTION_DEADLINE_FORMAT_VERSION
            record["caption_static_migrated_at"] = now.isoformat()
            record["caption_countdown_refreshed_at"] = now.isoformat()
            record.pop("deadline_caption_refresh_required", None)
            for platform, _message_id in targets:
                status_field = "expiry_status" if platform == "telegram" else "bale_expiry_status"
                if record.get(status_field) in {
                    "deadline_unavailable_marked", "deadline_unavailable_delete_failed", "unknown",
                }:
                    record[status_field] = "tracked" if verified_deadline else "unknown"
            changed = True

    if changed:
        save_json(STATE, state)
    print(
        "STATIC_CAPTION_MIGRATION_SUMMARY "
        f"records_selected={len(selected)} telegram_updated={counters['telegram_updated']} "
        f"telegram_missing={counters['telegram_missing']} telegram_failed={counters['telegram_failed']} "
        f"bale_updated={counters['bale_updated']} bale_missing={counters['bale_missing']} "
        f"bale_failed={counters['bale_failed']} skipped={counters['skipped']}"
    )
    return 0



def _delivery_retry_delay(attempt: int) -> int:
    """Exponential backoff for one-channel failures, capped at one hour."""
    exponent = max(0, min(4, int(attempt or 1) - 1))
    return min(3600, 300 * (2 ** exponent))


def _discover_public_channel_message_ids(max_pages: int = 50) -> set[int]:
    """Read public channel preview pages to find prior post IDs; does not expose bot credentials."""
    channel = TARGET_CHAT.lstrip("@")
    if not channel:
        return set()
    found: set[int] = set()
    before = None
    headers = {"User-Agent": "Mozilla/5.0 (compatible; IranGajetPostCleanup/1.0)"}
    for _ in range(max_pages):
        url = f"https://t.me/s/{channel}"
        if before:
            url += f"?before={before}"
        try:
            response = SESSION.get(url, headers=headers, timeout=(10, 20))
            if response.status_code >= 400:
                print(f"DELETE_SCAN_STOP status={response.status_code}")
                break
            soup = BeautifulSoup(response.text, "html.parser")
            page_ids = set()
            for node in soup.select("[data-post]"):
                match = re.fullmatch(rf"{re.escape(channel)}/(\d+)", str(node.get("data-post") or ""))
                if match:
                    page_ids.add(int(match.group(1)))
            new_ids = page_ids - found
            if not new_ids:
                break
            found.update(new_ids)
            oldest = min(page_ids)
            if before is not None and oldest >= before:
                break
            before = oldest
        except Exception as exc:
            print(f"DELETE_SCAN_FAILED error={type(exc).__name__}")
            break
    print(f"DELETE_SCAN_FOUND messages={len(found)}")
    return found


def delete_previous_channel_posts(state: dict) -> None:
    """Best-effort deletion of prior channel posts; tracks failures so products aren't silently duplicated."""
    if not BOT_TOKEN:
        print("DELETE_SKIPPED reason=missing_bot_token")
        return
    published = state.setdefault("published", {})
    known_ids = {}
    for product_id_value, record in list(published.items()):
        if not isinstance(record, dict):
            continue
        try:
            message_id = int(record.get("telegram_message_id"))
        except (TypeError, ValueError):
            continue
        known_ids[message_id] = product_id_value
    ids = _discover_public_channel_message_ids()
    ids.update(known_ids)
    deleted = set()
    failed = 0
    endpoint = f"https://api.telegram.org/bot{BOT_TOKEN}/deleteMessage"
    for message_id in sorted(ids, reverse=True):
        try:
            response = requests.post(
                endpoint,
                data={"chat_id": TARGET_CHAT, "message_id": message_id},
                timeout=(10, 20),
            )
            payload = response.json()
            if response.ok and payload.get("ok"):
                deleted.add(message_id)
                print(f"DELETE_OK message_id={message_id}")
            else:
                failed += 1
                detail = str(payload.get("description") or response.status_code)[:120]
                print(f"DELETE_FAILED message_id={message_id} detail={detail!r}")
        except Exception as exc:
            failed += 1
            print(f"DELETE_FAILED message_id={message_id} error={type(exc).__name__}")
        time.sleep(0.08)
    # Clearing visible Telegram posts must never erase product history/cooldowns.
    # Bale is not deleted by this Telegram-only helper, so its prior message ID remains
    # tracked and will continue to block another post until its own removal is confirmed.
    for product_id_value, record in list(published.items()):
        if not isinstance(record, dict):
            continue
        raw_id = record.get("telegram_message_id")
        if str(raw_id or "").isdigit() and int(raw_id) in deleted:
            record["expiry_status"] = "deleted"
            record["expired_deleted_at"] = datetime.now(timezone.utc).isoformat()
    ensure_publication_ledger(state)
    # Do not reset last_published_at: a cleanup/maintenance action is not a new posting window.
    save_json(STATE, state)
    print(
        f"DELETE_SUMMARY discovered={len(ids)} deleted={len(deleted)} "
        f"failed={failed} product_cooldowns_preserved={len(published)}"
    )


def _parse_utc_datetime(value):
    try:
        parsed = datetime.fromisoformat(str(value or "").replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)



def is_offer_expired(product: dict, now: datetime | None = None) -> bool:
    """An explicit expired deal deadline always blocks publication."""
    expiry_value = _parse_deal_expiry_value(product.get("deal_expires_at"))
    expiry = _parse_utc_datetime(expiry_value)
    if expiry is None:
        return False
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    return expiry <= now


def has_verified_deal_deadline(product: dict, now: datetime | None = None) -> bool:
    """Require a current, product-matched deadline extracted from a DigiKala offer card or detail API."""
    if not isinstance(product, dict):
        return False
    source = str(product.get("expiry_source") or "")
    direct_source = source in {"digikala_live_deals_feed", "digikala_product_detail_api"}
    site_card_source = (
        source == "digikala_mcp_offer_card"
        and product.get("expiry_deadline_verified_from_site_card") is True
    )
    if not ((direct_source and product.get("expiry_deadline_verified_directly") is True) or site_card_source):
        return False
    expiry = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
    if expiry is None:
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    return expiry > current.astimezone(timezone.utc)


def has_minimum_publication_runway(product: dict, now: datetime | None = None) -> bool:
    """Require at least the configured amount of time for the audience to act after a post."""
    expiry = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
    if expiry is None:
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    remaining_seconds = (expiry - current.astimezone(timezone.utc)).total_seconds()
    return remaining_seconds >= MIN_PUBLICATION_RUNWAY_MINUTES * 60


def has_publishable_expiry_or_open_offer(product: dict, now: datetime | None = None) -> bool:
    """Allow a live, discounted offer with no published timer, but never accept unknown stock."""
    if not isinstance(product, dict):
        return False
    source = str(product.get("expiry_source") or "")
    deadline = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
    # Legacy artificial SnappShop recheck timestamps are not real campaign deadlines.
    if source == "snappshop_recheck_window":
        deadline = None
    if deadline is not None:
        return bool(
            has_verified_deal_deadline(product, now)
            and not is_offer_expired(product, now)
            and has_minimum_publication_runway(product, now)
        )
    try:
        current_price = int(product.get("current_price") or 0)
        original_price = int(product.get("original_price") or 0)
    except (TypeError, ValueError, OverflowError):
        return False
    return bool(
        product.get("availability") == "in_stock"
        and product.get("availability_source")
        and current_price > 0
        and original_price > current_price
    )


def is_urgent_priority_deal(product: dict, now: datetime | None = None) -> bool:
    """Only very strong deals with safe purchase runway may use the shorter posting cooldown."""
    if not has_minimum_publication_runway(product, now):
        return False
    expiry_value = _parse_deal_expiry_value(product.get("deal_expires_at"))
    expiry = _parse_utc_datetime(expiry_value)
    if expiry is None:
        return False
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    remaining_seconds = (expiry - now).total_seconds()
    return bool(
        0 < remaining_seconds <= URGENT_EXPIRY_WINDOW_MINUTES * 60
        and int(product.get("discount_percent") or 0) >= URGENT_MIN_DISCOUNT_PERCENT
        and int(product.get("savings_toman") or 0) >= URGENT_MIN_SAVINGS_TOMAN
        and int(product.get("demand_score") or 0) >= URGENT_MIN_DEMAND_SCORE
    )


def is_deadline_critical_deal(product: dict, now: datetime | None = None) -> bool:
    """Allow a qualified deal near its deadline to bypass the usual gap, but never the runway floor."""
    if not has_minimum_publication_runway(product, now):
        return False
    expiry = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
    if expiry is None:
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    remaining_seconds = (expiry - current.astimezone(timezone.utc)).total_seconds()
    return bool(
        0 < remaining_seconds <= DEADLINE_CRITICAL_WINDOW_MINUTES * 60
        and has_meaningful_discount(product)
    )


def is_manual_publication_quarantine_active(previous: dict | None, now: datetime | None = None) -> bool:
    """Keep a product off the channel briefly after an operator reports invalid offer details."""
    if not isinstance(previous, dict):
        return False
    quarantine_until = _parse_utc_datetime(previous.get("manual_quarantine_until"))
    if quarantine_until is None:
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    return quarantine_until > current.astimezone(timezone.utc)


def previous_publication_posts_removed(previous: dict | None) -> bool:
    """Prevent a new post while any prior Telegram/Bale message may still be visible."""
    if not isinstance(previous, dict):
        return True
    records = [previous]
    history = previous.get("post_history")
    if isinstance(history, list):
        records.extend(record for record in history if isinstance(record, dict))
    terminal = {"deleted", "already_absent"}
    for record in records:
        for id_field, status_field in (
            ("telegram_message_id", "expiry_status"),
            ("bale_message_id", "bale_expiry_status"),
        ):
            message_id = record.get(id_field)
            if str(message_id or "").isdigit() and record.get(status_field) not in terminal:
                return False
    return True


def is_materially_improved_offer(previous: dict, product: dict, now: datetime | None = None) -> bool:
    """Allow a repeat within cooldown only when the current price is at least 10% lower.

    DigiKala can refresh or extend a campaign timer without materially improving the
    deal. A new timestamp alone must never bypass the 30-day product cooldown.
    """
    if not isinstance(previous, dict) or not isinstance(product, dict):
        return False
    try:
        old_price = int(previous.get("posted_current_price") or previous.get("current_price") or 0)
        new_price = int(product.get("current_price") or 0)
    except (TypeError, ValueError, OverflowError):
        old_price, new_price = 0, 0
    return bool(old_price > 0 and new_price > 0 and new_price <= old_price * 0.90)


def pending_queue_sort_key(product: dict, queue_record: dict | None = None,
                           now: datetime | None = None) -> tuple:
    """Prioritize market-demand signals, then discount percentage; urgency only follows those signals."""
    now = now or datetime.now(timezone.utc)
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    now = now.astimezone(timezone.utc)
    queue_record = queue_record if isinstance(queue_record, dict) else {}
    first_seen = _parse_utc_datetime(queue_record.get("first_seen_at")) or now
    expiry = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
    remaining = (expiry - now).total_seconds() if expiry else float("inf")
    if remaining <= ULTRA_URGENT_WINDOW_MINUTES * 60:
        deadline_priority = 3
    elif remaining <= DEADLINE_CRITICAL_WINDOW_MINUTES * 60:
        deadline_priority = 2
    elif remaining <= URGENT_EXPIRY_WINDOW_MINUTES * 60:
        deadline_priority = 1
    else:
        deadline_priority = 0
    # deal_sort_key prioritizes retailer-side demand signals, then discount percentage.
    # Channel clicks and deadline urgency cannot override those two ranking criteria.
    return (
        *deal_sort_key(product),
        int(is_urgent_priority_deal(product, now)),
        deadline_priority,
        -remaining if math.isfinite(remaining) else float("-inf"),
        -first_seen.timestamp(),
    )


def defer_pending_publication(
    state: dict,
    pid: str,
    reason: str,
    now: datetime | None = None,
) -> dict | None:
    """Back off a candidate that failed during publish, allowing the next queue item to run."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    queue = state.get("pending_queue")
    record = queue.get(str(pid)) if isinstance(queue, dict) else None
    if not isinstance(record, dict):
        return None
    try:
        failures = max(0, int(record.get("publish_failure_count") or 0)) + 1
    except (TypeError, ValueError, OverflowError):
        failures = 1
    # Exponential retry: 5, 10, 20, 40, then at most 60 minutes.
    delay_minutes = min(60, 5 * (2 ** min(failures - 1, 4)))
    record["publish_failure_count"] = failures
    record["last_publish_failure"] = str(reason or "publish_failed")[:80]
    record["last_publish_failure_at"] = current.isoformat()
    record["next_publish_attempt_at"] = (current + timedelta(minutes=delay_minutes)).isoformat()
    print(
        f"PUBLISH_CANDIDATE_DEFERRED id={pid} reason={record['last_publish_failure']} "
        f"failures={failures} retry_in_minutes={delay_minutes}"
    )
    return record


def _publication_diversity_group(product_or_title) -> tuple[str, str, str]:
    """Return a broad category, narrower product family, and known brand hint."""
    explicit_brand = ""
    if isinstance(product_or_title, dict):
        title = str(product_or_title.get("title") or "")
        raw_brand = product_or_title.get("brand") or product_or_title.get("brand_name") or ""
        if isinstance(raw_brand, dict):
            raw_brand = raw_brand.get("name") or raw_brand.get("title") or raw_brand.get("value") or ""
        explicit_brand = str(raw_brand or "").strip()
    else:
        title = str(product_or_title or "")
    normalized = title.lower().replace("\u200c", " ")
    brand_search_text = (normalized + " " + explicit_brand.lower()).strip()
    category = classify_category(normalized)
    family_patterns = {
        "lighting": [
            ("desk_lighting", r"چراغ مطالعه|چراغ خواب"),
            ("outdoor_lighting", r"چراغ پیشانی|هدلامپ|چراغ کمپینگ|نورافکن"),
            ("bulbs_and_strips", r"لامپ|ریسه روشنایی"),
        ],
        "home_cleaning": [
            ("floor_cleaning", r"تی زمین شوی|تی چرخشی|زمین شوی|بخارشوی"),
            ("vacuum_cleaning", r"جارو(?:برقی| شارژی)?"),
            ("surface_cleaning", r"مواد شوینده|شوینده سطوح|تمیزکننده سطوح|دستمال نظافت"),
        ],
        "pet_supplies": [
            ("pet_food", r"غذای سگ|غذای گربه|تشویقی سگ|تشویقی گربه"),
            ("pet_accessories", r"قلاده|خاک گربه|اسکرچر|پد بهداشتی سگ"),
        ],
        "arts_crafts": [
            ("art_materials", r"بوم نقاشی|لوازم نقاشی|لوازم هنری|قلم طراحی|رنگ اکریلیک|رنگ روغن"),
            ("sewing_crafts", r"لوازم خیاطی|چرخ خیاطی|کاموا|قلاب بافی|بافتنی"),
        ],
        "presentation_tools": [
            ("presentation_remote", r"ریموت ارائه|کنترل ارائه"),
            ("laser_pointer", r"لیزر پوینتر|پوینتر ارائه"),
        ],
        "sports_outdoor": [
            ("camping", r"کمپینگ|کوهنوردی|چادر مسافرتی|سفر و طبیعت"),
            ("fitness", r"بدنسازی|دمبل|تردمیل"),
            ("cycling_and_sports", r"دوچرخه|توپ فوتبال|شنا|اسکی"),
        ],
        "power_backup": [
            ("battery", r"باتری|قلمی|نیم\s*قلمی"),
            ("charger", r"شارژر"),
            ("emergency_light", r"چراغ اضطراری|برق اضطراری"),
            ("power_bank", r"پاور\s*بانک|پاوربانک"),
        ],
        "audio_wearables": [
            ("headphones", r"هدفون|هندزفری|ایرپاد"),
            ("speaker", r"اسپیکر"),
            ("smartwatch", r"ساعت\s*هوشمند|اسمارت\s*واچ"),
        ],
        "personal_care": [
            ("skincare", r"پوست|کرم|سرم|آبرسان|تونر|ضدآفتاب"),
            ("haircare", r"مو|سشوار|برس حرارتی|اتو مو"),
            ("massage", r"ماساژ"),
        ],
        "fashion": [
            ("apparel", r"تی\s*شرت|تیشرت|پولو\s*شرت|پولوشرت|سویشرت|سوییشرت|هودی|شلوار|بلوز|شومیز|تاپ|پیراهن|مانتو|لباس"),
            ("footwear", r"کفش|صندل|بوت"),
            ("wallets", r"کیف پول|جاکارتی"),
            ("bags", r"کیف|کوله"),
            ("eyewear", r"عینک"),
            ("accessories", r"کمربند|کراوات|کلاه|دستکش"),
        ],
        "jewelry": [("jewelry", r"نقره|گوشواره|انگشتر|دستبند|گردنبند|زیورآلات|بدلیجات")],
        "beauty_fragrance": [("fragrance", r"عطر|ادکلن|پرفیوم|تویلت|بادی\s*اسپلش")],
        "home": [
            ("kitchen", r"آشپزخانه|ظرف|قهوه ساز|فلاسک|ماگ"),
            ("organization", r"نظم دهنده|ارگانایزر"),
            ("lighting", r"چراغ|لامپ"),
        ],
        "kids_sports": [
            ("baby", r"نوزاد|نوزادی|کودک"),
            ("sports_outdoor", r"ورزشی|کمپینگ|کوهنوردی|سفر"),
        ],
    }
    # Eyewear is one global product family, even when a sport descriptor
    # causes the broad category classifier to label the listing as sports.
    family = "fashion:eyewear" if re.search(r"عینک", normalized, re.I) else category
    if family == category:
        for subfamily, pattern in family_patterns.get(category, []):
            if re.search(pattern, normalized, re.I):
                family = f"{category}:{subfamily}"
                break
    brand_hints = [
        ("muzik_apollo", r"موزیک\s*آپولو"),
        ("vonk", r"وونک"),
        ("reolink", r"ریولینک"),
        ("tilsim", r"تیلسیم"),
        ("glama", r"گلاما"),
        ("habsan", r"هپسان"),
        ("nil_cook", r"نیل\s*کوک"),
        ("bogta", r"بوگتا"),
        ("falcon", r"فالکون"),
        ("easydo", r"ایزی\s*دو|ایزی2"),
        ("panbineh", r"پنبینه"),
        ("paresteh", r"پرسته"),
        ("one_by_one", r"وان\s*بای\s*وان"),
        ("radis", r"رادیس"),
        ("art_vina", r"آرت\s*وینا"),
        ("eurovital", r"یوروویتال"),
        ("blatos", r"بلاتوس"),
        ("antonio_rossini", r"آنتونیو\s*روسینی"),
        ("zanama", r"زاناما"),
        ("dellbesto", r"دلبستو"),
    ]
    brand = next((key for key, pattern in brand_hints if re.search(pattern, brand_search_text, re.I)), "")
    if not brand and explicit_brand:
        brand_slug = re.sub(r"[^\w\u0600-\u06FF]+", "_", explicit_brand.lower()).strip("_")
        if brand_slug and brand_slug not in {"unknown", "other", "none", "نامشخص", "-"}:
            brand = f"brand:{brand_slug}"
    return category, family, brand


def _publication_retailer_group(product_or_record) -> str:
    """Return the retailer from an immutable product ID, with merchant as fallback."""
    if not isinstance(product_or_record, dict):
        return ""
    pid = str(
        product_or_record.get("product_id")
        or product_or_record.get("id")
        or product_id(product_or_record.get("product_url") or product_or_record.get("url") or "")
    ).strip().lower()
    if pid.startswith("snp-"):
        return "snappshop"
    if pid.startswith("dkp-"):
        return "digikala"
    merchant = str(product_or_record.get("merchant") or product_or_record.get("store") or "").strip().lower()
    if "snapp" in merchant or "اسنپ" in merchant:
        return "snappshop"
    if "digi" in merchant or "دیجی" in merchant:
        return "digikala"
    return ""


def _publication_diversity_history_key(record: dict, product_id_override: str | None = None):
    """Identify one real post by platform message IDs, not timestamps refreshed by audits.

    A post's metadata timestamp can be rewritten during countdown/cleanup runs.
    Stable channel message IDs are the durable identity; timestamps are only a
    fallback for legacy records that never stored a platform message ID.
    """
    if not isinstance(record, dict):
        return None
    pid = str(product_id_override or record.get("product_id") or "").strip()
    if not pid:
        return None

    def valid_id(field: str) -> int:
        value = str(record.get(field) or "").strip()
        return int(value) if value.isdigit() and int(value) > 0 else 0

    telegram_id = valid_id("telegram_message_id")
    bale_id = valid_id("bale_message_id")
    if telegram_id or bale_id:
        return ("message", pid, telegram_id, bale_id)

    try:
        timestamp = float(record.get("ts") or record.get("order") or 0)
    except (TypeError, ValueError, OverflowError):
        timestamp = 0.0
    if timestamp > 0:
        return ("time", pid, round(timestamp, 3))
    return None



def _recent_publication_diversity(
    published: dict | None,
    limit: int = 12,
    durable_history: list | None = None,
    now: datetime | None = None,
    window_hours: float = 24.0,
) -> list[dict]:
    """Read deduplicated publication history inside a rolling time window.

    Message deletion must not erase diversity memory. When now is supplied,
    stale publications older than the window are excluded before any row limit.
    """
    records = []
    for raw_pid, record in (published.items() if isinstance(published, dict) else []):
        if not isinstance(record, dict):
            continue
        histories = record.get("post_history")
        posts = [*(histories if isinstance(histories, list) else []), record]
        for post in posts:
            if not isinstance(post, dict):
                continue
            message_ids = [
                int(post[key]) for key in ("telegram_message_id", "bale_message_id")
                if str(post.get(key) or "").isdigit()
            ]
            if not message_ids:
                continue
            title = str(post.get("title") or record.get("title") or "").strip()
            if not title:
                continue
            try:
                timestamp = float(post.get("ts") or 0)
            except (TypeError, ValueError, OverflowError):
                timestamp = 0.0
            order = timestamp if timestamp > 0 else float(max(message_ids))
            category, family, brand = _publication_diversity_group({"title": title, "brand": post.get("brand") or record.get("brand") or ""})
            retailer = _publication_retailer_group({"product_id": raw_pid, "merchant": post.get("merchant") or record.get("merchant") or ""})
            records.append({
                "product_id": str(raw_pid), "title": title,
                "message_id": max(message_ids),
                "telegram_message_id": int(post["telegram_message_id"]) if str(post.get("telegram_message_id") or "").isdigit() else 0,
                "bale_message_id": int(post["bale_message_id"]) if str(post.get("bale_message_id") or "").isdigit() else 0,
                "ts": order, "order": order, "category": category, "family": family, "brand": brand,
                "retailer": retailer,
            })
    for entry in durable_history if isinstance(durable_history, list) else []:
        if not isinstance(entry, dict):
            continue
        pid = str(entry.get("product_id") or "").strip()
        title = str(entry.get("title") or "").strip()
        try:
            order = float(entry.get("ts") or 0)
        except (TypeError, ValueError, OverflowError):
            order = 0.0
        if not pid or not title or order <= 0:
            continue
        category, family, brand = _publication_diversity_group({"title": title, "brand": entry.get("brand") or ""})
        retailer = _publication_retailer_group({"product_id": pid, "merchant": entry.get("merchant") or ""})
        raw_message_id = entry.get("telegram_message_id") or entry.get("bale_message_id")
        try:
            message_id = int(raw_message_id)
        except (TypeError, ValueError, OverflowError):
            message_id = int(order * 1000)
        records.append({
            "product_id": pid, "title": title, "message_id": message_id,
            "telegram_message_id": int(entry["telegram_message_id"]) if str(entry.get("telegram_message_id") or "").isdigit() else 0,
            "bale_message_id": int(entry["bale_message_id"]) if str(entry.get("bale_message_id") or "").isdigit() else 0,
            "ts": order, "order": order, "category": category, "family": family, "brand": brand,
            "retailer": retailer,
        })
    unique = {}
    for record in records:
        key = _publication_diversity_history_key(record)
        if key is None:
            continue
        previous = unique.get(key)
        if previous is None or float(record["order"]) < float(previous["order"]):
            unique[key] = record
    ordered = sorted(unique.values(), key=lambda r: (r["order"], r["message_id"]))
    if now is not None:
        current = now
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        current_ts = current.astimezone(timezone.utc).timestamp()
        cutoff = current_ts - max(0.0, float(window_hours)) * 3600
        ordered = [record for record in ordered if cutoff <= float(record["order"]) <= current_ts + 300]
    return ordered[-max(1, int(limit)):]



_LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS: dict = {
    "candidate_count": 0,
    "top10_category_counts": {},
    "fallback_events": [],
}


def _publication_distribution_summary(records: list[dict]) -> dict:
    """Summarize category/family coverage, category shares, and repeated known brands."""
    category_counts: dict[str, int] = {}
    family_counts: dict[str, int] = {}
    brand_counts: dict[str, int] = {}
    retailer_counts: dict[str, int] = {}
    for record in records if isinstance(records, list) else []:
        if not isinstance(record, dict):
            continue
        category = str(record.get("category") or "other")
        family = str(record.get("family") or category)
        brand = str(record.get("brand") or "")
        category_counts[category] = category_counts.get(category, 0) + 1
        family_counts[family] = family_counts.get(family, 0) + 1
        if brand:
            brand_counts[brand] = brand_counts.get(brand, 0) + 1
        retailer = str(record.get("retailer") or _publication_retailer_group(record))
        if retailer:
            retailer_counts[retailer] = retailer_counts.get(retailer, 0) + 1

    post_count = len(records or [])
    ordered_categories = sorted(category_counts.items(), key=lambda row: (-row[1], row[0]))
    repeated_brands = {
        brand: count
        for brand, count in sorted(brand_counts.items(), key=lambda row: (-row[1], row[0]))
        if count > 1
    }
    return {
        "posts": post_count,
        "distinct_categories": len(category_counts),
        "distinct_families": len(family_counts),
        "distinct_retailers": len(retailer_counts),
        "retailer_post_counts": dict(sorted(retailer_counts.items(), key=lambda row: (-row[1], row[0]))),
        "retailer_share_percent": {
            retailer: round(count * 100.0 / post_count, 1)
            for retailer, count in sorted(retailer_counts.items(), key=lambda row: (-row[1], row[0]))
        } if post_count else {},
        "category_post_counts": dict(ordered_categories),
        "category_share_percent": {
            category: round(count * 100.0 / post_count, 1)
            for category, count in ordered_categories
        } if post_count else {},
        "known_brand_posts": sum(brand_counts.values()),
        "repeated_brand_count": sum(max(0, count - 1) for count in brand_counts.values()),
        "repeated_brands": repeated_brands,
    }


def build_publication_diversity_report(
    published: dict | None = None,
    recent_publications: list | None = None,
    now: datetime | None = None,
    fallback_events: list | None = None,
    fallback_total: int = 0,
    fallbacks_this_selection: list | None = None,
) -> dict:
    """Build a rolling report from deduplicated real publication history."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)

    day_records = _recent_publication_diversity(
        published, limit=2000, durable_history=recent_publications,
        now=current, window_hours=24.0,
    )
    week_records = _recent_publication_diversity(
        published, limit=2000, durable_history=recent_publications,
        now=current, window_hours=24.0 * 7,
    )
    events = [dict(event) for event in (fallback_events or []) if isinstance(event, dict)]
    cutoff = current - timedelta(days=7)
    events_last_7d = []
    for event in events:
        event_at = _parse_utc_datetime(event.get("at"))
        if event_at and cutoff <= event_at <= current + timedelta(minutes=5):
            events_last_7d.append(event)
    try:
        total_fallbacks = max(0, int(fallback_total or 0))
    except (TypeError, ValueError, OverflowError):
        total_fallbacks = 0
    current_fallbacks = [
        dict(event) for event in (fallbacks_this_selection or []) if isinstance(event, dict)
    ]

    return {
        "generated_at": current.isoformat(),
        "policy": {
            "minimum_discount_percent": MIN_DISCOUNT_FALLBACK_PERCENT,
            "preferred_discount_floor_percent": MIN_DISCOUNT_PERCENT,
            "discount_fallback_floors": list(DISCOUNT_FALLBACK_FLOORS),
            "minimum_savings_toman": MIN_SAVINGS_TOMAN,
            "category_repeat_cooldown_minutes": CATEGORY_REPEAT_COOLDOWN_MINUTES,
            "family_repeat_cooldown_hours": FAMILY_REPEAT_COOLDOWN_HOURS,
            "brand_repeat_cooldown_hours": BRAND_REPEAT_COOLDOWN_HOURS,
            "retailer_repeat_cooldown_minutes": RETAILER_REPEAT_COOLDOWN_MINUTES,
            "diversity_demand_score_ratio": DIVERSITY_DEMAND_SCORE_RATIO,
            "diversity_lookahead_candidates": DIVERSITY_LOOKAHEAD_CANDIDATES,
            "diversity_only_reorders_candidates_with_comparable_demand_and_offer_quality": True,
        },
        "last_24_hours": _publication_distribution_summary(day_records),
        "last_7_days": _publication_distribution_summary(week_records),
        "fallbacks": {
            "all_time_count": total_fallbacks,
            "last_7_days_count": len(events_last_7d),
            "current_selection_count": len(current_fallbacks),
            "current_selection_events": current_fallbacks[-10:],
            "recent_events": events[-10:],
        },
    }


def record_publication_diversity_report(state: dict, now: datetime | None = None) -> dict:
    """Persist fallback events and write a machine-readable diversity report."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)

    diagnostics = _LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS
    new_events = [
        dict(event) for event in diagnostics.get("fallback_events", [])
        if isinstance(event, dict)
    ] if isinstance(diagnostics, dict) else []
    existing_events = state.get("publication_diversity_fallback_events", [])
    if not isinstance(existing_events, list):
        existing_events = []
    stamped_events = [{"at": current.isoformat(), **event} for event in new_events]
    existing_events = [*existing_events, *stamped_events]
    cutoff = current - timedelta(days=365)
    retained_events = []
    for event in existing_events:
        if not isinstance(event, dict):
            continue
        event_at = _parse_utc_datetime(event.get("at"))
        if event_at and cutoff <= event_at <= current + timedelta(minutes=5):
            retained_events.append(event)
    state["publication_diversity_fallback_events"] = retained_events[-500:]

    try:
        previous_total = max(0, int(state.get("publication_diversity_fallback_count") or 0))
    except (TypeError, ValueError, OverflowError):
        previous_total = 0
    total = previous_total + len(stamped_events)
    state["publication_diversity_fallback_count"] = total

    report = build_publication_diversity_report(
        published=state.get("published"),
        recent_publications=state.get("recent_publications"),
        now=current,
        fallback_events=state["publication_diversity_fallback_events"],
        fallback_total=total,
        fallbacks_this_selection=stamped_events,
    )
    save_json(DIVERSITY_REPORT, report)
    print(
        "PUBLISH_DIVERSITY_SUMMARY "
        + json.dumps({
            "last_24_hours": report["last_24_hours"],
            "last_7_days": report["last_7_days"],
            "fallbacks": report["fallbacks"],
            "ranked_candidates": diagnostics.get("candidate_count", 0) if isinstance(diagnostics, dict) else 0,
            "top10_ranked_categories": diagnostics.get("top10_category_counts", {}) if isinstance(diagnostics, dict) else {},
        }, ensure_ascii=False, sort_keys=True)
    )
    return report


def _publication_rank_diagnostics(ordered: list[dict], fallback_events: list[dict], candidate_count: int) -> dict:
    top10_category_counts: dict[str, int] = {}
    for item in (ordered or [])[:10]:
        category = _publication_diversity_group(item)[0]
        top10_category_counts[category] = top10_category_counts.get(category, 0) + 1
    return {
        "candidate_count": max(0, int(candidate_count)),
        "top10_category_counts": dict(sorted(top10_category_counts.items(), key=lambda row: (-row[1], row[0]))),
        "fallback_events": list(fallback_events or []),
    }


def _order_candidates_by_primary_rank(
    candidates: list[dict],
    published: dict | None = None,
    recent_publications: list | None = None,
    now: datetime | None = None,
    allow_family_repeat: bool = False,
) -> list[dict]:
    """Rank by demand, enforce specific-family cooldowns, and softly balance categories."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    remaining = sorted(list(candidates or []), key=deal_sort_key, reverse=True)
    initial_candidate_count = len(remaining)
    fallback_events: list[dict] = []
    global _LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS
    if not remaining or not (published or recent_publications):
        _LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS = _publication_rank_diagnostics(
            remaining, fallback_events, initial_candidate_count
        )
        return remaining

    # Rolling day/week/month/year concentration scores.
    horizons = (
        (24.0, 4.0),        # day
        (24.0 * 7, 2.5),    # week
        (24.0 * 30, 1.5),   # month
        (24.0 * 365, 0.75), # year
    )
    horizon_counts: list[tuple[dict[str, int], dict[str, int], dict[str, int], dict[str, int], float, int]] = []
    for hours, weight in horizons:
        records = _recent_publication_diversity(
            published, limit=RECENT_PUBLICATION_HISTORY_LIMIT,
            durable_history=recent_publications, now=current, window_hours=hours,
        )
        category_counts: dict[str, int] = {}
        family_counts: dict[str, int] = {}
        brand_counts: dict[str, int] = {}
        retailer_counts: dict[str, int] = {}
        for post in records:
            category = str(post.get("category") or "other")
            family = str(post.get("family") or category)
            brand = str(post.get("brand") or "")
            retailer = str(post.get("retailer") or _publication_retailer_group(post))
            category_counts[category] = category_counts.get(category, 0) + 1
            family_counts[family] = family_counts.get(family, 0) + 1
            if brand:
                brand_counts[brand] = brand_counts.get(brand, 0) + 1
            if retailer:
                retailer_counts[retailer] = retailer_counts.get(retailer, 0) + 1
        horizon_counts.append((category_counts, family_counts, brand_counts, retailer_counts, weight, max(1, len(records))))
    if not any(categories or families or brands or retailers for categories, families, brands, retailers, _, _ in horizon_counts):
        _LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS = _publication_rank_diagnostics(
            remaining, fallback_events, initial_candidate_count
        )
        return remaining

    # Apply cooldowns at the final selection point too. The old 4-point-only
    # lookahead could let repeated apparel offers beat comparable alternatives.
    cooldown_hours = max(
        CATEGORY_REPEAT_COOLDOWN_MINUTES / 60.0,
        FAMILY_REPEAT_COOLDOWN_HOURS,
        BRAND_REPEAT_COOLDOWN_HOURS,
        RETAILER_REPEAT_COOLDOWN_MINUTES / 60.0,
    )
    cooldown_records = _recent_publication_diversity(
        published, limit=RECENT_PUBLICATION_HISTORY_LIMIT,
        durable_history=recent_publications, now=current, window_hours=cooldown_hours,
    )
    now_ts = current.timestamp()
    recent_categories = [
        str(post.get("category") or "other") for post in cooldown_records
        if float(post.get("order") or post.get("ts") or 0)
        >= now_ts - CATEGORY_REPEAT_COOLDOWN_MINUTES * 60
    ]
    recent_families = [
        str(post.get("family") or post.get("category") or "other") for post in cooldown_records
        if float(post.get("order") or post.get("ts") or 0)
        >= now_ts - FAMILY_REPEAT_COOLDOWN_HOURS * 3600
    ]
    recent_brands = [
        str(post.get("brand") or "") for post in cooldown_records
        if post.get("brand") and float(post.get("order") or post.get("ts") or 0)
        >= now_ts - BRAND_REPEAT_COOLDOWN_HOURS * 3600
    ]
    recent_retailers = [
        str(post.get("retailer") or _publication_retailer_group(post)) for post in cooldown_records
        if (post.get("retailer") or _publication_retailer_group(post))
        and float(post.get("order") or post.get("ts") or 0)
        >= now_ts - RETAILER_REPEAT_COOLDOWN_MINUTES * 60
    ]

    def group(item: dict) -> tuple[str, str, str]:
        return _publication_diversity_group(item)

    ordered: list[dict] = []
    family_cooldown_skips = 0
    while remaining:
        if not allow_family_repeat:
            family_fresh_remaining = [
                item for item in remaining
                if not (
                    _is_specific_product_family(group(item)[0], group(item)[1])
                    and group(item)[1] in recent_families
                )
            ]
            family_cooldown_skips += len(remaining) - len(family_fresh_remaining)
            remaining = family_fresh_remaining
            if not remaining:
                break
        leader = remaining[0]
        lookahead = remaining[:DIVERSITY_LOOKAHEAD_CANDIDATES]
        def has_explicit_demand_advantage(candidate: dict, top_candidate: dict) -> bool:
            """Do not let variety override a stronger explicit retailer demand score."""
            try:
                top_score = int(top_candidate.get("demand_score") or 0)
                candidate_score = int(candidate.get("demand_score") or 0)
            except (TypeError, ValueError, OverflowError):
                return False
            if top_score <= 0:
                return False
            if candidate_score <= 0:
                return True
            minimum_comparable_score = max(
                top_score - DIVERSITY_DEMAND_SCORE_GAP,
                round(top_score * DIVERSITY_DEMAND_SCORE_RATIO),
            )
            return candidate_score < minimum_comparable_score

        comparable = [
            (position, item) for position, item in enumerate(lookahead)
            if position == 0 or (
                _candidate_demand_comparable_for_diversity(item, leader)
                and not has_explicit_demand_advantage(item, leader)
            )
        ]
        if not comparable:
            comparable = [(0, leader)]

        fresh_category_and_family = [
            row for row in comparable
            if group(row[1])[0] not in recent_categories
            and group(row[1])[1] not in recent_families
        ]
        fresh_category = [
            row for row in comparable if group(row[1])[0] not in recent_categories
        ]
        fresh_category_family_retailer = [
            row for row in comparable
            if group(row[1])[0] not in recent_categories
            and group(row[1])[1] not in recent_families
            and (
                not _publication_retailer_group(row[1])
                or _publication_retailer_group(row[1]) not in recent_retailers
            )
        ]
        fresh_family = [
            row for row in comparable if group(row[1])[1] not in recent_families
        ]
        fresh_retailer = [
            row for row in comparable
            if _publication_retailer_group(row[1])
            and _publication_retailer_group(row[1]) not in recent_retailers
        ]
        if fresh_category_family_retailer:
            pool = fresh_category_family_retailer
        elif fresh_category_and_family:
            pool = fresh_category_and_family
        elif fresh_category:
            pool = fresh_category
        elif fresh_family:
            pool = fresh_family
        elif fresh_retailer:
            pool = fresh_retailer
        else:
            pool = comparable

        def diversity_key(row: tuple[int, dict]):
            position, item = row
            category, family, brand = group(item)
            weighted_category = sum(
                weight * categories.get(category, 0) / total
                for categories, _, _, _, weight, total in horizon_counts
            )
            weighted_family = sum(
                weight * families.get(family, 0) / total
                for _, families, _, _, weight, total in horizon_counts
            )
            weighted_brand = sum(
                weight * brands.get(brand, 0) / total
                for _, _, brands, _, weight, total in horizon_counts
            ) if brand else 0.0
            retailer = _publication_retailer_group(item)
            weighted_retailer = sum(
                weight * retailers.get(retailer, 0) / total
                for _, _, _, retailers, weight, total in horizon_counts
            ) if retailer else 0.0
            cooldown_penalty = (
                (10_000 if category in recent_categories else 0)
                + (5_000 if family in recent_families else 0)
                + (2_000 if brand and brand in recent_brands else 0)
                + (1_000 if retailer and retailer in recent_retailers else 0)
            )
            return (cooldown_penalty, weighted_category, weighted_family, weighted_brand, weighted_retailer, position)

        chosen_position, chosen = min(pool, key=diversity_key)
        remaining.pop(chosen_position)
        ordered.append(chosen)
        category, family, brand = group(chosen)

        # Simulate earlier ranked choices so one returned batch isn't concentrated
        # in one category if alternatives of comparable quality exist.
        retailer = _publication_retailer_group(chosen)
        for categories, families, brands, retailers, _, _ in horizon_counts:
            categories[category] = categories.get(category, 0) + 1
            families[family] = families.get(family, 0) + 1
            if brand:
                brands[brand] = brands.get(brand, 0) + 1
            if retailer:
                retailers[retailer] = retailers.get(retailer, 0) + 1
        repeated_category = category in recent_categories
        recent_categories.append(category)
        recent_categories = recent_categories[-24:]
        recent_families.append(family)
        recent_families = recent_families[-36:]
        if brand:
            recent_brands.append(brand)
            recent_brands = recent_brands[-24:]
        if retailer:
            recent_retailers.append(retailer)
            recent_retailers = recent_retailers[-12:]

        if repeated_category:
            has_comparable_other_category = any(
                group(item)[0] != category
                and _candidate_demand_comparable_for_diversity(item, chosen)
                for _, item in comparable
            )
            if not has_comparable_other_category:
                fallback_event = {
                    "selected_rank": len(ordered),
                    "product_id": str(chosen.get("product_id") or chosen.get("id") or ""),
                    "category": category,
                    "family": family,
                    "brand": brand,
                    "reason": "no_comparable_other_category_in_lookahead",
                }
                fallback_events.append(fallback_event)
                print(
                    "PUBLISH_DIVERSITY_COOLDOWN_FALLBACK "
                    f"category={category} family={family} product_id={fallback_event['product_id'] or 'unknown'} "
                    "reason=no_comparable_alternative_in_lookahead"
                )
    _LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS = _publication_rank_diagnostics(
        ordered, fallback_events, initial_candidate_count
    )
    if family_cooldown_skips:
        print(
            f"PUBLISH_DIVERSITY_FAMILY_COOLDOWN_SKIP count={family_cooldown_skips} "
            f"remaining_candidates={len(remaining)}"
        )
    print(
        "PUBLISH_DIVERSITY_RANKING "
        + json.dumps({
            "candidates": initial_candidate_count,
            "selected": len(ordered),
            "family_cooldown_skips": family_cooldown_skips,
            "top10_categories": _LAST_PUBLICATION_DIVERSITY_DIAGNOSTICS["top10_category_counts"],
            "fallbacks_without_comparable_category": len(fallback_events),
        }, ensure_ascii=False, sort_keys=True)
    )
    return ordered

def select_urgent_publication_candidate(
    eligible: list[dict],
    now: datetime | None = None,
    published: dict | None = None,
    recent_publications: list | None = None,
) -> dict | None:
    """Choose the largest verified discount among urgent candidates in the popularity-ranked pool."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    urgent = [
        product for product in eligible
        if is_urgent_priority_deal(product, current) or is_deadline_critical_deal(product, current)
    ]
    if not urgent:
        return None
    ranked = _order_candidates_by_primary_rank(
        urgent, published=published, recent_publications=recent_publications,
        now=current, allow_family_repeat=False,
    )
    if not ranked:
        print("URGENT_PUBLICATION_DEFERRED reason=recent_family_cooldown_or_no_diverse_candidate")
        return None
    # Stable discount sort: maximum discount leads, existing demand/diversity order
    # is preserved when discounts are equal.
    ranked.sort(
        key=lambda product: max(0, int(product.get("discount_percent") or 0)),
        reverse=True,
    )
    return ranked[0]


def select_publish_candidates(
    pending_queue: dict[str, dict],
    eligible_by_id: dict[str, dict],
    now: datetime | None = None,
    published: dict | None = None,
    recent_publications: list | None = None,
) -> list[dict]:
    """Rank demand/diversity within each discount tier; never let a weaker tier jump the queue."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    selected_by_floor: dict[int, list[dict]] = {}
    deferred = 0
    for pid, record in (pending_queue.items() if isinstance(pending_queue, dict) else []):
        product = eligible_by_id.get(str(pid)) if isinstance(eligible_by_id, dict) else None
        if not isinstance(record, dict) or not isinstance(product, dict):
            continue
        retry_at = _parse_utc_datetime(record.get("next_publish_attempt_at"))
        if retry_at and retry_at > current:
            deferred += 1
            continue
        raw_floor = product.get("selection_discount_floor")
        try:
            floor = int(raw_floor) if raw_floor is not None else DISCOUNT_FALLBACK_FLOORS[0]
        except (TypeError, ValueError, OverflowError):
            continue
        if floor not in DISCOUNT_FALLBACK_FLOORS:
            continue
        selected_by_floor.setdefault(floor, []).append(product)
    if deferred:
        print(f"PUBLISH_QUEUE_BACKOFF skipped_deferred={deferred} ready={sum(map(len, selected_by_floor.values()))}")

    # Candidate discovery first builds a popularity-ranked pool. Final publication
    # then selects the largest currently verified discount inside that pool.
    ordered: list[dict] = []
    for floor in sorted(selected_by_floor, reverse=True):
        tier = _order_candidates_by_primary_rank(
            selected_by_floor[floor],
            published=published,
            recent_publications=recent_publications,
            now=current,
        )
        # Stable sort preserves the demand/diversity rank for equal discounts.
        tier.sort(
            key=lambda product: max(0, int(product.get("discount_percent") or 0)),
            reverse=True,
        )
        ordered.extend(tier)
    return ordered


MIN_REPEAT_PRODUCT_INTERVAL_HOURS = 24
PUBLICATION_LEDGER_LIMIT = 2000
# Repeat-gap preferences; diversity can reorder within a bounded demand gap to avoid category saturation.
FAMILY_REPEAT_COOLDOWN_HOURS = 4
BRAND_REPEAT_COOLDOWN_HOURS = 3
CATEGORY_REPEAT_COOLDOWN_MINUTES = 180
RETAILER_REPEAT_COOLDOWN_MINUTES = 60
DIVERSITY_LOOKAHEAD_CANDIDATES = 128
DIVERSITY_DEMAND_SCORE_GAP = 18
DIVERSITY_DEMAND_SCORE_RATIO = 0.75


def _publication_record_ts(record: dict | None) -> float:
    if not isinstance(record, dict):
        return 0.0
    try:
        return max(0.0, float(record.get("ts") or 0))
    except (TypeError, ValueError, OverflowError):
        return 0.0


def ensure_publication_ledger(state: dict) -> bool:
    """Persist each product's last publication independently of message deletion.

    Expiration cleanup and one-time user-requested removals keep this durable cooldown
    record, so a fresh discovery run cannot immediately repost a just-removed product.
    Candidate diversity ordering applies after this standard repeat guard.
    """
    if not isinstance(state, dict):
        return False
    changed = False
    published = state.get("published")
    if not isinstance(published, dict):
        published = {}
        state["published"] = published
        changed = True
    ledger = state.get("publication_ledger")
    if not isinstance(ledger, dict):
        ledger = {}
        state["publication_ledger"] = ledger
        changed = True

    fields = (
        "title", "product_url", "posted_current_price", "posted_original_price",
        "posted_discount_percent", "telegram_message_id", "bale_message_id",
        "expiry_status", "bale_expiry_status", "delivery_status", "delivery_attempts",
        "expires_at", "expiry_source", "expiry_estimated",
    )
    for pid, record in published.items():
        if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", str(pid)) or not isinstance(record, dict):
            continue
        ts = _publication_record_ts(record)
        if ts <= 0:
            continue
        old = ledger.get(str(pid))
        old_ts = _publication_record_ts(old)
        # A newer ledger entry survives any stale copy of the main published map.
        if old_ts > ts:
            continue
        entry = {"ts": ts}
        for key in fields:
            if key in record:
                entry[key] = record[key]
        if old != entry:
            ledger[str(pid)] = entry
            changed = True

    if len(ledger) > PUBLICATION_LEDGER_LIMIT:
        retained = sorted(
            ledger.items(),
            key=lambda item: _publication_record_ts(item[1]),
            reverse=True,
        )[:PUBLICATION_LEDGER_LIMIT]
        state["publication_ledger"] = dict(retained)
        changed = True
    if ensure_recent_publications(state):
        changed = True
    return changed


# Keep enough compact publication events for roughly one year at the current posting cadence.
RECENT_PUBLICATION_HISTORY_LIMIT = 30000


def ensure_recent_publications(state: dict) -> bool:
    """Seed durable category-diversity memory from the ledger and surviving records."""
    if not isinstance(state, dict):
        return False
    original = state.get("recent_publications")
    history = list(original) if isinstance(original, list) else []
    by_key = {}
    for entry in history:
        if not isinstance(entry, dict):
            continue
        pid = str(entry.get("product_id") or "").strip()
        title = str(entry.get("title") or "").strip()
        ts = _publication_record_ts(entry)
        if not pid or not title or ts <= 0:
            continue
        key = _publication_diversity_history_key(entry, pid)
        if key is None:
            continue
        previous = by_key.get(key)
        # When an identical message ID appears under multiple changed timestamps,
        # retain the earliest timestamp as the actual publication time.
        if previous is None or ts < _publication_record_ts(previous):
            by_key[key] = dict(entry)

    sources = []
    ledger = state.get("publication_ledger")
    if isinstance(ledger, dict):
        sources.extend(ledger.items())
    published = state.get("published")
    if isinstance(published, dict):
        for pid, record in published.items():
            if not isinstance(record, dict):
                continue
            sources.append((pid, record))
            items = record.get("post_history")
            if isinstance(items, list):
                sources.extend((pid, item) for item in items if isinstance(item, dict))

    for raw_pid, record in sources:
        if not isinstance(record, dict):
            continue
        pid = str(raw_pid or "").strip()
        title = str(record.get("title") or "").strip()
        ts = _publication_record_ts(record)
        if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", pid) or not title or ts <= 0:
            continue
        category, family, brand = _publication_diversity_group(title)
        retailer = _publication_retailer_group({"product_id": pid, "merchant": record.get("merchant") or ""})
        entry = {
            "ts": ts,
            "product_id": pid,
            "title": title,
            "category": category,
            "family": family,
            "brand": brand,
            "retailer": retailer,
        }
        for field in ("telegram_message_id", "bale_message_id"):
            if str(record.get(field) or "").isdigit():
                entry[field] = int(record[field])
        key = _publication_diversity_history_key(entry, pid)
        if key is None:
            continue
        old = by_key.get(key)
        if old and _publication_record_ts(old) <= ts:
            continue
        by_key[key] = entry

    retained = sorted(by_key.values(), key=lambda item: _publication_record_ts(item))[
        -RECENT_PUBLICATION_HISTORY_LIMIT:
    ]
    changed = not isinstance(original, list) or retained != original
    if changed:
        state["recent_publications"] = retained
    return changed


def _publication_cooldown_record(state: dict, pid: str) -> dict:
    """Choose the newest publication record, falling back to the durable ledger."""
    state = state if isinstance(state, dict) else {}
    published = state.get("published", {})
    ledger = state.get("publication_ledger", {})
    current = published.get(str(pid)) if isinstance(published, dict) else None
    durable = ledger.get(str(pid)) if isinstance(ledger, dict) else None
    if not isinstance(current, dict):
        return durable if isinstance(durable, dict) else {}
    if not isinstance(durable, dict):
        return current
    if _publication_record_ts(durable) > _publication_record_ts(current):
        return durable
    return current


def is_product_repeat_blocked(previous: dict, product: dict,
                              now: datetime | None = None) -> bool:
    """Block same-product repeats for at least 24 hours, even after confirmed deletion.

    After that safety window, the existing 30-day cooldown still applies unless a
    verified current price is at least 10% below the last posted price. Delivery retries
    remain eligible and are handled independently per platform.
    """
    if not isinstance(previous, dict) or not isinstance(product, dict):
        return False
    if _has_pending_delivery(previous):
        return False
    posted_at = _publication_record_ts(previous)
    if posted_at <= 0:
        return False
    now = now or datetime.now(timezone.utc)
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    elapsed = now.timestamp() - posted_at
    if elapsed < MIN_REPEAT_PRODUCT_INTERVAL_HOURS * 3600:
        return True
    return bool(
        elapsed < PRODUCT_COOLDOWN_DAYS * 86400
        and not is_materially_improved_offer(previous, product, now)
    )

def _has_active_publication_or_delivery(state: dict, pid: str) -> bool:
    """Whether this product already has an active public post or hand-off record."""
    from content_delivery import TERMINAL_QUEUE_STATUSES, _active_publication

    state = state if isinstance(state, dict) else {}
    published = state.get("published", {})
    record = published.get(str(pid)) if isinstance(published, dict) else None
    if _active_publication(record):
        return True
    queue = state.get("content_delivery_queue", {})
    entry = queue.get(str(pid)) if isinstance(queue, dict) else None
    return isinstance(entry, dict) and entry.get("status") not in TERMINAL_QUEUE_STATUSES


def is_fresh_selection_candidate(
    state: dict,
    pid: str,
    product: dict,
    now: datetime | None = None,
) -> bool:
    """True only when the product can create a new post without duplicating live work."""
    key = str(pid or "").strip().lower()
    if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", key):
        return False
    if _has_active_publication_or_delivery(state, key):
        return False
    previous = _publication_cooldown_record(state, key)
    return not is_product_repeat_blocked(previous, product, now)


def discount_fallback_band_label(floor: int, upper_exclusive: int | None) -> str:
    """Human-readable discount band used in logs and operational reports."""
    if upper_exclusive is None:
        return f"{floor}%+"
    return f"{floor}%–{upper_exclusive - 1}%"


SELECTION_REJECTION_TTL_MINUTES = 20
SELECTION_REJECTION_LIMIT = 500


def mark_selection_candidate_rejected(
    state: dict,
    product: dict,
    reason: str,
    now: datetime | None = None,
) -> None:
    """Temporarily cool down a candidate rejected by the publisher's live checks.

    A changed current/original price releases the cooldown immediately; otherwise a
    bad selection cannot monopolize every five-minute discovery cycle.
    """
    if not isinstance(state, dict) or not isinstance(product, dict):
        return
    pid = str(product.get("product_id") or product_id(product.get("product_url") or "")).strip().lower()
    if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", pid):
        return
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    try:
        current_price = int(product.get("current_price") or 0)
    except (TypeError, ValueError, OverflowError):
        current_price = 0
    try:
        original_price = int(product.get("original_price") or 0)
    except (TypeError, ValueError, OverflowError):
        original_price = 0

    rejected = state.setdefault("selection_rejections", {})
    if not isinstance(rejected, dict):
        rejected = {}
        state["selection_rejections"] = rejected
    rejected[pid] = {
        "rejected_at": current.isoformat(),
        "retry_after": (current + timedelta(minutes=SELECTION_REJECTION_TTL_MINUTES)).isoformat(),
        "reason": str(reason or "publisher_live_validation_rejected")[:180],
        "current_price": current_price,
        "original_price": original_price,
    }
    if len(rejected) > SELECTION_REJECTION_LIMIT:
        retained = sorted(
            rejected.items(),
            key=lambda item: _parse_utc_datetime(
                item[1].get("retry_after") if isinstance(item[1], dict) else None
            ) or datetime.min.replace(tzinfo=timezone.utc),
            reverse=True,
        )[:SELECTION_REJECTION_LIMIT]
        state["selection_rejections"] = dict(retained)


def is_selection_candidate_rejected(
    state: dict,
    pid: str,
    product: dict,
    now: datetime | None = None,
) -> bool:
    """Skip a recent live-rejected candidate until its offer changes or TTL expires."""
    rejected = state.get("selection_rejections") if isinstance(state, dict) else None
    if not isinstance(rejected, dict):
        return False
    key = str(pid or "").strip().lower()
    record = rejected.get(key)
    if not isinstance(record, dict):
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    retry_after = _parse_utc_datetime(record.get("retry_after"))
    if retry_after is None or retry_after <= current:
        rejected.pop(key, None)
        return False

    for field in ("current_price", "original_price"):
        try:
            previous_value = int(record.get(field) or 0)
            live_value = int((product or {}).get(field) or 0)
        except (TypeError, ValueError, OverflowError):
            previous_value = live_value = 0
        if previous_value > 0 and live_value > 0 and previous_value != live_value:
            rejected.pop(key, None)
            return False
    return True


def select_discount_fallback_candidates(
    products: list[dict],
    state: dict,
    now: datetime | None = None,
    include_fallback_bands: bool = False,
) -> tuple[list[dict], int | None, list[dict]]:
    """Select the best available discount band without relaxing demand or safety gates.

    The 50% band is preferred. 45/40/35% bands are considered only when no
    candidate exists in a higher band. Every primary and backup independently
    passes current-demand, stock, price, affiliate, market-value, expiry, and
    product-diversity checks.
    """
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    state = state if isinstance(state, dict) else {}

    quality_eligible: list[dict] = []
    fresh_candidates: list[dict] = []
    seen_ids: set[str] = set()
    for product in products or []:
        if not isinstance(product, dict):
            continue
        pid = str(product.get("product_id") or product_id(product.get("product_url") or "")).strip()
        if not pid or pid in seen_ids or is_product_suppressed(state, pid):
            continue
        if not is_discount_publish_eligible(
            product, minimum_discount_percent=MIN_DISCOUNT_FALLBACK_PERCENT, now=current
        ):
            continue
        if not is_market_value_publish_eligible(product):
            continue
        if not has_publishable_expiry_or_open_offer(product, current):
            continue
        seen_ids.add(pid)
        quality_eligible.append(product)
        if (
            not is_selection_candidate_rejected(state, pid, product, current)
            and is_fresh_selection_candidate(state, pid, product, current)
        ):
            fresh_candidates.append(product)

    fallback_pool: list[dict] = []
    first_floor: int | None = None
    for index, floor in enumerate(DISCOUNT_FALLBACK_FLOORS):
        upper_exclusive = DISCOUNT_FALLBACK_FLOORS[index - 1] if index > 0 else None
        band = [
            product for product in fresh_candidates
            if int(product.get("discount_percent") or 0) >= floor
            and (
                upper_exclusive is None
                or int(product.get("discount_percent") or 0) < upper_exclusive
            )
        ]
        if not band:
            continue
        ranked = _order_candidates_by_primary_rank(
            band,
            published=state.get("published"),
            recent_publications=state.get("recent_publications"),
            now=current,
            allow_family_repeat=False,
        )
        if not ranked:
            print(
                f"DISCOUNT_FALLBACK_BAND_EXHAUSTED band={discount_fallback_band_label(floor, upper_exclusive)} "
                "reason=recent_family_cooldown"
            )
            # Do not use a weaker discount band to bypass a higher band whose
            # otherwise-qualified products are temporarily excluded by diversity.
            if first_floor is None:
                print(
                    f"DISCOUNT_FALLBACK_LOWER_BANDS_SUPPRESSED blocked_floor={floor}% "
                    "reason=higher_band_blocked_by_diversity"
                )
                break
            continue

        label = discount_fallback_band_label(floor, upper_exclusive)
        handoff_candidates = []
        for product in ranked:
            selected_product = dict(product)
            selected_product["selection_discount_floor"] = int(floor)
            selected_product["selection_discount_band"] = label
            handoff_candidates.append(selected_product)

        if first_floor is None:
            first_floor = floor
            print(
                f"DISCOUNT_FALLBACK_SELECTED band={label} floor={floor}% "
                f"quality_pool={len(quality_eligible)} fresh_pool={len(fresh_candidates)} "
                f"band_candidates={len(band)}"
            )
        elif include_fallback_bands:
            print(
                f"DISCOUNT_FALLBACK_BACKUP_BAND band={label} "
                f"floor={floor}% candidates={len(handoff_candidates)}"
            )

        if not include_fallback_bands:
            return handoff_candidates, floor, quality_eligible
        fallback_pool.extend(handoff_candidates)

    if fallback_pool:
        print(
            f"DISCOUNT_FALLBACK_POOL_READY primary_floor={first_floor}% "
            f"ranked_backups={max(0, len(fallback_pool) - 1)}"
        )
        return fallback_pool, first_floor, quality_eligible

    print(
        f"DISCOUNT_FALLBACK_EXHAUSTED floors={','.join(str(x) for x in DISCOUNT_FALLBACK_FLOORS)} "
        f"quality_pool={len(quality_eligible)} fresh_pool={len(fresh_candidates)}"
    )
    return [], None, quality_eligible


def restore_selection_discount_tiers(
    selected_candidates: list[dict],
    tiered_candidates: list[dict],
) -> int:
    """Restore the selected discount floor after publication ranking.

    The tier selector ranks copies annotated with their own allowed minimum.
    The publication ranker operates on the original quality records, so this
    metadata must be copied back before the queue hand-off or the publisher
    incorrectly falls back to the legacy 50% floor for every product.
    """
    tiers_by_id: dict[str, dict] = {}
    for candidate in tiered_candidates or []:
        if not isinstance(candidate, dict):
            continue
        pid = str(
            candidate.get("product_id")
            or product_id(candidate.get("product_url") or "")
        ).strip()
        try:
            floor = int(candidate.get("selection_discount_floor"))
        except (TypeError, ValueError, OverflowError):
            continue
        if not pid or floor not in DISCOUNT_FALLBACK_FLOORS:
            continue
        tier = {"selection_discount_floor": floor}
        band = str(candidate.get("selection_discount_band") or "").strip()
        if band:
            tier["selection_discount_band"] = band
        tiers_by_id[pid] = tier

    restored = 0
    for candidate in selected_candidates or []:
        if not isinstance(candidate, dict):
            continue
        pid = str(
            candidate.get("product_id")
            or product_id(candidate.get("product_url") or "")
        ).strip()
        tier = tiers_by_id.get(pid)
        if not tier:
            continue
        candidate.update(tier)
        restored += 1
    return restored


def _has_pending_channel_retry(state: dict, pid: str) -> bool:
    """A failed channel destination may be rechecked, but never becomes a new selection."""
    return _has_pending_delivery(_publication_cooldown_record(state or {}, str(pid)))



def is_product_suppressed(state: dict, pid: str) -> bool:
    """Return true for a product explicitly excluded by the user."""
    if not isinstance(state, dict):
        return False
    key = str(pid or "").strip().lower()
    if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", key):
        key = product_id(key)
    suppressions = state.get("product_suppressions", {})
    return bool(key and isinstance(suppressions, dict) and key in suppressions)


def prune_suppressed_product_queues(state: dict) -> bool:
    """Remove permanently excluded IDs from the two publication queues."""
    suppressions = state.get("product_suppressions", {}) if isinstance(state, dict) else {}
    if not isinstance(suppressions, dict) or not suppressions:
        return False
    suppressed = {str(k).strip().lower() for k in suppressions if re.fullmatch(r"(?:dkp|snp)-\d{1,12}", str(k).strip().lower())}
    changed = False
    for name in ("pending_queue", "discovery_queue"):
        queue = state.get(name)
        if isinstance(queue, dict):
            for key, value in list(queue.items()):
                pid = str(key or "").strip().lower()
                if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", pid) and isinstance(value, dict):
                    pid = str(value.get("product_id") or value.get("id") or "").strip().lower()
                    if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", pid):
                        pid = product_id(value.get("product_url") or value.get("url") or "")
                if pid in suppressed:
                    queue.pop(key, None)
                    changed = True
        elif isinstance(queue, list):
            retained = []
            for item in queue:
                pid = ""
                if isinstance(item, dict):
                    pid = str(item.get("product_id") or item.get("id") or "").strip().lower()
                    if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", pid):
                        pid = product_id(item.get("product_url") or item.get("url") or "")
                if pid in suppressed:
                    changed = True
                else:
                    retained.append(item)
            if len(retained) != len(queue):
                state[name] = retained
    return changed


def refresh_pending_queue(state: dict, eligible: list[dict],
                          now: datetime | None = None,
                          observed_product_ids: set[str] | None = None) -> dict:
    """Persist valid offers; keep unobserved queued offers until rechecked or their deadline passes."""
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    prune_suppressed_product_queues(state)
    old_queue = state.get("pending_queue")
    if not isinstance(old_queue, dict):
        old_queue = {}
    published = state.setdefault("published", {})
    ensure_publication_ledger(state)
    candidate_by_id = {}
    pending = {}
    for product in eligible:
        pid = str(product.get("product_id") or product_id(product.get("product_url", "")))
        if not re.fullmatch(r"(?:dkp|snp)-\d{1,12}", pid) or is_product_suppressed(state, pid) or is_offer_expired(product, now):
            continue
        previous_publication = _publication_cooldown_record(state, pid)
        # Delivery retries are handled independently below. A product with an
        # already-active public post (or a video still awaiting its own quota slot)
        # must not re-enter the fresh-selection queue.
        if _has_active_publication_or_delivery(state, pid):
            continue
        if is_product_repeat_blocked(previous_publication, product, now):
            continue

        old = old_queue.get(pid, {})
        old_first_seen = _parse_utc_datetime(old.get("first_seen_at")) if isinstance(old, dict) else None
        try:
            old_publish_failures = max(0, int(old.get("publish_failure_count") or 0)) if isinstance(old, dict) else 0
        except (TypeError, ValueError, OverflowError):
            old_publish_failures = 0
        if old_first_seen is None or (now - old_first_seen).total_seconds() > PENDING_QUEUE_TTL_HOURS * 3600:
            old_first_seen = now
        expiry = _parse_utc_datetime(_parse_deal_expiry_value(product.get("deal_expires_at")))
        pending[pid] = {
            "product_id": pid,
            "title": str(product.get("title") or "")[:180],
            "product_url": safe_product_url(product.get("product_url", "")),
            "first_seen_at": old_first_seen.isoformat(),
            "deal_expires_at": expiry.isoformat() if expiry else "",
            "current_price": int(product.get("current_price") or 0),
            "original_price": int(product.get("original_price") or 0),
            "discount_percent": int(product.get("discount_percent") or 0),
            "savings_toman": int(product.get("savings_toman") or 0),
            "demand_score": int(product.get("demand_score") or 0),
            "promo_score": int(product.get("promo_score") or 0),
            "urgent": is_urgent_priority_deal(product, now),
            "publish_failure_count": old_publish_failures,
            "next_publish_attempt_at": str(old.get("next_publish_attempt_at") or "") if isinstance(old, dict) else "",
            "last_publish_failure": str(old.get("last_publish_failure") or "") if isinstance(old, dict) else "",
            "last_publish_failure_at": str(old.get("last_publish_failure_at") or "") if isinstance(old, dict) else "",
        }
        candidate_by_id[pid] = product

    # Do not discard a valid queued deal merely because pagination did not return it in
    # this scan. Keep it until the deadline passes, and bring it back through discovery
    # for a fresh stock/price check. If it was checked this run and failed eligibility,
    # it is deliberately not retained.
    observed_ids = {str(value) for value in observed_product_ids} if observed_product_ids is not None else None
    if observed_ids is not None:
        for pid, old in old_queue.items():
            if not isinstance(old, dict) or pid in pending or pid in observed_ids or is_product_suppressed(state, str(pid)):
                continue
            url = safe_product_url(old.get("product_url", ""))
            expiry = _parse_utc_datetime(_parse_deal_expiry_value(old.get("deal_expires_at")))
            if not url or product_id(url) != str(pid) or expiry is None or expiry <= now:
                continue
            previous_publication = _publication_cooldown_record(state, str(pid))
            if _has_active_publication_or_delivery(state, str(pid)):
                continue
            if is_product_repeat_blocked(previous_publication, old, now):
                continue
            retained = dict(old)
            retained["product_id"] = str(pid)
            retained["product_url"] = url
            retained["deal_expires_at"] = expiry.isoformat()
            retained["urgent"] = is_urgent_priority_deal(retained, now)
            pending[str(pid)] = retained
            candidate_by_id[str(pid)] = retained

    ordered_ids = sorted(
        pending,
        key=lambda pid: pending_queue_sort_key(candidate_by_id[pid], pending[pid], now),
        reverse=True,
    )[:PENDING_QUEUE_LIMIT]
    queue = {pid: pending[pid] for pid in ordered_ids}
    state["pending_queue"] = queue
    urgent_count = sum(1 for item in queue.values() if item.get("urgent"))
    top = ordered_ids[0] if ordered_ids else "none"
    retained_count = sum(1 for pid in queue if pid not in {str(p.get("product_id") or product_id(p.get("product_url", ""))) for p in eligible})
    print(f"PENDING_QUEUE size={len(queue)} urgent={urgent_count} retained_unobserved={retained_count} top={top}")
    return queue


def preferred_publication_window(now: datetime | None = None) -> str:
    """Return the preferred audience window using Iran local time; otherwise quiet_hours."""
    now = now or datetime.now(timezone.utc)
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    local_now = now.astimezone(IRAN_TIMEZONE)
    for name, start_hour, end_hour in PREFERRED_POSTING_WINDOWS:
        if start_hour <= local_now.hour < end_hour:
            return name
    return "quiet_hours"


def is_preferred_publication_time(now: datetime | None = None) -> bool:
    """Regular posts are limited to the three broad Iran-time audience windows."""
    return preferred_publication_window(now) != "quiet_hours"


def _last_post_timestamp(state):
    try:
        previous = datetime.fromisoformat(str(state.get("last_published_at", "")))
        if previous.tzinfo is None:
            previous = previous.replace(tzinfo=timezone.utc)
        return previous.timestamp()
    except (TypeError, ValueError):
        return 0.0

def daily_channel_posts_count(state: dict, now: datetime | None = None) -> int:
    """Count channel publications on the current Iran calendar day, independently of YouTube quota resets."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    channel_day = current.astimezone(IRAN_TIMEZONE).date()
    published = state.get("published", {}) if isinstance(state, dict) else {}
    count = 0
    for record in published.values() if isinstance(published, dict) else []:
        if not isinstance(record, dict):
            continue
        delivery = record.get("delivery_status", {})
        if not isinstance(delivery, dict) or not any(value == "sent" for value in delivery.values()):
            continue
        try:
            stamp = float(record.get("ts") or 0)
            if stamp <= 0:
                continue
            posted_day = datetime.fromtimestamp(stamp, timezone.utc).astimezone(
                IRAN_TIMEZONE
            ).date()
        except (TypeError, ValueError, OverflowError, OSError):
            continue
        if posted_day == channel_day:
            count += 1
    return count


def effective_posts_per_run(backlog_count, configured_limit=None, force_full_batch=False):
    """Use one post per scan normally, and permit a two-post burst only during backlog."""
    try:
        configured = MAX_POSTS_PER_RUN if configured_limit is None else int(configured_limit)
        configured = max(1, min(10, configured))
    except (TypeError, ValueError, OverflowError):
        configured = 1
    if force_full_batch:
        return configured
    try:
        backlog = max(0, int(backlog_count))
    except (TypeError, ValueError, OverflowError):
        backlog = 0
    if backlog >= PUBLISH_BACKLOG_BURST_THRESHOLD:
        return min(configured, PUBLISH_BACKLOG_BURST_MAX_POSTS)
    return min(configured, 1)




VIDEO_STYLE_VERSION = 5  # Vazirmatn ExtraBold Persian discount badge with larger type
YOUTUBE_DESCRIPTION_VERSION = 3  # public channel links plus product-specific checked purchase link
PERSIAN_TEXT_RENDERER_VERSION = 2  # single RTL/bidi pass via Pillow RAQM when available
PERSIAN_TEXT_REPAIR_PRODUCT_IDS = ("dkp-19336870", "dkp-21887319")
# The generic web uploader can publish vertical 9:16 videos to Aparat's regular feed, but cannot guarantee
# placement in Aparat Shorts (which currently requires the official app). Keep queue-only mode opt-in.
APARAT_SHORTS_ONLY = str(os.getenv("APARAT_SHORTS_ONLY", "false")).strip().lower() in {"1", "true", "yes", "on"}
# The main radar and the dedicated Aparat workflow can independently enable this destination.
APARAT_UPLOAD_ENABLED = str(os.getenv("AFFILIO_APARAT_UPLOAD_ENABLED", "true")).strip().lower() in {"1", "true", "yes", "on"}
# Match video throughput to channel publication bursts so the video queue does not lag behind.
MAX_SHORT_VIDEOS_PER_RUN = max(1, min(4, int(os.getenv("AFFILIO_MAX_SHORT_VIDEOS_PER_RUN", "2"))))


def _delete_superseded_youtube_video(
    record: dict,
    product_id_value: str,
    delete_fn,
    now: datetime | None = None,
) -> bool:
    """Delete a replaced Short only after its corrected replacement is confirmed uploaded."""
    old_video_id = str(record.get("youtube_previous_video_id") or "").strip()
    new_video_id = str(record.get("youtube_video_id") or "").strip()
    if (
        not old_video_id
        or not new_video_id
        or old_video_id == new_video_id
        or str(record.get("youtube_upload_status") or "") != "uploaded"
    ):
        return False

    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    retry_at = _parse_utc_datetime(
        record.get("youtube_previous_video_delete_next_attempt_at")
    )
    if retry_at and current < retry_at:
        return False

    try:
        outcome = delete_fn(old_video_id)
        if outcome not in {"deleted", "already_absent"}:
            raise RuntimeError("YouTube did not confirm deletion of the replaced Short")
        record["youtube_previous_video_deleted_at"] = current.isoformat()
        record["youtube_video_renderer_version"] = PERSIAN_TEXT_RENDERER_VERSION
        record.pop("youtube_previous_video_id", None)
        record.pop("youtube_previous_video_delete_next_attempt_at", None)
        record.pop("youtube_previous_video_delete_attempts", None)
        record.pop("youtube_previous_video_delete_last_error", None)
        record.pop("video_repair_priority", None)
        print(
            f"YOUTUBE_REPLACED_VIDEO_DELETE_OK product_id={product_id_value} "
            f"old_video_id={old_video_id} outcome={outcome}"
        )
    except Exception as exc:
        try:
            attempts = int(record.get("youtube_previous_video_delete_attempts", 0) or 0) + 1
        except (TypeError, ValueError, OverflowError):
            attempts = 1
        record["youtube_previous_video_delete_attempts"] = attempts
        delay = min(3600, 300 * (2 ** min(attempts - 1, 4)))
        record["youtube_previous_video_delete_next_attempt_at"] = (
            current + timedelta(seconds=delay)
        ).isoformat()
        record["youtube_previous_video_delete_last_error"] = type(exc).__name__
        print(
            f"YOUTUBE_REPLACED_VIDEO_DELETE_FAILED product_id={product_id_value} "
            f"old_video_id={old_video_id} error={type(exc).__name__} retry_attempt={attempts}"
        )
    return True


def repair_persian_text_video_uploads() -> int:
    """Safely replace the two latest Shorts rendered with the broken Persian text layout."""
    current = datetime.now(timezone.utc)
    state = load_state()
    published = state.get("published") if isinstance(state, dict) else None
    if not isinstance(published, dict):
        print("PERSIAN_TEXT_VIDEO_REPAIR_ABORTED reason=published_state_unavailable")
        return 1

    queued = 0
    already_current = 0
    unavailable = []
    for pid in PERSIAN_TEXT_REPAIR_PRODUCT_IDS:
        record = published.get(pid)
        if not isinstance(record, dict):
            unavailable.append(f"{pid}:record_missing")
            print(f"PERSIAN_TEXT_VIDEO_REPAIR_SKIP product_id={pid} reason=record_missing")
            continue

        current_video_id = str(record.get("youtube_video_id") or "").strip()
        previous_video_id = str(record.get("youtube_previous_video_id") or "").strip()
        status = str(record.get("youtube_upload_status") or "")
        if (
            int(record.get("youtube_video_renderer_version", 0) or 0)
            >= PERSIAN_TEXT_RENDERER_VERSION
            and current_video_id
            and status == "uploaded"
            and not previous_video_id
        ):
            already_current += 1
            print(f"PERSIAN_TEXT_VIDEO_REPAIR_SKIP product_id={pid} reason=already_repaired")
            continue

        # A previous attempt may have uploaded the replacement but failed to delete
        # the old video. Keep that transaction and retry cleanup; never upload twice.
        if previous_video_id and current_video_id and status == "uploaded":
            record["video_repair_priority"] = True
            queued += 1
            continue

        if previous_video_id and not current_video_id and status in {
            "pending", "retry", "uploading", "upload_result_unknown", "pending_credentials"
        }:
            record["video_repair_priority"] = True
            queued += 1
            continue

        if not current_video_id or status != "uploaded":
            unavailable.append(f"{pid}:existing_upload_not_confirmed")
            print(f"PERSIAN_TEXT_VIDEO_REPAIR_SKIP product_id={pid} reason=existing_upload_not_confirmed")
            continue

        # Preserve the known-good public video until its corrected replacement uploads.
        record["youtube_previous_video_id"] = current_video_id
        record["youtube_video_id"] = ""
        record["youtube_video_url"] = ""
        record["youtube_upload_status"] = "pending"
        record["video_generation_status"] = "pending"
        record["video_style_version"] = 0
        record["video_repair_priority"] = True
        record["youtube_visual_repair_started_at"] = current.isoformat()
        record.pop("youtube_next_attempt_at", None)
        record.pop("video_generation_next_attempt_at", None)
        record.pop("youtube_last_error", None)
        queued += 1
        print(
            f"PERSIAN_TEXT_VIDEO_REPAIR_QUEUED product_id={pid} "
            f"previous_video_id={current_video_id}"
        )

    save_json(STATE, state)
    # Each call handles at most one generated video. Repair-priority records are
    # selected before any unrelated backlog item, while all other queues stay intact.
    attempts = 0
    max_attempts = max(2, len(PERSIAN_TEXT_REPAIR_PRODUCT_IDS) * 2)
    while attempts < max_attempts:
        state = load_state()
        published = state.get("published", {}) if isinstance(state, dict) else {}
        remaining = []
        for pid in PERSIAN_TEXT_REPAIR_PRODUCT_IDS:
            record = published.get(pid, {}) if isinstance(published, dict) else {}
            if not isinstance(record, dict):
                remaining.append(pid)
                continue
            vid = str(record.get("youtube_video_id") or "").strip()
            old_vid = str(record.get("youtube_previous_video_id") or "").strip()
            status = str(record.get("youtube_upload_status") or "")
            version = int(record.get("youtube_video_renderer_version", 0) or 0)
            if not (version >= PERSIAN_TEXT_RENDERER_VERSION and vid and status == "uploaded" and not old_vid):
                remaining.append(pid)
        if not remaining:
            break
        if not process_pending_short_video(state, now=current, output_dir="video_artifacts"):
            break
        attempts += 1

    final_state = load_state()
    final_published = final_state.get("published", {}) if isinstance(final_state, dict) else {}
    repaired = []
    pending = []
    for pid in PERSIAN_TEXT_REPAIR_PRODUCT_IDS:
        record = final_published.get(pid, {}) if isinstance(final_published, dict) else {}
        if not isinstance(record, dict):
            pending.append(pid)
            continue
        vid = str(record.get("youtube_video_id") or "").strip()
        old_vid = str(record.get("youtube_previous_video_id") or "").strip()
        status = str(record.get("youtube_upload_status") or "")
        version = int(record.get("youtube_video_renderer_version", 0) or 0)
        if version >= PERSIAN_TEXT_RENDERER_VERSION and vid and status == "uploaded" and not old_vid:
            repaired.append(pid)
        else:
            pending.append(pid)
    print(
        f"PERSIAN_TEXT_VIDEO_REPAIR_SUMMARY repaired={len(repaired)} "
        f"pending={len(pending)} already_current={already_current} "
        f"queued_initially={queued} unavailable={len(unavailable)}"
    )
    if pending:
        print(f"PERSIAN_TEXT_VIDEO_REPAIR_PENDING product_ids={','.join(pending)}")
    return 0 if len(repaired) + already_current == len(PERSIAN_TEXT_REPAIR_PRODUCT_IDS) else 1


def _next_youtube_daily_upload_retry_at(now: datetime | None = None) -> datetime:
    """Defer a channel daily-upload-limit error for 24 hours, plus a small safety buffer."""
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    return current.astimezone(timezone.utc) + timedelta(hours=24, minutes=15)


def _initialize_aparat_upload_slot(state: dict) -> datetime | None:
    """Load Aparat's next-upload slot or migrate it from Aparat upload history."""
    next_slot = _parse_utc_datetime(state.get("aparat_next_upload_at"))
    if next_slot is not None:
        return next_slot

    published = state.get("published", {})
    candidates: list[datetime] = []
    if isinstance(published, dict):
        for record in published.values():
            if not isinstance(record, dict):
                continue
            if str(record.get("aparat_upload_status") or "") != "uploaded":
                continue
            uploaded_at = _parse_utc_datetime(record.get("aparat_uploaded_at"))
            if uploaded_at is not None:
                candidates.append(uploaded_at)

    for key in ("aparat_last_upload_success_at", "aparat_last_upload_outcome_unknown_at"):
        timestamp = _parse_utc_datetime(state.get(key))
        if timestamp is not None:
            candidates.append(timestamp)

    if not candidates:
        return None

    next_slot = max(candidates) + timedelta(hours=APARAT_UPLOAD_INTERVAL_HOURS)
    state["aparat_next_upload_at"] = next_slot.isoformat()
    return next_slot


def _aparat_upload_slot_due(
    state: dict,
    now: datetime | None = None,
    credentials_ready: bool = True,
) -> bool:
    """Check Aparat's upload slot independently of YouTube status and credentials."""
    if not credentials_ready:
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    next_slot = _initialize_aparat_upload_slot(state)
    return next_slot is None or current >= next_slot


def process_pending_short_video(
    state: dict,
    now: datetime | None = None,
    output_dir: str | Path = "video_artifacts",
    destinations: set[str] | None = None,
    force_due: bool = False,
    only_product_id: str | None = None,
) -> bool:
    """Generate and publish a vertical artifact for a selected product.

    Normal queue scans respect each platform's upload schedule. The external publisher
    may pass force_due=True and product_id to process one selected item immediately;
    this bypasses only cross-item spacing, never daily quotas, credentials or platform
    failure handling. Missing expiry can be allowed in this path because the independent
    live price/stock audit removes stale posts when the offer is no longer valid.
    """
    selected_destinations = (
        {"youtube", "aparat"} if destinations is None
        else {str(item).strip().lower() for item in destinations}
    )
    try:
        from short_video import (
            render_short_video,
            upload_youtube_video,
            update_youtube_video_description,
            delete_youtube_video,
            youtube_credentials_available,
            send_telegram_video_review,
            telegram_video_review_available,
        )
    except Exception as exc:
        print(f"SHORT_VIDEO_SKIP reason=renderer_import_failed error={type(exc).__name__}")
        return False

    # Keep the Aparat integration optional: an import failure there must not suppress
    # the YouTube destination or the private review artifact.
    try:
        from aparat_uploader import (
            aparat_credentials_available,
            upload_aparat_video,
            find_uploaded_aparat_video,
            PENDING_APARAT_STATUSES,
        )
    except Exception as exc:
        def _aparat_unavailable() -> bool:
            return False
        aparat_credentials_available = _aparat_unavailable
        upload_aparat_video = None
        find_uploaded_aparat_video = None
        PENDING_APARAT_STATUSES = {"pending", "pending_credentials", "retry"}
        print(f"APARAT_SETUP_UNAVAILABLE error={type(exc).__name__}; YouTube processing continues")

    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    published = state.get("published", {})
    if not isinstance(published, dict):
        return False

    youtube_ready = "youtube" in selected_destinations and youtube_credentials_available()
    try:
        aparat_ready = (
            "aparat" in selected_destinations
            and APARAT_UPLOAD_ENABLED
            and aparat_credentials_available()
        )
    except Exception as exc:
        aparat_ready = False
        print(f"APARAT_CREDENTIAL_CHECK_FAILED error={type(exc).__name__}; other destinations continue")
    review_ready = destinations is None and telegram_video_review_available()
    pending_youtube = {"pending", "pending_credentials", "retry"}
    candidates = []
    state_changed = False

    youtube_pause_until = _parse_utc_datetime(state.get("youtube_uploads_paused_until"))

    # One-time migration: earlier runs saved the channel-limit error per video
    # before the global cooldown existed. Promote that persisted evidence into a
    # channel-wide pause to prevent wasting another upload request after deployment.
    if state.get("youtube_upload_pause_diagnostic_migrated") is not True:
        if youtube_pause_until is None:
            daily_limit_markers = (
                "uploadlimitexceeded",
                "video uploads per day",
                "daily video upload limit",
            )
            for existing_pid, existing_record in published.items():
                if not isinstance(existing_record, dict):
                    continue
                existing_error = str(existing_record.get("youtube_last_error") or "").casefold()
                if any(marker in existing_error for marker in daily_limit_markers):
                    youtube_pause_until = _next_youtube_daily_upload_retry_at(current)
                    state["youtube_uploads_paused_until"] = youtube_pause_until.isoformat()
                    state["youtube_upload_pause_reason"] = "daily_upload_limit"
                    print(
                        f"YOUTUBE_DAILY_LIMIT_PAUSE_MIGRATED product_id={existing_pid} "
                        f"until={youtube_pause_until.isoformat()}"
                    )
                    break
        state["youtube_upload_pause_diagnostic_migrated"] = True
        state_changed = True

    if youtube_pause_until and current >= youtube_pause_until:
        state.pop("youtube_uploads_paused_until", None)
        state.pop("youtube_upload_pause_reason", None)
        youtube_pause_until = None
        state_changed = True

    # Migrate existing uploads into a durable three-hour spacing schedule. The radar
    # still refreshes candidates every five minutes, but only chooses/renders a public
    # YouTube Short when a publication slot is due.
    youtube_next_upload_at = _parse_utc_datetime(state.get("youtube_next_upload_at"))
    if youtube_next_upload_at is None:
        last_successful_uploads = []
        for existing_record in published.values():
            if not isinstance(existing_record, dict):
                continue
            if str(existing_record.get("youtube_upload_status") or "") != "uploaded":
                continue
            uploaded_at = _parse_utc_datetime(existing_record.get("youtube_uploaded_at"))
            if uploaded_at is not None:
                last_successful_uploads.append(uploaded_at)
        last_upload_at = max(last_successful_uploads) if last_successful_uploads else None
        if last_upload_at is not None:
            youtube_next_upload_at = last_upload_at + timedelta(hours=YOUTUBE_UPLOAD_INTERVAL_HOURS)
            state["youtube_next_upload_at"] = youtube_next_upload_at.isoformat()
            state_changed = True

    youtube_pause_active = bool(youtube_pause_until and current < youtube_pause_until)
    youtube_upload_due = (
        youtube_ready
        and not youtube_pause_active
        and (force_due or youtube_next_upload_at is None or current >= youtube_next_upload_at)
    )
    if youtube_pause_active:
        print(
            f"YOUTUBE_UPLOADS_PAUSED reason={state.get('youtube_upload_pause_reason', 'daily_upload_limit')} "
            f"until={youtube_pause_until.isoformat()}"
        )
    elif youtube_ready and not youtube_upload_due and youtube_next_upload_at is not None:
        print(f"YOUTUBE_UPLOAD_SLOT_WAIT next_at={youtube_next_upload_at.isoformat()}")

    # Aparat's upload clock is independent: a YouTube pause/cadence must not postpone it.
    aparat_schedule_before = str(state.get("aparat_next_upload_at") or "")
    aparat_upload_due = bool(force_due and aparat_ready) or _aparat_upload_slot_due(state, current, aparat_ready)
    aparat_next_upload_at = _parse_utc_datetime(state.get("aparat_next_upload_at"))
    if str(state.get("aparat_next_upload_at") or "") != aparat_schedule_before:
        state_changed = True
    if aparat_ready and not aparat_upload_due and aparat_next_upload_at is not None:
        print(f"APARAT_UPLOAD_SLOT_WAIT next_at={aparat_next_upload_at.isoformat()}")

    if youtube_ready:
        for existing_pid, existing_record in published.items():
            if isinstance(existing_record, dict) and _delete_superseded_youtube_video(
                existing_record, str(existing_pid), delete_youtube_video, current
            ):
                state_changed = True

    # Bring descriptions on already-published, still-live Shorts into line with the current
    # clean channel-link template. Updates are versioned, capped per scan, and failure-isolated.
    if youtube_ready:
        description_updates = 0
        description_state_changed = False
        ordered_records = sorted(
            published.items(),
            key=lambda pair: float(pair[1].get("ts") or 0) if isinstance(pair[1], dict) else 0,
            reverse=True,
        )
        for pid, existing_record in ordered_records:
            if description_updates >= 3:
                break
            if not isinstance(existing_record, dict):
                continue
            video_id = str(existing_record.get("youtube_video_id") or "").strip()
            if not video_id or str(existing_record.get("youtube_upload_status") or "") != "uploaded":
                continue
            try:
                description_version = int(existing_record.get("youtube_description_version", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                description_version = 0
            if description_version >= YOUTUBE_DESCRIPTION_VERSION:
                continue
            live_expiry = _parse_utc_datetime(
                _parse_deal_expiry_value(existing_record.get("expires_at"))
            )
            if (
                live_expiry is None
                or live_expiry <= current + timedelta(minutes=10)
                or existing_record.get("expiry_source") not in {"digikala_live_deals_feed", "digikala_mcp_offer_card"}
                or existing_record.get("expiry_estimated") is True
                or (existing_record.get("expiry_source") == "digikala_mcp_offer_card" and existing_record.get("expiry_deadline_verified_from_site_card") is not True)
                or existing_record.get("youtube_expiry_status") in {"private", "already_private"}
            ):
                continue
            retry_at = _parse_utc_datetime(
                existing_record.get("youtube_description_next_attempt_at")
            )
            if retry_at and current < retry_at:
                continue

            description_updates += 1
            try:
                update_youtube_video_description(
                    video_id,
                    build_video_channel_description(state, "youtube", record=existing_record),
                )
                existing_record["youtube_description_version"] = YOUTUBE_DESCRIPTION_VERSION
                existing_record["youtube_description_updated_at"] = current.isoformat()
                existing_record.pop("youtube_description_next_attempt_at", None)
                existing_record.pop("youtube_description_last_error", None)
                print(f"YOUTUBE_DESCRIPTION_UPDATE_OK product_id={pid} video_id={video_id}")
            except Exception as exc:
                try:
                    attempts = int(existing_record.get("youtube_description_update_attempts", 0) or 0) + 1
                except (TypeError, ValueError, OverflowError):
                    attempts = 1
                existing_record["youtube_description_update_attempts"] = attempts
                existing_record["youtube_description_next_attempt_at"] = (
                    current + timedelta(seconds=min(3600, 300 * (2 ** min(attempts - 1, 4))))
                ).isoformat()
                existing_record["youtube_description_last_error"] = type(exc).__name__
                print(
                    f"YOUTUBE_DESCRIPTION_UPDATE_FAILED product_id={pid} "
                    f"error={type(exc).__name__} retry_attempt={attempts}"
                )
            description_state_changed = True
        if description_state_changed:
            save_json(STATE, state)

    # Reconcile a successful upload whose API response omitted the video UID.
    # This only queries the account's video list; it never retries the upload.
    if aparat_ready:
        for pid, record in published.items():
            if not isinstance(record, dict):
                continue
            if str(record.get("aparat_upload_status") or "") != "uploaded":
                continue
            if str(record.get("aparat_video_hash") or "").strip():
                continue
            retry_at = _parse_utc_datetime(record.get("aparat_video_lookup_next_attempt_at"))
            if retry_at and current < retry_at:
                continue
            try:
                found = find_uploaded_aparat_video(
                    str(record.get("title") or ""),
                    video_id=record.get("aparat_video_record_id") or None,
                )
                if found.get("video_hash"):
                    record["aparat_video_record_id"] = found.get("video_id") or record.get("aparat_video_record_id", "")
                    record["aparat_video_hash"] = found["video_hash"]
                    record["aparat_video_url"] = found.get("url", "")
                    record.pop("aparat_video_lookup_next_attempt_at", None)
                    record.pop("aparat_video_lookup_last_error", None)
                    print(
                        f"APARAT_VIDEO_RECONCILED id={pid} "
                        f"video_record_id={record.get('aparat_video_record_id') or 'unknown'} "
                        f"url={record['aparat_video_url']}"
                    )
                else:
                    record["aparat_video_lookup_next_attempt_at"] = (
                        current + timedelta(minutes=15)
                    ).isoformat()
                    record["aparat_video_lookup_last_error"] = "not_found_or_uid_pending"
                    print(f"APARAT_VIDEO_RECONCILE_PENDING id={pid} reason=not_found_or_uid_pending")
                state_changed = True
            except Exception as exc:
                record["aparat_video_lookup_next_attempt_at"] = (
                    current + timedelta(minutes=15)
                ).isoformat()
                record["aparat_video_lookup_last_error"] = type(exc).__name__
                state_changed = True
                print(f"APARAT_VIDEO_RECONCILE_FAILED id={pid} error={type(exc).__name__}")
            break  # One lookup per scan; other posting and video tasks remain independent.

    for pid, record in published.items():
        if not isinstance(record, dict):
            continue
        if only_product_id is not None and str(pid) != str(only_product_id):
            continue
        generation_status = str(record.get("video_generation_status") or "")
        if generation_status == "generated":
            try:
                style_version = int(record.get("video_style_version", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                style_version = 0
            if style_version < VIDEO_STYLE_VERSION:
                # Rebuild older saved artifacts once so they get the new badge, motion, and music.
                record["video_generation_status"] = "pending"
                generation_status = "pending"
                state_changed = True
                print(f"SHORT_VIDEO_REGENERATE id={pid} old_style={style_version} new_style={VIDEO_STYLE_VERSION}")
        upload_status = str(record.get("youtube_upload_status") or "pending_credentials")
        aparat_status = str(record.get("aparat_upload_status") or "pending_credentials")
        # Requeue deals previously held for manual Shorts publication. They still must
        # pass the live-deadline checks below before a public upload can occur.
        if not APARAT_SHORTS_ONLY and aparat_status == "waiting_shorts_uploader":
            record["aparat_upload_status"] = "pending"
            record["aparat_shorts_upload_status"] = "superseded_by_regular_video_upload"
            aparat_status = "pending"
            state_changed = True
            print(f"APARAT_QUEUE_REACTIVATED id={pid} target=regular_video_feed")

        # Revisit records skipped by the previous, stricter 20-minute rule when
        # the same live-deal record still has enough time before channel cleanup.
        if generation_status == "skipped_expiring_soon":
            prior_expiry = _parse_utc_datetime(
                _parse_deal_expiry_value(record.get("expires_at"))
            )
            if (
                prior_expiry is not None
                and record.get("expiry_source") in {"digikala_live_deals_feed", "digikala_product_detail_api", "digikala_mcp_offer_card"}
                and record.get("expiry_estimated") is not True
                and (
                    (record.get("expiry_source") in {"digikala_live_deals_feed", "digikala_product_detail_api"}
                     and record.get("expiry_deadline_verified_directly") is True)
                    or (record.get("expiry_source") == "digikala_mcp_offer_card"
                        and record.get("expiry_deadline_verified_from_site_card") is True)
                )
                and prior_expiry > current + timedelta(minutes=COUNTDOWN_SAFETY_BUFFER_MINUTES)
            ):
                record["video_generation_status"] = "pending"
                generation_status = "pending"
                if upload_status == "skipped_expiring_soon":
                    record["youtube_upload_status"] = "pending"
                    upload_status = "pending"
                if aparat_status == "skipped_expiring_soon":
                    record["aparat_upload_status"] = "pending"
                    aparat_status = "pending"
                state_changed = True
                print(f"SHORT_VIDEO_REQUEUED id={pid} reason=active_deadline_after_policy_change")

        youtube_in_flight = False
        aparat_in_flight = False

        if upload_status == "uploading":
            started = _parse_utc_datetime(record.get("youtube_upload_started_at"))
            if started and (current - started).total_seconds() > 1800:
                record["youtube_upload_status"] = "upload_result_unknown"
                record["youtube_review_required"] = True
                record["youtube_last_error"] = "runner_interrupted_during_upload"
                upload_status = "upload_result_unknown"
                state_changed = True
            else:
                youtube_in_flight = True

        if aparat_status == "uploading":
            started = _parse_utc_datetime(record.get("aparat_upload_started_at"))
            if started and (current - started).total_seconds() > 1800:
                record["aparat_upload_status"] = "upload_result_unknown"
                record["aparat_review_required"] = True
                record["aparat_last_error"] = "runner_interrupted_during_upload"
                aparat_status = "upload_result_unknown"
                state_changed = True
            else:
                aparat_in_flight = True

        if generation_status not in {"pending", "generated"}:
            continue

        expiry = _parse_utc_datetime(_parse_deal_expiry_value(record.get("expires_at")))
        if not force_due and (
            expiry is None
            or record.get("expiry_source") not in {"digikala_live_deals_feed", "digikala_product_detail_api", "digikala_mcp_offer_card", "snappshop_recheck_window"}
            or record.get("expiry_estimated") is True
            or (
                record.get("expiry_source") in {"digikala_live_deals_feed", "digikala_product_detail_api"}
                and record.get("expiry_deadline_verified_directly") is not True
            )
            or (
                record.get("expiry_source") == "digikala_mcp_offer_card"
                and record.get("expiry_deadline_verified_from_site_card") is not True
            )
        ):
            record["video_generation_status"] = "skipped_unverified_deadline"
            if upload_status in pending_youtube:
                record["youtube_upload_status"] = "skipped_unverified_deadline"
            if aparat_status in PENDING_APARAT_STATUSES:
                record["aparat_upload_status"] = "skipped_unverified_deadline"
            state_changed = True
            print(f"SHORT_VIDEO_SKIP id={pid} reason=unverified_deadline")
            continue
        if expiry is None and force_due:
            # The publisher has just revalidated current price and stock. The
            # hourly audit is the expiry safety net for products without a site timer.
            expiry = current + timedelta(days=3650)
        # Use the same ten-minute removal buffer as the channel posts. Do not
        # impose a separate 20-minute video eligibility rule on an already-published deal.
        if expiry <= current + timedelta(minutes=COUNTDOWN_SAFETY_BUFFER_MINUTES):
            record["video_generation_status"] = "skipped_expiring_soon"
            if upload_status in pending_youtube:
                record["youtube_upload_status"] = "skipped_expiring_soon"
            if aparat_status in PENDING_APARAT_STATUSES:
                record["aparat_upload_status"] = "skipped_expiring_soon"
            state_changed = True
            print(f"SHORT_VIDEO_SKIP id={pid} reason=inside_expiry_removal_buffer")
            continue

        delivery = record.get("delivery_status") if isinstance(record.get("delivery_status"), dict) else {}
        if not force_due and not any(value == "sent" for value in delivery.values()):
            continue

        yt_need = (
            youtube_upload_due and upload_status in pending_youtube
            and not youtube_in_flight
        )
        aparat_pending = aparat_ready and aparat_status in PENDING_APARAT_STATUSES and not aparat_in_flight
        aparat_need = aparat_pending and (APARAT_SHORTS_ONLY or aparat_upload_due)
        public_aparat_need = aparat_need and not APARAT_SHORTS_ONLY
        shorts_queue_need = aparat_pending and APARAT_SHORTS_ONLY
        manual_artifact_need = (
            not youtube_ready and upload_status in pending_youtube
            and generation_status == "pending"
        )
        review_next = _parse_utc_datetime(record.get("video_review_next_attempt_at"))
        review_need = review_ready and not record.get("video_review_sent") and not (
            review_next and current < review_next
        )
        if youtube_pause_active and not (public_aparat_need or shorts_queue_need or review_need):
            # A YouTube daily limit suppresses only YouTube uploads; public Aparat uploads,
            # the separately queued Aparat Shorts path, and an explicitly configured private
            # review destination remain eligible.
            continue
        if not (yt_need or public_aparat_need or shorts_queue_need or review_need or manual_artifact_need):
            # Don't render/select public YouTube content before its next scheduled slot.
            continue
        if generation_status == "generated" and not (yt_need or public_aparat_need or shorts_queue_need or review_need or manual_artifact_need):
            # A previously generated MP4 has no configured destination needing work.
            continue

        retry_values = []
        for key, needed in (
            ("youtube_next_attempt_at", yt_need),
            ("aparat_next_attempt_at", aparat_need),
            ("video_generation_next_attempt_at", generation_status == "pending"),
        ):
            value = record.get(key)
            retry_at = _parse_utc_datetime(value) if value else None
            if needed and retry_at:
                retry_values.append(retry_at)
        if retry_values and current < max(retry_values):
            continue

        if not str(record.get("image_url") or "").strip():
            record["video_generation_status"] = "pending"
            record["video_generation_last_error"] = "missing_image_url"
            record["video_generation_next_attempt_at"] = (current + timedelta(minutes=30)).isoformat()
            state_changed = True
            continue
        candidates.append((float(record.get("ts") or 0), str(pid), record, expiry))

    if state_changed:
        save_json(STATE, state)
    if not candidates:
        return False

    candidates.sort(
        key=lambda row: (
            0 if row[2].get("video_repair_priority") else 1,
            -_candidate_demand_score(row[2]),
            -_candidate_promo_score(row[2]),
            -(_int_value(row[2].get("click_count_30d")) or 0),
            row[3],  # among similarly attractive deals, upload the one expiring sooner first
            row[0],
        )
    )
    _, pid, record, expiry = candidates[0]
    output_folder = Path(output_dir)
    output_folder.mkdir(parents=True, exist_ok=True)
    output_path = output_folder / f"offerchin-{pid}.mp4"

    try:
        image_bytes = _fetch_image(str(record["image_url"]))
        render_short_video(
            image_bytes,
            record.get("posted_discount_percent"),
            output_path,
            title=str(record.get("title") or "پیشنهاد ویژه دیجی‌کالا"),
            current_price=record.get("posted_current_price"),
            original_price=record.get("posted_original_price"),
            merchant="اسنپ‌شاپ" if product_id(record.get("product_url", "")).startswith("snp-") else "دیجی‌کالا",
        )
        record["video_generation_status"] = "generated"
        record["video_style_version"] = VIDEO_STYLE_VERSION
        record["video_generated_at"] = current.isoformat()
        record["video_file_name"] = output_path.name
        record.pop("video_generation_next_attempt_at", None)
        record.pop("video_generation_last_error", None)
        print(
            f"SHORT_VIDEO_GENERATED id={pid} file={output_path.name} "
            f"youtube_credentials={youtube_ready} aparat_credentials={aparat_ready} "
            f"telegram_review={review_ready} expiry={expiry.isoformat()}"
        )
        save_json(STATE, state)
    except Exception as exc:
        try:
            attempts = int(record.get("video_generation_attempts", 0) or 0) + 1
        except (TypeError, ValueError, OverflowError):
            attempts = 1
        record["video_generation_attempts"] = attempts
        record["video_generation_status"] = "pending"
        record["video_generation_last_error"] = f"{type(exc).__name__}: {str(exc)[:260]}"
        record["video_generation_next_attempt_at"] = (
            current + timedelta(seconds=min(3600, 300 * (2 ** min(attempts - 1, 4))))
        ).isoformat()
        save_json(STATE, state)
        print(f"SHORT_VIDEO_GENERATION_FAILED id={pid} error={type(exc).__name__} detail={str(exc)[:260]!r}")
        return True

    # Optional private preview goes to a user-configured chat, never to the public channel.
    if review_ready and not record.get("video_review_sent"):
        try:
            preview = send_telegram_video_review(
                output_path,
                str(record.get("title") or "پیشنهاد آفِرچین"),
                record.get("posted_discount_percent"),
            )
            record["video_review_sent"] = True
            record["video_review_message_id"] = preview.get("message_id")
            record["video_review_sent_at"] = datetime.now(timezone.utc).isoformat()
            record.pop("video_review_last_error", None)
            record.pop("video_review_next_attempt_at", None)
            print(f"TELEGRAM_VIDEO_REVIEW_SENT id={pid} message_id={preview.get('message_id')}")
        except Exception as exc:
            record["video_review_last_error"] = type(exc).__name__
            record["video_review_next_attempt_at"] = (
                datetime.now(timezone.utc) + timedelta(minutes=30)
            ).isoformat()
            print(f"TELEGRAM_VIDEO_REVIEW_FAILED id={pid} error={type(exc).__name__}")
        save_json(STATE, state)

    # Aparat public uploads use their own slot and status fields; all errors are caught
    # locally so they cannot interrupt the YouTube publication attempt below.
    aparat_status = str(record.get("aparat_upload_status") or "pending_credentials")
    if aparat_ready and aparat_upload_due and aparat_status in PENDING_APARAT_STATUSES and not APARAT_SHORTS_ONLY:
        aparat_started_at = datetime.now(timezone.utc)
        record["aparat_upload_status"] = "uploading"
        record["aparat_upload_started_at"] = aparat_started_at.isoformat()
        state["aparat_last_upload_attempt_at"] = aparat_started_at.isoformat()
        # Reserve the next slot before uploading so failures cannot cause a five-minute burst.
        state["aparat_next_upload_at"] = (
            aparat_started_at + timedelta(hours=APARAT_UPLOAD_INTERVAL_HOURS)
        ).isoformat()
        save_json(STATE, state)
        try:
            aparat_result = upload_aparat_video(
                output_path,
                str(record.get("title") or "پیشنهاد آفِرچین"),
                description=build_video_channel_description(state, "aparat", record=record),
            )
            record["aparat_upload_status"] = "uploaded"
            record["aparat_video_record_id"] = aparat_result.get("video_id", "")
            record["aparat_video_hash"] = aparat_result.get("video_hash", "")
            record["aparat_video_url"] = aparat_result.get("url", "")
            record["aparat_visibility"] = aparat_result.get("visibility", "unknown")
            if aparat_result.get("lookup_error"):
                record["aparat_video_lookup_last_error"] = aparat_result["lookup_error"]
            aparat_uploaded_at = datetime.now(timezone.utc)
            record["aparat_uploaded_at"] = aparat_uploaded_at.isoformat()
            state["aparat_last_upload_success_at"] = aparat_uploaded_at.isoformat()
            state["aparat_next_upload_at"] = (
                aparat_uploaded_at + timedelta(hours=APARAT_UPLOAD_INTERVAL_HOURS)
            ).isoformat()
            state.pop("aparat_last_upload_outcome_unknown_at", None)
            record.pop("aparat_next_attempt_at", None)
            record.pop("aparat_last_error", None)
            print(
                f"APARAT_UPLOAD_OK id={pid} visibility={record['aparat_visibility']} "
                f"url={record['aparat_video_url'] or 'pending_hash'}"
            )
        except Exception as exc:
            aparat_failure_at = datetime.now(timezone.utc)
            state["aparat_next_upload_at"] = (
                aparat_failure_at + timedelta(hours=APARAT_UPLOAD_INTERVAL_HOURS)
            ).isoformat()
            if isinstance(exc, (requests.exceptions.Timeout, requests.exceptions.ConnectionError)):
                record["aparat_upload_status"] = "upload_result_unknown"
                record["aparat_review_required"] = True
                record["aparat_last_error"] = type(exc).__name__
                state["aparat_last_upload_outcome_unknown_at"] = aparat_failure_at.isoformat()
                print(f"APARAT_UPLOAD_RESULT_UNKNOWN id={pid} error={type(exc).__name__}; no automatic duplicate retry")
            else:
                try:
                    attempts = int(record.get("aparat_upload_attempts", 0) or 0) + 1
                except (TypeError, ValueError, OverflowError):
                    attempts = 1
                record["aparat_upload_attempts"] = attempts
                record["aparat_upload_status"] = "retry"
                record["aparat_last_error"] = type(exc).__name__
                record["aparat_next_attempt_at"] = (
                    datetime.now(timezone.utc)
                    + timedelta(seconds=min(3600, 300 * (2 ** min(attempts - 1, 4))))
                ).isoformat()
                status_code = getattr(getattr(exc, "response", None), "status_code", None)
                print(f"APARAT_UPLOAD_FAILED id={pid} error={type(exc).__name__} http_status={status_code or 'unknown'} retry_attempt={attempts}")
        save_json(STATE, state)
    elif aparat_status in PENDING_APARAT_STATUSES and APARAT_SHORTS_ONLY:
        # Never send a vertical MP4 to the generic website uploader and assume it becomes
        # a Short. Preserve a clear queue state until a verified Shorts-capable path exists.
        record["aparat_upload_status"] = "waiting_shorts_uploader"
        record["aparat_shorts_upload_status"] = "queued"
        record["aparat_shorts_queue_reason"] = "generic_web_upload_does_not_guarantee_shorts_placement"
        record.setdefault("aparat_shorts_queued_at", datetime.now(timezone.utc).isoformat())
        record.pop("aparat_next_attempt_at", None)
        record.pop("aparat_last_error", None)
        print(f"APARAT_SHORTS_QUEUED id={pid} format=9:16 generic_public_upload=disabled")
        save_json(STATE, state)

    # Existing official YouTube upload stays independent from Aparat.
    upload_status = str(record.get("youtube_upload_status") or "pending_credentials")
    if youtube_upload_due and upload_status in pending_youtube:
        record["youtube_upload_status"] = "uploading"
        record["youtube_upload_started_at"] = datetime.now(timezone.utc).isoformat()
        save_json(STATE, state)
        try:
            result = upload_youtube_video(
                output_path,
                str(record.get("title") or "پیشنهاد آفِرچین"),
                record.get("posted_discount_percent"),
                description=build_video_channel_description(state, "youtube", record=record),
            )
            record["youtube_upload_status"] = "uploaded"
            record["youtube_video_id"] = result["video_id"]
            record["youtube_video_url"] = result["url"]
            uploaded_at = datetime.now(timezone.utc)
            record["youtube_uploaded_at"] = uploaded_at.isoformat()
            state["youtube_last_upload_success_at"] = uploaded_at.isoformat()
            state["youtube_next_upload_at"] = (
                uploaded_at + timedelta(hours=YOUTUBE_UPLOAD_INTERVAL_HOURS)
            ).isoformat()
            record["youtube_description_version"] = YOUTUBE_DESCRIPTION_VERSION
            record["youtube_video_renderer_version"] = PERSIAN_TEXT_RENDERER_VERSION
            record["youtube_visual_repair_completed_at"] = datetime.now(timezone.utc).isoformat() if record.get("youtube_previous_video_id") else record.get("youtube_visual_repair_completed_at", "")
            record["youtube_review_required"] = False
            record.pop("youtube_next_attempt_at", None)
            record.pop("youtube_last_error", None)
            print(f"YOUTUBE_UPLOAD_OK id={pid} video_id={result['video_id']} url={result['url']}")
            _delete_superseded_youtube_video(
                record, pid, delete_youtube_video, datetime.now(timezone.utc)
            )
        except Exception as exc:
            if isinstance(exc, (requests.exceptions.Timeout, requests.exceptions.ConnectionError)):
                record["youtube_upload_status"] = "upload_result_unknown"
                record["youtube_review_required"] = True
                record["youtube_last_error"] = type(exc).__name__
                unknown_at = datetime.now(timezone.utc)
                state["youtube_last_upload_outcome_unknown_at"] = unknown_at.isoformat()
                state["youtube_next_upload_at"] = (
                    unknown_at + timedelta(hours=YOUTUBE_UPLOAD_INTERVAL_HOURS)
                ).isoformat()
                print(
                    f"YOUTUBE_UPLOAD_RESULT_UNKNOWN id={pid} error={type(exc).__name__}; "
                    f"next slot reserved at {state['youtube_next_upload_at']}; no automatic duplicate retry"
                )
            else:
                try:
                    attempts = int(record.get("youtube_upload_attempts", 0) or 0) + 1
                except (TypeError, ValueError, OverflowError):
                    attempts = 1
                record["youtube_upload_attempts"] = attempts
                record["youtube_upload_status"] = "retry"
                error_detail = " ".join(str(exc).split())[:260]
                record["youtube_last_error"] = (
                    f"{type(exc).__name__}: {error_detail}" if error_detail
                    else type(exc).__name__
                )
                error_lower = error_detail.casefold()
                daily_upload_limit = any(marker in error_lower for marker in (
                    "video uploads per day",
                    "uploadlimitexceeded",
                    "daily video upload limit",
                ))
                failure_time = datetime.now(timezone.utc)
                if daily_upload_limit:
                    next_attempt = _next_youtube_daily_upload_retry_at(failure_time)
                    state["youtube_uploads_paused_until"] = next_attempt.isoformat()
                    state["youtube_upload_pause_reason"] = "daily_upload_limit"
                    state["youtube_upload_pause_diagnostic_migrated"] = True
                    youtube_pause_until = next_attempt
                    youtube_pause_active = True
                else:
                    next_attempt = failure_time + timedelta(
                        seconds=min(3600, 300 * (2 ** min(attempts - 1, 4)))
                    )
                record["youtube_next_attempt_at"] = next_attempt.isoformat()
                http_status = getattr(getattr(exc, "response", None), "status_code", None)
                print(
                    f"YOUTUBE_UPLOAD_FAILED id={pid} error={type(exc).__name__} "
                    f"http_status={http_status or 'unknown'} detail={error_detail!r} "
                    f"retry_attempt={attempts} "
                    f"deferred_for_24h={daily_upload_limit} "
                    f"next_attempt_at={next_attempt.isoformat()}"
                )
    elif not youtube_ready and upload_status in pending_youtube:
        record["youtube_upload_status"] = "pending_credentials"
        record["youtube_last_error"] = ""

    save_json(STATE, state)
    return True


GROWTH_TRACKING_INVITE_SOURCES = (
    ("aparat", "OfferChin-Aparat"),
    ("bale", "OfferChin-Bale"),
    ("youtube", "OfferChin-YouTube"),
)


def ensure_telegram_source_invites(state: dict, *, session=None, token=None, chat_id=None, now=None) -> bool:
    """Create one stable, source-named Telegram invite link per growth channel.

    Failures are deliberately non-fatal: publishing offers must continue even when the
    bot lacks invite-management rights or Telegram is temporarily unavailable.
    """
    bot_token = str(BOT_TOKEN if token is None else token).strip()
    target_chat = str(TARGET_CHAT if chat_id is None else chat_id).strip()
    if not bot_token or not target_chat:
        print("GROWTH_INVITE_SETUP_SKIPPED reason=telegram_credentials_missing")
        return False

    tracking = state.setdefault("growth_tracking", {})
    if not isinstance(tracking, dict):
        tracking = {}
        state["growth_tracking"] = tracking
    links = tracking.setdefault("telegram_invite_links", {})
    if not isinstance(links, dict):
        links = {}
        tracking["telegram_invite_links"] = links

    http = session or requests.Session()
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    changed = False

    for source, link_name in GROWTH_TRACKING_INVITE_SOURCES:
        existing = links.get(source)
        existing_url = str(existing.get("url") or "").strip() if isinstance(existing, dict) else ""
        parsed = urlsplit(existing_url)
        if parsed.scheme == "https" and parsed.netloc.lower() in {"t.me", "telegram.me"} and parsed.path:
            print(f"GROWTH_INVITE_READY source={source} origin=saved url={existing_url}")
            continue

        try:
            response = http.post(
                f"https://api.telegram.org/bot{bot_token}/createChatInviteLink",
                data={"chat_id": target_chat, "name": link_name},
                timeout=(10, 20),
            )
            response.raise_for_status()
            payload = response.json()
            if not isinstance(payload, dict) or payload.get("ok") is not True:
                description = str(payload.get("description") or "telegram_api_rejected_request") if isinstance(payload, dict) else "invalid_telegram_response"
                description = re.sub(r"[\r\n\t]+", " ", description)[:140]
                print(f"GROWTH_INVITE_SETUP_FAILED source={source} reason={description!r}")
                continue
            result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
            invite_url = str(result.get("invite_link") or "").strip()
            parsed_invite = urlsplit(invite_url)
            if parsed_invite.scheme != "https" or parsed_invite.netloc.lower() not in {"t.me", "telegram.me"} or not parsed_invite.path:
                print(f"GROWTH_INVITE_SETUP_FAILED source={source} reason=invalid_invite_url")
                continue

            links[source] = {
                "name": link_name,
                "url": invite_url,
                "created_at": current.isoformat(),
                "status": "active",
            }
            changed = True
            print(f"GROWTH_INVITE_READY source={source} origin=created url={invite_url}")
        except Exception as exc:
            # Never print the request URL, since it embeds the private bot token.
            print(f"GROWTH_INVITE_SETUP_FAILED source={source} error={type(exc).__name__}")

    return changed



def record_daily_member_count_snapshot(
    state: dict,
    *,
    session=None,
    now=None,
    telegram_token=None,
    telegram_chat_id=None,
    bale_token=None,
    bale_chat_id=None,
) -> bool:
    """Store the first successful member-count snapshot per Iran calendar day.

    This is best-effort telemetry only. API failures never affect posting or invite setup.
    """
    tg_token = str(BOT_TOKEN if telegram_token is None else telegram_token).strip()
    tg_chat = str(TARGET_CHAT if telegram_chat_id is None else telegram_chat_id).strip()
    bl_token = str(BALE_BOT_TOKEN if bale_token is None else bale_token).strip()
    bl_chat = str(BALE_CHANNEL_ID if bale_chat_id is None else bale_chat_id).strip()
    if not (tg_token and tg_chat) and not (bl_token and bl_chat):
        print("GROWTH_MEMBER_COUNT_SKIPPED reason=channel_credentials_missing")
        return False

    tracking = state.setdefault("growth_tracking", {})
    if not isinstance(tracking, dict):
        tracking = {}
        state["growth_tracking"] = tracking
    daily = tracking.setdefault("daily_member_counts", {})
    if not isinstance(daily, dict):
        daily = {}
        tracking["daily_member_counts"] = daily

    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    current = current.astimezone(timezone.utc)
    day = current.astimezone(IRAN_TIMEZONE).date().isoformat()
    sample = daily.setdefault(day, {})
    if not isinstance(sample, dict):
        sample = {}
        daily[day] = sample

    http = session or requests.Session()
    changed = False
    sources = (
        ("telegram", tg_token, tg_chat, "https://api.telegram.org", ("getChatMemberCount",)),
        # Bale-compatible Bot API deployments may expose the method with or without the
        # legacy plural suffix, so try the standard spelling and a compatible fallback.
        ("bale", bl_token, bl_chat, "https://tapi.bale.ai", ("getChatMemberCount", "getChatMembersCount")),
    )
    for platform, token, chat_id, base_url, methods in sources:
        if platform in sample or not token or not chat_id:
            continue
        last_reason = "no_supported_count_response"
        for method in methods:
            try:
                response = http.post(
                    f"{base_url}/bot{token}/{method}",
                    data={"chat_id": chat_id},
                    timeout=(8, 15),
                )
                response.raise_for_status()
                payload = response.json()
                result = payload.get("result") if isinstance(payload, dict) and payload.get("ok") is True else None
                if isinstance(result, bool):
                    result = None
                count = int(result) if result is not None else None
                if count is None or count < 0:
                    last_reason = str(payload.get("description") or "count_not_available") if isinstance(payload, dict) else "invalid_response"
                    continue
                sample[platform] = {"count": count, "captured_at": current.isoformat()}
                changed = True
                print(f"GROWTH_MEMBER_COUNT_SNAPSHOT platform={platform} count={count} day={day}")
                break
            except Exception as exc:
                last_reason = type(exc).__name__
        if platform not in sample:
            print(f"GROWTH_MEMBER_COUNT_UNAVAILABLE platform={platform} reason={str(last_reason)[:100]!r}")

    # Keep a bounded 90-day record so telemetry cannot make state.json grow indefinitely.
    for old_day in sorted(daily)[:-90]:
        daily.pop(old_day, None)
        changed = True
    return changed



def build_video_channel_description(state: dict, source: str, record: dict | None = None) -> str:
    """Build platform descriptions with the video's product-specific Affilio buying link."""
    source_value = str(source or "").strip().lower()
    lines = [
        "پیشنهادهای کاربردی و تخفیف‌های منتخب دیجی‌کالا و اسنپ‌شاپ را در آفِرچین دنبال کنید.",
    ]
    if source_value != "youtube":
        lines.append("قیمت، موجودی و شرایط تخفیف ممکن است تغییر کند؛ پیش از خرید، اطلاعات روز محصول را در فروشگاه مربوط بررسی کنید.")

    product_url = safe_product_url((record or {}).get("product_url", "")) if isinstance(record, dict) else ""
    if product_url:
        affiliate_url = build_affilio_tracking_link(product_url)
        if _is_valid_affilio_tracking_url(affiliate_url):
            purchase_url = tracked_affiliate_button_url(
                affiliate_url,
                source_value if source_value in {"youtube", "aparat"} else "unknown",
            )
            lines.extend(["", "لینک خرید محصول:", purchase_url])

    if source_value == "youtube":
        lines.extend([
            "",
            "کانال تلگرام:",
            "https://t.me/OfferChin",
            "کانال بله:",
            "https://ble.ir/OfferChin",
            "آپارات:",
            "https://www.aparat.com/OfferChin",
        ])
        return "\n".join(lines)

    tracking = state.get("growth_tracking", {}) if isinstance(state, dict) else {}
    links = tracking.get("telegram_invite_links", {}) if isinstance(tracking, dict) else {}
    link_record = links.get(source_value, {}) if isinstance(links, dict) else {}
    invite_url = str(link_record.get("url") or "").strip() if isinstance(link_record, dict) else ""
    parsed = urlsplit(invite_url)
    if not (parsed.scheme == "https" and parsed.netloc.lower() in {"t.me", "telegram.me"} and parsed.path):
        invite_url = TELEGRAM_CHANNEL_URL
    source_names = {"aparat": "آپارات", "youtube": "یوتیوب"}
    source_label = source_names.get(source_value, "این ویدئو")
    lines.extend([
        "",
        f"برای عضویت در تلگرام از {source_label}:",
        invite_url,
        "کانال بله: https://ble.ir/OfferChin",
    ])
    return "\n".join(lines)

def tracked_telegram_invite_url(state: dict, source: str) -> str:
    """Get a validated saved invite URL for replacing a source link in a pinned message."""
    tracking = state.get("growth_tracking", {}) if isinstance(state, dict) else {}
    links = tracking.get("telegram_invite_links", {}) if isinstance(tracking, dict) else {}
    record = links.get(source, {}) if isinstance(links, dict) else {}
    url = str(record.get("url") or "").strip() if isinstance(record, dict) else ""
    parsed = urlsplit(url)
    if parsed.scheme == "https" and parsed.netloc.lower() in {"t.me", "telegram.me"} and parsed.path:
        return url
    return TELEGRAM_CHANNEL_URL


def run(publish=False, selection_only=False):
    print("Affilio radar: independent from Dayan and TrendsUploader.")
    print(f"delivery_configuration telegram={bool(BOT_TOKEN)} bale={bool(BALE_BOT_TOKEN and BALE_CHANNEL_ID)}")
    print(
        "Ranking mode=top-public-demand-pool then highest live discount; "
        "no minimum discount percentage or minimum saving amount. "
        "Live stock, current price, genuine markdown, image, affiliate link, "
        "expiry safety, market-value and duplicate checks remain active."
    )
    catalog = load_catalog()
    approved = link_map(catalog)
    probe_link = build_affilio_tracking_link("https://www.digikala.com/product/dkp-12345/")
    if probe_link:
        link_mode = "publisher_public_affilio_link"
    elif approved:
        link_mode = "per_product_overrides"
    else:
        link_mode = "no_valid_affilio_tracking_config"
    print(f"affiliate_link_mode={link_mode} manual_product_overrides={len(approved)}")
    # [scan-now] Read the persistent queue before discovery so offers temporarily missing from one
    # page remain eligible for a live recheck on the next scan.
    state = load_state()
    if prune_suppressed_product_queues(state):
        save_json(STATE, state)
    if ensure_publication_ledger(state):
        save_json(STATE, state)
    # Growth attribution/count telemetry is best-effort and must never block regular offer publishing.
    growth_invites_changed = ensure_telegram_source_invites(state)
    growth_counts_changed = record_daily_member_count_snapshot(state)
    if growth_invites_changed or growth_counts_changed:
        save_json(STATE, state)
    state.setdefault("published", {})
    queued_records = state.get("pending_queue")
    discovery_queue = state.get("discovery_queue")
    if not isinstance(discovery_queue, dict):
        discovery_queue = {}
        state["discovery_queue"] = discovery_queue
    urls, search_diagnostics, deal_expiries, direct_feed_expiries, mcp_card_expiries = discover_product_urls(
        queued_records if isinstance(queued_records, dict) else {},
        discovery_queue,
        state,
    )
    prune_suppressed_product_queues(state)
    # Write the discovery queue before per-product page checks; the workflow's final
    # state-commit step also runs on failed validation/check steps so these sightings survive.
    save_json(STATE, state)
    print(
        f"discovered_product_urls={len(urls)} offer_expiries={len(deal_expiries)} "
        f"discovery_queue_size={len(discovery_queue)}"
    )

    products = []
    for url in urls:
        try:
            canonical = safe_product_url(url)
            if not canonical:
                print("PRODUCT_SKIP invalid_product_url")
                continue
            item = fetch_product_record(canonical)
            item["merchant"] = "اسنپ‌شاپ" if product_id(canonical).startswith("snp-") else "دیجی‌کالا"
            pid = item.get("product_id", "")
            mcp_deadline_hint = deal_expiries.get(pid, "")
            direct_feed_deadline = direct_feed_expiries.get(pid, "")
            mcp_card_deadline = mcp_card_expiries.get(pid, "")
            if direct_feed_deadline:
                item["deal_expires_at"] = direct_feed_deadline
                item["expiry_source"] = "digikala_live_deals_feed"
                item["expiry_deadline_verified_directly"] = True
                item["expiry_deadline_verified_from_site_card"] = False
                item["expiry_estimated"] = False
            elif not (
                item.get("expiry_deadline_verified_directly") is True
                and item.get("expiry_source") == "digikala_product_detail_api"
                and item.get("deal_expires_at")
            ) and mcp_card_deadline:
                # DigiKala's direct REST list currently omits the live timer on many
                # cards. Use only the matching product's current live offer-card timer
                # as a tagged fallback; never use an old discovery-queue timestamp.
                item["deal_expires_at"] = mcp_card_deadline
                item["expiry_source"] = "digikala_mcp_offer_card"
                item["expiry_deadline_verified_directly"] = False
                item["expiry_deadline_verified_from_site_card"] = True
                item["expiry_estimated"] = False
            elif product_id(canonical).startswith("snp-"):
                # No source-confirmed timer: keep the offer open-ended and validate
                # current stock, price, and discount instead of inventing a deadline.
                item["deal_expires_at"] = ""
                item["expiry_source"] = "snappshop_no_confirmed_expiry"
                item["expiry_deadline_verified_directly"] = False
                item["expiry_deadline_verified_from_site_card"] = False
                item["expiry_estimated"] = False
                item["expiry_is_recheck_window"] = False
            elif not (
                item.get("expiry_deadline_verified_directly") is True
                and item.get("expiry_source") == "digikala_product_detail_api"
                and item.get("deal_expires_at")
            ):
                item["deal_expires_at"] = ""
                item["expiry_source"] = "unavailable"
                item["expiry_deadline_verified_directly"] = False
                item["expiry_deadline_verified_from_site_card"] = False
                item["expiry_estimated"] = False
                if mcp_deadline_hint:
                    item["mcp_deadline_hint"] = mcp_deadline_hint
            if not is_publishable_product_title(item.get("title")):
                print(f"PRODUCT_SKIP id={item.get('product_id')} reason=invalid_or_incomplete_title")
                continue
            item = score_product(item)
            override = approved.get(item["product_id"], {})
            tracking_link = str(override.get("affiliate_url", "")).strip()
            if not tracking_link:
                tracking_link = build_affilio_tracking_link(item.get("product_url", ""))
            item["affiliate_url"] = tracking_link
            item["has_affiliate_link"] = bool(tracking_link)
            products.append(item)
            print(
                f"PRODUCT id={item['product_id']} stock={item['availability']} "
                f"price={item.get('current_price')} rating={item.get('rating')} reviews={item.get('review_count')} "
                f"score={item['demand_score']} linked={item['has_affiliate_link']} title={item['title']!r}"
            )
        except Exception as exc:
            print(f"PRODUCT_FETCH_FAILED url={url} error={type(exc).__name__}")

    # Repeated retailer observations are required to distinguish recent interest from lifetime popularity.
    update_current_demand_signals(state, products, now=datetime.now(timezone.utc))
    # Do not fetch click-worker statistics: they are not affiliate conversions and
    # new purchase buttons now go directly to Affilio to preserve attribution.
    products.sort(key=deal_sort_key, reverse=True)
    state.setdefault("published", {})
    if publish and CLEAR_PREVIOUS_CHANNEL_POSTS and BATCH_OPERATION_KEY and state.get("completed_batch_operation") == BATCH_OPERATION_KEY:
        print(f"BATCH_ALREADY_COMPLETED key={BATCH_OPERATION_KEY}; duplicate workflow run will not send again.")
        publish = False
    # Historical-price lookup is intentionally not used.
    state.pop("price_history", None)
    enrich_market_prices(products)
    products.sort(key=deal_sort_key, reverse=True)
    queue_now = datetime.now(timezone.utc)
    listed_eligible_count = sum(
        bool(
            p.get("has_affiliate_link")
            and is_discount_publish_eligible(
                p, minimum_discount_percent=MIN_DISCOUNT_FALLBACK_PERCENT, now=queue_now
            )
            and is_market_value_publish_eligible(p)
            and has_publishable_expiry_or_open_offer(p, queue_now)
        )
        for p in products
    )
    deadline_too_close_count = sum(
        has_verified_deal_deadline(p, queue_now)
        and not has_minimum_publication_runway(p, queue_now)
        for p in products
    )
    market_blocked_count = sum(is_market_price_uncompetitive(p) for p in products)
    eligible, selected_discount_floor, quality_eligible = select_discount_fallback_candidates(
        products, state, now=queue_now, include_fallback_bands=selection_only
    )
    observed_product_ids = {
        str(p.get("product_id") or product_id(p.get("product_url", "")))
        for p in products
        if p.get("product_id") or product_id(p.get("product_url", ""))
    }
    pending_queue = refresh_pending_queue(state, eligible, queue_now, observed_product_ids)
    discovery_queue = state.get("discovery_queue")
    if isinstance(discovery_queue, dict):
        checked_products = {
            str(p.get("product_id") or product_id(p.get("product_url", ""))): p
            for p in products
            if p.get("product_id") or product_id(p.get("product_url", ""))
        }
        eligible_ids = {
            str(p.get("product_id") or product_id(p.get("product_url", "")))
            for p in quality_eligible
        }
        for checked_url in urls:
            checked_pid = product_id(checked_url)
            if checked_pid not in discovery_queue:
                continue
            checked = checked_products.get(checked_pid)
            if checked is None:
                mark_discovery_candidate_checked(discovery_queue, checked_pid, "fetch_failed", queue_now)
            elif checked_pid in eligible_ids:
                mark_discovery_candidate_checked(discovery_queue, checked, "eligible", queue_now)
            elif checked.get("availability") != "in_stock":
                mark_discovery_candidate_checked(discovery_queue, checked, "stock_not_confirmed", queue_now)
            elif _parse_utc_datetime(_parse_deal_expiry_value(checked.get("deal_expires_at"))) and (
                not has_verified_deal_deadline(checked, queue_now) or is_offer_expired(checked, queue_now)
            ):
                mark_discovery_candidate_checked(discovery_queue, checked, "deadline_not_publishable", queue_now)
            elif has_verified_deal_deadline(checked, queue_now) and not has_minimum_publication_runway(checked, queue_now):
                mark_discovery_candidate_checked(discovery_queue, checked, "deadline_too_close_for_publication", queue_now)
            elif not checked.get("has_affiliate_link"):
                mark_discovery_candidate_checked(discovery_queue, checked, "affiliate_link_missing", queue_now)
            elif not is_discount_publish_eligible(
                checked, minimum_discount_percent=MIN_DISCOUNT_FALLBACK_PERCENT, now=queue_now
            ):
                mark_discovery_candidate_checked(discovery_queue, checked, "discount_or_content_gate", queue_now)
            elif not is_market_value_publish_eligible(checked):
                mark_discovery_candidate_checked(discovery_queue, checked, "market_price_rejected", queue_now)
            else:
                mark_discovery_candidate_checked(discovery_queue, checked, "selection_tier_deferred", queue_now)
        save_json(STATE, state)
        print(f"DISCOVERY_QUEUE_CHECK_RESULTS updated={len(urls)} retained={len(discovery_queue)}")
    missing_deadline_count = sum(
        not _parse_utc_datetime(_parse_deal_expiry_value(p.get("deal_expires_at")))
        for p in products
    )
    expired_deadline_count = sum(is_offer_expired(p, queue_now) for p in products)
    prohibited_product_count = sum(is_prohibited_product_title(p.get("title", "")) for p in products)
    selected_discount_band = (
        discount_fallback_band_label(
            selected_discount_floor,
            DISCOUNT_FALLBACK_FLOORS[DISCOUNT_FALLBACK_FLOORS.index(selected_discount_floor) - 1]
            if selected_discount_floor in DISCOUNT_FALLBACK_FLOORS
            and DISCOUNT_FALLBACK_FLOORS.index(selected_discount_floor) > 0
            else None,
        )
        if selected_discount_floor is not None else "none"
    )
    print(
        f"ELIGIBILITY_DIAGNOSTICS ranked={len(products)} "
        f"missing_deadline={missing_deadline_count} expired_deadline={expired_deadline_count} "
        f"deadline_too_close_for_publication={deadline_too_close_count} "
        f"medicine_or_supplement={prohibited_product_count} "
        f"quality_eligible_all_bands={listed_eligible_count} "
        f"selected_discount_band={selected_discount_band} "
        f"fresh_selected_candidates={len(eligible)} "
        f"fresh_after_duplicate_cooldown={len(pending_queue)}"
    )
    eligible_by_id = {
        str(p.get("product_id") or product_id(p.get("product_url", ""))): p
        for p in quality_eligible
    }
    # Retain the band metadata before ranking replaces this list with the
    # original quality records. Restore it now so retries and final ranking both
    # enforce the exact per-product floor.
    selection_tier_candidates = list(eligible)
    restored_tiers = restore_selection_discount_tiers(
        list(eligible_by_id.values()), selection_tier_candidates
    )
    if restored_tiers:
        print(f"DISCOUNT_FALLBACK_TIERS_RESTORED count={restored_tiers}")

    # Retry a failed destination for a previously published product before posting another product.
    # This keeps each channel's delivery independent and avoids reposting to the channel that succeeded.
    delivery_retry_handled = False
    delivery_retry_unresolved = False
    if publish:
        now_epoch = time.time()
        for pid, previous in list(state.get("published", {}).items()):
            if not isinstance(previous, dict):
                continue
            failed_platforms = _delivery_retry_platforms(previous)
            if not failed_platforms:
                continue
            try:
                retry_after = float(previous.get("delivery_retry_after", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                retry_after = 0
            if now_epoch < retry_after:
                continue
            fresh_item = eligible_by_id.get(pid)
            if not fresh_item:
                continue
            if not has_publishable_expiry_or_open_offer(fresh_item, datetime.now(timezone.utc)):
                print(f"DELIVERY_RETRY_SKIP id={pid} reason=offer_not_live_or_not_safely_publishable")
                continue
            delivery_retry_handled = True
            try:
                fresh_image = _fetch_image(fresh_item["image_url"])
            except Exception as exc:
                attempts = previous.setdefault("delivery_attempts", {})
                for platform in failed_platforms:
                    attempts[platform] = int(attempts.get(platform, 1) or 1) + 1
                max_attempt = max(int(attempts.get(platform, 1) or 1) for platform in failed_platforms)
                previous["delivery_retry_after"] = now_epoch + _delivery_retry_delay(max_attempt)
                previous["delivery_last_error"] = type(exc).__name__
                save_json(STATE, state)
                delivery_retry_unresolved = True
                print(f"DELIVERY_RETRY_FAILED id={pid} reason=image_fetch error={type(exc).__name__}")
                break

            statuses = previous.setdefault("delivery_status", {})
            attempts = previous.setdefault("delivery_attempts", {})
            last_error = ""
            for platform in failed_platforms:
                attempts[platform] = int(attempts.get(platform, 1) or 1) + 1
                try:
                    result = _send_platform_photo(platform, fresh_item, fresh_image, fresh_item["affiliate_url"])
                    statuses[platform] = "sent"
                    if platform == "telegram":
                        previous["telegram_message_id"] = result.get("message_id")
                    else:
                        previous["bale_message_id"] = result.get("message_id")
                    print(f"DELIVERY_RETRY_OK id={pid} platform={platform}")
                except Exception as exc:
                    statuses[platform] = "failed"
                    last_error = type(exc).__name__
                    print(f"DELIVERY_RETRY_FAILED id={pid} platform={platform} error={type(exc).__name__}")
            remaining = _delivery_retry_platforms(previous)
            if remaining:
                delivery_retry_unresolved = True
                max_attempt = max(int(attempts.get(platform, 1) or 1) for platform in remaining)
                previous["delivery_retry_after"] = time.time() + _delivery_retry_delay(max_attempt)
                if last_error:
                    previous["delivery_last_error"] = last_error
            else:
                previous.pop("delivery_retry_after", None)
                previous.pop("delivery_last_error", None)
            previous["delivery_last_attempt_at"] = datetime.now(timezone.utc).isoformat()
            save_json(STATE, state)
            print(
                f"DELIVERY_RETRY_SUMMARY id={pid} "
                f"telegram={statuses.get('telegram', 'not_attempted')} "
                f"bale={statuses.get('bale', 'not_attempted')} remaining={','.join(remaining) or 'none'}"
            )
            break

    eligible = select_publish_candidates(
        pending_queue, eligible_by_id, queue_now, state.get("published"),
        state.get("recent_publications"),
    )
    record_publication_diversity_report(state, now=queue_now)
    save_json(STATE, state)
    market_verified = sum(p.get("market_status") == "verified" for p in products)
    print(
        f"ranked_products={len(products)} listed_discount_eligible={listed_eligible_count} "
        f"current_demand_verified={sum(has_current_demand_signal(p, queue_now) for p in products)} "
        f"market_verified={market_verified} market_price_rejected={market_blocked_count} "
        f"publish_eligible={len(eligible)}"
    )
    for rank, item in enumerate(products[:12], start=1):
        print(
            f"RANK {rank}: discount={item['discount_percent']}% saving={item['savings_toman']} "
            f"promo_score={item['promo_score']} demand_score={item['demand_score']} "
            f"clicks_30d={item.get('click_count_30d', 0)} "
            f"stock={item['availability']} linked={item['has_affiliate_link']} "
            f"market={item.get('market_status')} market_price={item.get('market_reference_price_toman')} "
            f"market_advantage={item.get('market_price_advantage_pct')}% "
            f"market_blocked={is_market_price_uncompetitive(item)} "
            f"price={item.get('current_price')} title={item['title']!r} url={item['product_url']}"
        )

    report = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "ranking_note": "Builds a popularity-ranked pool from public retailer review counts and ratings (a demand proxy, not sales volume), checks up to 100 candidates, then selects the largest verified live discount. No minimum discount percentage or saving amount is imposed. Publication still requires verified current price and stock, a genuine markdown, image, affiliate link, a valid title, no prohibited category, no verified market-price rejection, and no duplicate conflict. Confirmed deadlines require the configured publication runway; open-ended offers remain eligible after live stock/current-price validation.",
        "current_demand_policy": {
            "source": "rolling retailer review/rating-count observations",
            "window_days": CURRENT_DEMAND_WINDOW_DAYS,
            "minimum_growth": CURRENT_DEMAND_MIN_REVIEW_GROWTH,
            "minimum_observation_hours": CURRENT_DEMAND_MIN_OBSERVATION_HOURS,
            "sample_interval_hours": CURRENT_DEMAND_SAMPLE_INTERVAL_HOURS,
            "maximum_signal_age_hours": CURRENT_DEMAND_MAX_SIGNAL_AGE_HOURS,
            "unverified_blocks_publication": False,
            "sales_volume_claimed": False,
        },
        "price_market_policy": {
            "source": "Torob public price comparison via Torob MCP",
            "unavailable_market_data_blocks_publication": False,
            "checked_candidates_per_run": MARKET_PRICE_CHECK_LIMIT,
            "minimum_name_match_score": MIN_MARKET_MATCH_SCORE,
            "minimum_sellers_for_verified_median": 3,
            "minimum_discount_vs_current_market_median_percent": 5,
            "unknown_or_limited_comparison_blocks": False,
            "endpoint": TOROB_MCP_URL,
        },
        "search_diagnostics": search_diagnostics,
        "products": products[:40],
    }
    save_json(REPORT, report)
    if selection_only:
        # Keep discovery live on every scan, but only select a new product when a
        # publication slot is due. Never build a long queue of products chosen early.
        from content_delivery import (
            enqueue_selected_content,
            get_last_channel_published_at,
            has_fresh_unpublished_selection,
            refresh_unpublished_selections,
            selection_cadence_anchor,
        )
        selection_now = datetime.now(timezone.utc)
        replaced = refresh_unpublished_selections(
            state, now=selection_now, stale_after_minutes=8
        )
        interval_seconds = max(60, int(MIN_POST_INTERVAL_HOURS * 3600))

        # Cadence follows the last selection and an actual Telegram/Bale send.
        # Retries to YouTube/Aparat cannot move the public-channel slot forward.
        # The helper also recovers older state from immutable per-platform send times.
        last_selected = _parse_utc_datetime(state.get("last_content_selection_at"))
        last_channel_published = get_last_channel_published_at(state)
        fresh_unpublished_selection = has_fresh_unpublished_selection(
            state, now=selection_now, stale_after_minutes=8
        )
        last_slot_anchor = selection_cadence_anchor(
            last_selected,
            last_channel_published,
            has_fresh_unpublished_selection=fresh_unpublished_selection,
        )
        elapsed = (
            (selection_now - last_slot_anchor).total_seconds()
            if last_slot_anchor is not None else interval_seconds
        )
        remaining = max(0, interval_seconds - int(elapsed))

        # A daily cap or an unexpired cooldown is a normal no-op, not a failed scan.
        if remaining > 0:
            save_json(STATE, state)
            print(
                "CONTENT_SELECTION_SLOT_NOT_DUE "
                f"seconds_remaining={remaining} live_candidates={len(eligible)} "
                f"replaced_stale={replaced}"
            )
            return 0
        if daily_channel_posts_count(state, selection_now) >= MAX_DAILY_CHANNEL_POSTS:
            save_json(STATE, state)
            print(
                "CONTENT_SELECTION_DAILY_CAP_REACHED "
                f"limit={MAX_DAILY_CHANNEL_POSTS} live_candidates={len(eligible)}"
            )
            return 0

        # Store one due primary plus a compact ranked backup pool.
        # Every backup has already passed the same hard discount and current-demand
        # gates; backups are never used to relax quality when the primary goes stale.
        primary = eligible[:1]
        summary = enqueue_selected_content(
            state,
            primary,
            now=selection_now,
            interval_seconds=interval_seconds,
            max_items=1,
            minimum_runway_minutes=MIN_PUBLICATION_RUNWAY_MINUTES,
        )
        fallback_count = 0
        if summary["added"] and primary:
            primary_id = str(primary[0].get("product_id") or product_id(primary[0].get("product_url") or ""))
            primary_entry = state.get("content_delivery_queue", {}).get(primary_id)
            if isinstance(primary_entry, dict):
                primary_entry["fallback_candidates"] = [
                    dict(candidate) for candidate in eligible[1:6]
                    if isinstance(candidate, dict)
                ]
                fallback_count = len(primary_entry["fallback_candidates"])
            state["last_content_selection_at"] = selection_now.isoformat()
        save_json(STATE, state)
        print(
            "CONTENT_SELECTION_HANDOFF "
            f"queued={summary['added']} skipped={summary['skipped']} "
            f"queue_size={summary['queue_size']} live_candidates={len(eligible)} "
            f"fallback_pool={fallback_count} replaced_stale={replaced} publisher_invoked=false"
        )
        # No eligible offer is a normal outcome. The next scan refreshes the pool.
        return 0

    state.setdefault("published", {})
    state.setdefault("last_published_at", "")
    now = time.time()
    last_post = _last_post_timestamp(state)
    cooldown_remaining = -1 if FORCE_POST_COOLDOWN_BYPASS else MIN_POST_INTERVAL_HOURS * 3600 - (now - last_post)
    now_utc = datetime.fromtimestamp(now, tz=timezone.utc)
    local_now = now_utc.astimezone(IRAN_TIMEZONE)
    posting_window = preferred_publication_window(now_utc)
    # A fixed "quiet hours" block can make a short-lived offer expire before the next
    # audience window. The queue/cooldown—not the wall clock—now controls publishing.
    regular_window_open = True
    print(
        f"POSTING_WINDOW iran_time={local_now.strftime('%H:%M')} "
        f"preferred_window={posting_window} posting_allowed={regular_window_open}"
    )
    urgent_candidate = select_urgent_publication_candidate(
        eligible,
        now=now_utc,
        published=state.get("published"),
        recent_publications=state.get("recent_publications"),
    )
    urgent_minimum_spacing = URGENT_MIN_POST_INTERVAL_MINUTES
    if urgent_candidate:
        urgent_expiry = _parse_utc_datetime(_parse_deal_expiry_value(urgent_candidate.get("deal_expires_at")))
        if urgent_expiry and 0 < (urgent_expiry - now_utc).total_seconds() <= ULTRA_URGENT_WINDOW_MINUTES * 60:
            urgent_minimum_spacing = ULTRA_URGENT_MIN_POST_INTERVAL_MINUTES
    urgent_override_allowed = bool(
        urgent_candidate
        and now - last_post >= urgent_minimum_spacing * 60
    )
    urgent_cooldown_bypass = bool(
        cooldown_remaining > 0
        and urgent_override_allowed
        and not FORCE_POST_COOLDOWN_BYPASS
    )
    if cooldown_remaining > 0:
        print(f"POST_COOLDOWN remaining_minutes={int(cooldown_remaining / 60)}")
    if cooldown_remaining > 0 and urgent_cooldown_bypass:
        expiry_utc = _parse_utc_datetime(_parse_deal_expiry_value(urgent_candidate.get("deal_expires_at")))
        deadline_minutes = int((expiry_utc - now_utc).total_seconds() / 60) if expiry_utc else -1
        print(
            f"URGENT_PRIORITY_COOLDOWN_BYPASS id={urgent_candidate.get('product_id')} "
            f"deadline_minutes={deadline_minutes} minimum_spacing_minutes={urgent_minimum_spacing}"
        )
    elif cooldown_remaining > 0 and urgent_candidate and not urgent_override_allowed:
        print(f"URGENT_PRIORITY_WAIT minimum_spacing_minutes={urgent_minimum_spacing}")
    if not regular_window_open and urgent_override_allowed:
        expiry_utc = _parse_utc_datetime(_parse_deal_expiry_value(urgent_candidate.get("deal_expires_at")))
        deadline_minutes = int((expiry_utc - now_utc).total_seconds() / 60) if expiry_utc else -1
        print(
            f"QUIET_HOURS_URGENT_OVERRIDE id={urgent_candidate.get('product_id')} "
            f"deadline_minutes={deadline_minutes}"
        )

    if publish and CLEAR_PREVIOUS_CHANNEL_POSTS:
        if not BATCH_OPERATION_KEY or state.get("cleanup_batch_operation") != BATCH_OPERATION_KEY:
            delete_previous_channel_posts(state)
            state["cleanup_batch_operation"] = BATCH_OPERATION_KEY or datetime.now(timezone.utc).isoformat()
            save_json(STATE, state)
        else:
            print(f"BATCH_CLEANUP_ALREADY_DONE key={BATCH_OPERATION_KEY}")
        # Re-evaluate candidates after clearing messages tracked by this bot.
        eligible = [p for p in eligible if p["product_id"] not in state.get("published", {})]

    if not publish:
        print("DRY_RUN: discovery and stock checks only; no Telegram post attempted.")
    elif not BOT_TOKEN and not (BALE_BOT_TOKEN and BALE_CHANNEL_ID):
        print("PUBLISH_BLOCKED: neither complete Telegram nor Bale credentials are configured; no post attempted.")
    elif link_mode == "no_valid_affilio_tracking_config":
        print("PUBLISH_BLOCKED: no valid Affilio tracking parameters/template configured; no post attempted.")
    elif not eligible:
        print(
            "PUBLISH_BLOCKED: no fresh candidate has a genuine price reduction plus confirmed stock, "
            "current price/image, affiliate link, market-value and duplicate/expiry checks. "
            "Open-ended offers are accepted only after live stock/current-price validation."
        )
    elif not regular_window_open and not urgent_override_allowed and not FORCE_POST_COOLDOWN_BYPASS:
        print("PUBLISH_BLOCKED: quiet hours in Iran; regular offer retained for the next audience window.")
    elif cooldown_remaining > 0 and not urgent_cooldown_bypass:
        print("PUBLISH_BLOCKED: global posting cooldown active; queue retained.")
    else:
        sent = 0
        attempted_candidates = 0
        backlog_count = len(pending_queue) if isinstance(pending_queue, dict) else 0
        daily_posts_used = daily_channel_posts_count(state, datetime.now(timezone.utc))
        daily_posts_remaining = max(0, MAX_DAILY_CHANNEL_POSTS - daily_posts_used)
        run_post_limit = min(
            effective_posts_per_run(
                backlog_count,
                configured_limit=MAX_POSTS_PER_RUN,
                force_full_batch=FORCE_POST_COOLDOWN_BYPASS,
            ),
            daily_posts_remaining,
        )
        print(
            f"CHANNEL_DAILY_CAP iran_day_posts={daily_posts_used} "
            f"cap={MAX_DAILY_CHANNEL_POSTS} remaining={daily_posts_remaining} "
            "reason=independent_channel_volume_guard"
        )
        if daily_posts_remaining <= 0:
            print("PUBLISH_BLOCKED: Iran-day channel publication cap reached; YouTube quota is independent.")
        print(
            f"PUBLICATION_CAPACITY backlog={backlog_count} configured_limit={MAX_POSTS_PER_RUN} "
            f"effective_limit={run_post_limit} burst_threshold={PUBLISH_BACKLOG_BURST_THRESHOLD}"
        )
        for item in eligible:
            if sent >= run_post_limit:
                break
            if attempted_candidates >= MAX_PUBLISH_CANDIDATE_ATTEMPTS:
                print(
                    f"PUBLISH_FALLBACK_LIMIT attempts={attempted_candidates} "
                    f"limit={MAX_PUBLISH_CANDIDATE_ATTEMPTS}; remaining candidates stay queued."
                )
                break
            pid = item["product_id"]
            if is_product_suppressed(state, pid):
                print(f"PUBLISH_SKIP id={pid} reason=user_requested_product_suppression")
                state.get("pending_queue", {}).pop(pid, None)
                continue
            publish_guard_time = datetime.now(timezone.utc)
            if not has_publishable_expiry_or_open_offer(item, publish_guard_time):
                expiry = _parse_utc_datetime(_parse_deal_expiry_value(item.get("deal_expires_at")))
                remaining_minutes = int((expiry - publish_guard_time).total_seconds() / 60) if expiry else -1
                reason = "minimum_publication_runway" if expiry else "open_offer_not_verified"
                print(f"PUBLISH_SKIP id={pid} reason={reason} remaining_minutes={remaining_minutes}")
                state.get("pending_queue", {}).pop(pid, None)
                save_json(STATE, state)
                continue
            old = state["published"].get(pid, {})
            cooldown_record = _publication_cooldown_record(state, pid)
            if is_manual_publication_quarantine_active(old or cooldown_record, now_utc):
                print(f"PUBLISH_SKIP id={pid} reason=manual_safety_quarantine")
                continue
            if old and not previous_publication_posts_removed(old):
                print(
                    f"PUBLISH_SKIP id={pid} "
                    "reason=previous_channel_post_not_confirmed_removed"
                )
                continue
            if is_product_repeat_blocked(cooldown_record, item, now_utc):
                print(
                    f"PUBLISH_SKIP id={pid} reason=product_repeat_cooldown "
                    f"minimum_repeat_interval_hours={MIN_REPEAT_PRODUCT_INTERVAL_HOURS}"
                )
                continue
            attempted_candidates += 1
            try:
                image_bytes = _fetch_image(item["image_url"])
            except Exception as exc:
                print(f"PUBLISH_FAILED id={pid} reason=image_fetch error={type(exc).__name__}")
                defer_pending_publication(state, pid, f"image_fetch_{type(exc).__name__}", datetime.now(timezone.utc))
                save_json(STATE, state)
                continue

            # Independently re-read the public product page before sending this offer.
            # Never publish if the page price no longer matches the listing/API record.
            price_check = verify_live_page_price(item)
            if not price_check.get("ok"):
                print(
                    f"PUBLISH_SKIP id={pid} reason={price_check.get('reason')} "
                    f"api_price={price_check.get('api_price', item.get('current_price'))} "
                    f"page_price={price_check.get('page_price')}"
                )
                defer_pending_publication(
                    state, pid, str(price_check.get("reason") or "live_page_price_unverified"),
                    datetime.now(timezone.utc),
                )
                save_json(STATE, state)
                continue

            # Check again after image download, immediately before sending to either channel:
            # a candidate may cross the minimum runway while the rest of the pipeline is running.
            publish_check_time = datetime.now(timezone.utc)
            if not has_publishable_expiry_or_open_offer(item, publish_check_time):
                expiry = _parse_utc_datetime(_parse_deal_expiry_value(item.get("deal_expires_at")))
                remaining_minutes = int((expiry - publish_check_time).total_seconds() / 60) if expiry else -1
                print(
                    f"PUBLISH_SKIP id={pid} reason=minimum_publication_runway "
                    f"remaining_minutes={remaining_minutes} required_minutes={MIN_PUBLICATION_RUNWAY_MINUTES}"
                )
                pending_state = state.get("pending_queue")
                if isinstance(pending_state, dict):
                    pending_state.pop(pid, None)
                save_json(STATE, state)
                continue

            # Attempt both destinations independently. A failure on one platform must not undo
            # or duplicate a successful publication on the other.
            button_url = item["affiliate_url"]
            statuses = {"telegram": "failed", "bale": "failed"}
            attempts = {"telegram": 0, "bale": 0}
            results = {}
            if BOT_TOKEN:
                attempts["telegram"] = 1
                try:
                    results["telegram"] = _send_platform_photo("telegram", item, image_bytes, button_url)
                    statuses["telegram"] = "sent"
                except Exception as exc:
                    print(f"PUBLISH_PLATFORM_FAILED id={pid} platform=telegram error={type(exc).__name__}")
            else:
                print(f"PUBLISH_PLATFORM_FAILED id={pid} platform=telegram reason=missing_secret")

            if BALE_BOT_TOKEN and BALE_CHANNEL_ID:
                attempts["bale"] = 1
                try:
                    results["bale"] = _send_platform_photo("bale", item, image_bytes, button_url)
                    statuses["bale"] = "sent"
                except Exception as exc:
                    print(f"PUBLISH_PLATFORM_FAILED id={pid} platform=bale error={type(exc).__name__}")
            else:
                print(
                    f"PUBLISH_PLATFORM_FAILED id={pid} platform=bale "
                    f"reason=missing_{'BALE_BOT_TOKEN' if not BALE_BOT_TOKEN else 'BALE_CHANNEL_ID'}"
                )

            succeeded = any(value == "sent" for value in statuses.values())
            if not succeeded:
                print(f"PUBLISH_FAILED id={pid} reason=all_platforms_failed")
                defer_pending_publication(state, pid, "all_platforms_failed", datetime.now(timezone.utc))
                save_json(STATE, state)
                continue

            expiry_at = str(item.get("deal_expires_at") or "").strip()
            published_at_epoch = time.time()
            record = {
                "ts": published_at_epoch,
                "title": item["title"],
                "product_url": item["product_url"],
                "image_url": item.get("image_url", ""),
                "video_generation_status": "pending",
                "youtube_upload_status": "pending",
                "click_tracking_url": "",
                "telegram_message_id": results.get("telegram", {}).get("message_id"),
                "bale_message_id": results.get("bale", {}).get("message_id"),
                "delivery_version": 1,
                "delivery_status": statuses,
                "delivery_attempts": attempts,
                "expires_at": expiry_at,
                "expiry_source": str(item.get("expiry_source") or "unavailable"),
                "expiry_estimated": bool(item.get("expiry_estimated")),
                "expiry_deadline_verified_directly": (
                    item.get("expiry_deadline_verified_directly") is True
                    and str(item.get("expiry_source") or "") in {
                        "digikala_live_deals_feed", "digikala_product_detail_api"
                    }
                ),
                "expiry_deadline_verified_from_site_card": (
                    item.get("expiry_deadline_verified_from_site_card") is True
                    and str(item.get("expiry_source") or "") == "digikala_mcp_offer_card"
                ),
                "caption_deadline_format_version": CAPTION_DEADLINE_FORMAT_VERSION,
                "posted_discount_percent": int(item.get("discount_percent") or 0),
                "posted_current_price": int(item.get("current_price") or 0),
                "posted_original_price": int(item.get("original_price") or 0),
                "demand_score": int(item.get("demand_score") or 0),
                "current_demand_verified": item.get("current_demand_verified") is True,
                "current_demand_score": int(item.get("current_demand_score") or 0),
                "recent_review_growth_7d": int(item.get("recent_review_growth_7d") or 0),
                "demand_window_hours": float(item.get("demand_window_hours") or 0),
                "demand_observed_at": str(item.get("demand_observed_at") or ""),
                "demand_signal_source": str(item.get("demand_signal_source") or ""),
                "historical_popularity_score": int(item.get("historical_popularity_score") or 0),
                "promo_score": int(item.get("promo_score") or 0),
                "click_count_30d": int(item.get("click_count_30d") or 0),
            }
            failed_ready_platforms = _delivery_retry_platforms(record)
            if failed_ready_platforms:
                max_attempt = max(int(attempts.get(platform, 1) or 1) for platform in failed_ready_platforms)
                record["delivery_retry_after"] = time.time() + _delivery_retry_delay(max_attempt)
            # Preserve prior IDs so new campaigns cannot orphan old channel posts.
            old_history = [
                entry for entry in old.get("post_history", [])
                if isinstance(entry, dict)
            ] if isinstance(old, dict) and isinstance(old.get("post_history"), list) else []
            if isinstance(old, dict) and old:
                previous_snapshot = dict(old)
                previous_snapshot.pop("post_history", None)
                old_history.append(previous_snapshot)
            if old_history:
                record["post_history"] = old_history[-12:]
            state["published"][pid] = record
            ensure_publication_ledger(state)
            category, family, brand = _publication_diversity_group(item)
            history = state.setdefault("recent_publications", [])
            if not isinstance(history, list):
                history = []
                state["recent_publications"] = history
            history.append({
                "ts": published_at_epoch,
                "product_id": pid,
                "title": item["title"],
                "category": category,
                "family": family,
                "brand": brand,
                "retailer": _publication_retailer_group(item),
                "telegram_message_id": results.get("telegram", {}).get("message_id"),
                "bale_message_id": results.get("bale", {}).get("message_id"),
            })
            unique_history = {}
            for entry in history:
                if not isinstance(entry, dict):
                    continue
                entry_ts = _publication_record_ts(entry)
                if not entry_ts:
                    continue
                event_key = _publication_diversity_history_key(entry)
                if event_key is None:
                    continue
                previous_entry = unique_history.get(event_key)
                # Stable IDs mean this is the same post even if a maintenance run
                # refreshed its metadata timestamp. Preserve the original post time.
                if previous_entry is None or entry_ts < _publication_record_ts(previous_entry):
                    unique_history[event_key] = entry
            state["recent_publications"] = sorted(
                unique_history.values(), key=_publication_record_ts,
            )[-RECENT_PUBLICATION_HISTORY_LIMIT:]
            actual_post_time = datetime.fromtimestamp(
                published_at_epoch, tz=timezone.utc
            ).isoformat()
            state["last_published_at"] = actual_post_time
            state["last_channel_published_at"] = actual_post_time
            state.setdefault("pending_queue", {}).pop(pid, None)
            save_json(STATE, state)
            print(
                f"PUBLISHED id={pid} "
                f"telegram={statuses['telegram']} "
                f"bale={statuses['bale']} "
                f"score={item['demand_score']} direct_affiliate_link=True"
            )
            sent += 1
            if not all(statuses.get(platform) == "sent" for platform in ("telegram", "bale")):
                missing_platforms = [
                    platform for platform in ("telegram", "bale")
                    if statuses.get(platform) != "sent"
                ]
                print(
                    f"PUBLISH_PARTIAL_DELIVERY id={pid} "
                    f"missing={','.join(missing_platforms)}; future publication continues and failed channel will be retried independently."
                )
        print(f"products_distributed={sent} candidates_attempted={attempted_candidates}")
        if CLEAR_PREVIOUS_CHANNEL_POSTS and BATCH_OPERATION_KEY and sent > 0:
            state["completed_batch_operation"] = BATCH_OPERATION_KEY
            save_json(STATE, state)
            print(f"BATCH_MARKED_COMPLETED key={BATCH_OPERATION_KEY} posts_sent={sent}")

    # Use the same posted-product records for video destinations, and allow enough
    # throughput to keep pace with the channel's two-post backlog bursts. Each destination
    # remains failure-isolated; a failed item is deferred while later candidates can proceed.
    video_items_processed = 0
    while video_items_processed < MAX_SHORT_VIDEOS_PER_RUN:
        if not process_pending_short_video(state):
            break
        video_items_processed += 1
    if video_items_processed:
        print(
            f"SHORT_VIDEO_QUEUE_PROCESSED items={video_items_processed} "
            f"limit={MAX_SHORT_VIDEOS_PER_RUN}"
        )

    # Limit retained product history while preserving most recent entries.
    if isinstance(state.get("published"), dict) and len(state["published"]) > 2000:
        state["published"] = dict(sorted(state["published"].items(), key=lambda kv: float(kv[1].get("ts", 0)))[-2000:])
    save_json(STATE, state)
    return 0 if products or any(d.get("ok") for d in search_diagnostics) else 2


def run_aparat_uploads_only() -> int:
    """Process the persisted video queue for Aparat only; never run product/channel discovery."""
    state = load_state()
    processed = 0
    while processed < MAX_SHORT_VIDEOS_PER_RUN:
        if not process_pending_short_video(
            state,
            output_dir="video_artifacts",
            destinations={"aparat"},
        ):
            break
        processed += 1
        # Each attempt persists state. Reload it so the next item sees the latest
        # per-destination status and reserved upload slot.
        state = load_state()
    print(f"APARAT_ONLY_RUN_SUMMARY processed={processed} max_per_run={MAX_SHORT_VIDEOS_PER_RUN}")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--publish", action="store_true", help="publish at most one eligible item if all checks pass")
    parser.add_argument("--select-only", action="store_true", help="discover, validate and queue selected content without publishing to any platform")
    parser.add_argument(
        "--aparat-upload-only",
        action="store_true",
        help="process pending vertical videos for Aparat only; do not discover products or upload to YouTube",
    )
    parser.add_argument("--dry-run", action="store_true", help="force discovery-only mode")
    parser.add_argument("--setup-growth-invites", action="store_true", help="create source-specific Telegram invite links without running product discovery or publishing offers")
    parser.add_argument(
        "--repair-bale-message-id",
        type=int,
        default=None,
        help="edit one already-published Bale photo caption without publishing a new product",
    )
    parser.add_argument(
        "--repair-all-captions",
        action="store_true",
        help="edit all tracked Telegram and Bale captions in place; never publish new products",
    )
    parser.add_argument(
        "--repair-recent-captions",
        type=int,
        default=None,
        help="edit only the newest N active Telegram/Bale product posts in place; never publish new products",
    )
    parser.add_argument(
        "--refresh-countdowns",
        action="store_true",
        help="refresh remaining-hours/minutes timers on active deadline-verified posts",
    )
    parser.add_argument(
        "--repair-persian-video-text",
        action="store_true",
        help="safely replace the two recent YouTube Shorts whose Persian text layout was broken",
    )
    args = parser.parse_args()
    if args.aparat_upload_only:
        try:
            sys.exit(run_aparat_uploads_only())
        except Exception as exc:
            print(f"APARAT_ONLY_RUN_FAILED error={type(exc).__name__}")
            sys.exit(1)
    if args.setup_growth_invites:
        state = load_state()
        try:
            changed = ensure_telegram_source_invites(state)
            counts_changed = record_daily_member_count_snapshot(state)
            if changed or counts_changed:
                save_json(STATE, state)
            links = state.get("growth_tracking", {}).get("telegram_invite_links", {})
            ready = sum(
                1 for value in links.values()
                if isinstance(value, dict) and str(value.get("url") or "").startswith("https://t.me/")
            ) if isinstance(links, dict) else 0
            daily = state.get("growth_tracking", {}).get("daily_member_counts", {})
            todays = daily.get(datetime.now(IRAN_TIMEZONE).date().isoformat(), {}) if isinstance(daily, dict) else {}
            counts_ready = sum(1 for key in ("telegram", "bale") if isinstance(todays, dict) and key in todays)
            print(f"GROWTH_INVITE_SETUP_SUMMARY ready={ready} required={len(GROWTH_TRACKING_INVITE_SOURCES)} changed={changed} member_counts_today={counts_ready}/2")
            sys.exit(0 if ready == len(GROWTH_TRACKING_INVITE_SOURCES) else 1)
        except Exception as exc:
            print(f"GROWTH_INVITE_SETUP_ABORTED error={type(exc).__name__}")
            sys.exit(1)
    if args.refresh_countdowns:
        try:
            sys.exit(refresh_active_countdowns())
        except Exception as exc:
            print(f"COUNTDOWN_REFRESH_FAILED error={type(exc).__name__}")
            sys.exit(1)
    if args.repair_persian_video_text:
        try:
            sys.exit(repair_persian_text_video_uploads())
        except Exception as exc:
            print(f"PERSIAN_TEXT_VIDEO_REPAIR_ABORTED error={type(exc).__name__} detail={str(exc)[:240]!r}")
            sys.exit(1)
    if args.repair_recent_captions is not None:
        try:
            sys.exit(repair_all_published_captions(max_products=args.repair_recent_captions))
        except Exception as exc:
            print(f"RECENT_CAPTION_REPAIR_FAILED error={type(exc).__name__}")
            sys.exit(1)
    if args.repair_all_captions:
        try:
            sys.exit(repair_all_published_captions())
        except Exception as exc:
            print(f"CAPTION_REPAIR_FAILED error={type(exc).__name__}")
            sys.exit(1)
    if args.repair_bale_message_id is not None:
        try:
            sys.exit(repair_bale_caption(args.repair_bale_message_id))
        except Exception as exc:
            # Do not print request URLs because they can contain the private Bale bot token.
            print(f"BALE_CAPTION_REPAIR_FAILED message_id={args.repair_bale_message_id} error={type(exc).__name__}")
            sys.exit(1)
    publish = (AUTOPUBLISH or args.publish) and not args.dry_run
    sys.exit(run(publish=publish, selection_only=args.select_only))


if __name__ == "__main__":
    main()

